INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C1','math',5,2,'u4',2,'소수의 10배·⟨1/10⟩ — 10배 하면 소수점이 오른쪽으로, ⟨1/10⟩ 하면 왼쪽으로 한 자리 옮겨짐을 되짚고, 길이의 차이는 뺄셈·같은 양이 여러 개면 곱셈식으로 적어야 함을 가리기',ARRAY['6수01-13']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C2','math',5,2,'u4',2,'(소수 한 자리)×(자연수) — 수직선에서 같은 소수씩 뛰어 세기·0.1의 개수·분수의 곱셈(⟨12/10⟩ × 4)·자연수의 곱셈(12 × 4의 ⟨1/10⟩배)으로 계산하고, 곱이 어느 두 자연수 사이에 있어야 하는지 어림하기',ARRAY['6수01-13']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C3','math',5,2,'u4',3,'(소수 두 자리)×(자연수) — 분수(⟨24/100⟩ × 3)나 자연수의 곱셈(24 × 3의 ⟨1/100⟩배)으로 계산하고, 계산 전에 어림한 값과 견주어 소수점을 너무 왼쪽·오른쪽에 찍은 오류를 찾기',ARRAY['6수01-13']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C4','math',5,2,'u4',4,'(자연수)×(소수 한 자리) — 「2의 0.8배」는 2를 똑같이 10으로 나눈 것 중의 8임을 알고 분수·자연수의 곱셈으로 계산하며, 곱하는 수가 1보다 작으면 곱이 처음 수보다 작고 1보다 크면 커짐을 계산 전에 가리기',ARRAY['6수01-13']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C5','math',5,2,'u4',5,'(자연수)×(소수 두 자리) — 6 × 0.38을 6 × 38의 ⟨1/100⟩배로 계산하고, 곱하는 수가 1보다 작으면 곱이 처음 수보다 작아야 함을 어림으로 확인하며 자리를 바꾸어 계산해도 곱이 같음을 알기',ARRAY['6수01-13']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C6','math',5,2,'u4',6,'(소수 한 자리)×(소수 한 자리) — 1을 100칸으로 나눈 넓이 모델에서 한 칸이 0.01임을 알고 칠한 칸 수로 곱을 구하며, 두 수가 모두 ⟨1/10⟩배이면 곱은 자연수의 곱의 ⟨1/100⟩배임을 알기',ARRAY['6수01-13']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C7','math',5,2,'u4',7,'자릿수가 다른 소수끼리의 곱셈 — 0.47 × 0.3처럼 ⟨1/100⟩배와 ⟨1/10⟩배이면 곱은 ⟨1/1000⟩배임을 알고, 끝자리 0을 생략하며, 계산하기 전에 어림하여 곱이 기준보다 큰지 작은지 가리기',ARRAY['6수01-13']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C8','math',5,2,'u4',8,'곱의 소수점 위치 — 10·100·1000을 곱하면 소수점이 오른쪽으로, 0.1·0.01·0.001을 곱하면 왼쪽으로 그 0의 개수만큼 옮겨지고, 소수끼리의 곱은 자연수의 곱에서 두 수의 소수점 아래 자릿수의 합만큼 왼쪽으로 옮긴 자리임을 알기',ARRAY['6수01-13']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C9','math',5,2,'u4',9,'문제 해결 — 표에서 한 사람의 효과와 실천한 사람 수를 읽고, 반 전체의 효과(한 사람 효과 × 사람 수)를 어림셈으로 먼저 견준 뒤 계산으로 확인하며, 한 사람 효과나 사람 수 하나만 보고 판단하면 안 됨을 알기',ARRAY['6수01-13']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X01','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'곱의 소수점을 찍지 않고 자연수의 곱을 그대로 쓴다(1.2 × 4를 48로)','소수점을 꼭 찍어요 — 어림하면 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X02','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C7']::text[],'곱의 소수점을 한 자리 이상 잘못 찍어 곱을 10배 크게 또는 ⟨1/10⟩배 작게 쓴다(1.35 × 4를 0.540으로)','어림한 값과 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X03','math',5,'u4',ARRAY['M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C8']::text[],'소수끼리 곱할 때 한 수의 소수점 아래 자릿수만 세어 곱의 소수점을 찍는다(75.9 × 0.6을 455.4로)','두 수의 소수점 아래 자릿수를 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X04','math',5,'u4',ARRAY['M5-2-u4-C3','M5-2-u4-C5','M5-2-u4-C7']::text[],'끝자리 0을 생략하면서 다른 자리의 숫자까지 지우거나 0을 지운 뒤 소수점 위치를 바꾼다','끝자리 0만 생략해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X05','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3']::text[],'같은 소수를 여러 번 더하는 것을 곱셈식으로 세우지 못하고 소수와 자연수를 더한다(1.5를 세 번 더한 것을 1.5 + 3으로)','같은 수를 여러 번 더하면 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X06','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'곱하면 언제나 커진다고 여긴다(1보다 작은 소수를 곱해도 커진다고 본다)','1보다 작은 수를 곱하면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X07','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C7']::text[],'곱의 크기를 어림할 때 곱하는 수와 1을 견주지 않고 곱해지는 수나 자리 수만 본다','곱하는 수를 1과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X08','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'소수를 분수로 바꿀 때 분모를 잘못 쓴다(0.24를 ⟨24/10⟩로, 1.2를 ⟨12/100⟩로)','소수 한 자리는 분모 10, 두 자리는 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X09','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C6']::text[],'0.1·0.01이 몇 개인지 셀 때 개수를 10배 또는 ⟨1/10⟩로 잘못 센다(0.3을 0.1이 30개로)','0.3은 0.1이 3개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X10','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C8']::text[],'10·100을 곱할 때 소수점을 왼쪽으로, 0.1·0.01을 곱할 때 오른쪽으로 옮긴다(방향을 거꾸로 한다)','10배는 오른쪽, ⟨1/10⟩배는 왼쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X11','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C8']::text[],'소수점을 옮기는 자리 수를 잘못 센다(100을 곱하는데 한 자리만 옮긴다)','0의 개수만큼 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X12','math',5,'u4',ARRAY['M5-2-u4-C7','M5-2-u4-C8']::text[],'곱의 자릿수가 모자랄 때 빈 자리를 0으로 채우지 않는다(0.09 × 0.07을 0.063으로)','모자란 자리는 0으로 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X13','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C9']::text[],'자연수의 곱셈(또는 뺄셈)을 잘못 계산한다','세로셈으로 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X14','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C9']::text[],'어림한 값을 정확한 값처럼 쓰거나, 「적어도 몇 개」에서 모자라는 수를 답으로 고른다','어림은 크기 가리기용 — 모자라면 하나 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X15','math',5,'u4',ARRAY['M5-2-u4-C9']::text[],'반 전체의 효과를 견줄 때 한 사람의 효과나 실천한 사람 수 하나만 보고 판단한다','효과 × 사람 수로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X16','math',5,'u4',ARRAY['M5-2-u4-C5','M5-2-u4-C9']::text[],'시간·단위를 소수로 바꿀 때 잘못 바꾼다(1시간 30분을 1.3시간으로)','30분 = 0.5시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X17','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'「몇 배」를 구할 때 곱셈 대신 덧셈을 한다(1.5 m의 1.2배를 2.7 m로)','「몇 배」는 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X18','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C8','M5-2-u4-C9']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔바른, 큰↔작은, 몇 자리↔몇 개','물음의 「잘못·가장·몇 자리」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X20','math',5,'u4',ARRAY['M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C8']::text[],'곱의 크기를 견줄 때 소수점 위치를 보지 않고 소수점을 뗀 숫자(자연수의 곱)만 보아 같다·크다고 판단한다(0.28 × 5.6과 2.8 × 5.6을 같은 곱으로 봄)','소수점 위치를 기준으로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#1','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','3.4의 ⟨1/10⟩은 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"3.4의 ⟨1/10⟩은 얼마인가요?","options":[{"t":"0.34","correct":true},{"t":"34","mis":"M5-2-u4-X10"},{"t":"0.034","mis":"M5-2-u4-X11"},{"t":"0.0034","mis":"M5-2-u4-X11"}],"explanation":["⟨1/10⟩ 할 때마다 소수점이 왼쪽으로 한 자리씩 옮겨져요.","⟨1/10⟩은 소수점을 왼쪽으로 한 자리 옮겨요.","3.4의 ⟨1/10⟩은 0.34예요."],"variant_rule":{"alt":[{"stem":"3.4의 ⟨1/100⟩은 얼마인가요?","options":[{"t":"0.034","correct":true},{"t":"340","mis":"M5-2-u4-X10"},{"t":"0.0034","mis":"M5-2-u4-X11"},{"t":"0.34","mis":"M5-2-u4-X11"}],"explanation":["⟨1/10⟩ 할 때마다 소수점이 왼쪽으로 한 자리씩 옮겨져요.","⟨1/100⟩은 소수점을 왼쪽으로 두 자리 옮겨요.","3.4의 ⟨1/100⟩은 0.034예요."]},{"stem":"0.034의 100배는 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"0.00034","mis":"M5-2-u4-X10"},{"t":"34","mis":"M5-2-u4-X11"},{"t":"0.34","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","100배는 소수점을 오른쪽으로 두 자리 옮겨요.","0.034 × 100 = 3.4예요."]},{"stem":"1.8의 10배는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"0.18","mis":"M5-2-u4-X10"},{"t":"180","mis":"M5-2-u4-X11"},{"t":"1800","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","1.8 × 10 = 18이에요."]},{"stem":"0.123의 100배는 얼마인가요?","options":[{"t":"12.3","correct":true},{"t":"0.00123","mis":"M5-2-u4-X10"},{"t":"123","mis":"M5-2-u4-X11"},{"t":"1.23","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","100배는 소수점을 오른쪽으로 두 자리 옮겨요.","0.123 × 100 = 12.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#2','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','1.5 + 1.5 + 1.5를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X05','M5-2-u4-X01']::text[],true,'{"seq":2,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"1.5 + 1.5 + 1.5를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"1.5 × 3","correct":true},{"t":"1.5 × 4","mis":"M5-2-u4-X18"},{"t":"1.5 + 3","mis":"M5-2-u4-X05"},{"t":"15 × 3","mis":"M5-2-u4-X01"}],"explanation":["1.5를 3번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","1.5 + 1.5 + 1.5 = 1.5 × 3 = 4.5예요."],"variant_rule":{"alt":[{"stem":"0.3 + 0.3 + 0.3 + 0.3 + 0.3을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"0.3 × 5","correct":true},{"t":"0.3 × 6","mis":"M5-2-u4-X18"},{"t":"0.3 + 5","mis":"M5-2-u4-X05"},{"t":"3 × 5","mis":"M5-2-u4-X01"}],"explanation":["0.3을 5번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","0.3 + 0.3 + 0.3 + 0.3 + 0.3 = 0.3 × 5 = 1.5예요."]},{"stem":"0.4 + 0.4 + 0.4 + 0.4를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"0.4 × 4","correct":true},{"t":"0.4 × 5","mis":"M5-2-u4-X18"},{"t":"0.4 + 4","mis":"M5-2-u4-X05"},{"t":"4 × 4","mis":"M5-2-u4-X01"}],"explanation":["0.4를 4번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","0.4 + 0.4 + 0.4 + 0.4 = 0.4 × 4 = 1.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#3','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',1,'mc','auto','수직선의 0에서 0.3씩 5번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C2","difficulty":1,"kind":"mc","stem":"수직선의 0에서 0.3씩 5번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"1.5","correct":true},{"t":"15","mis":"M5-2-u4-X01"},{"t":"5.3","mis":"M5-2-u4-X05"},{"t":"1.8","mis":"M5-2-u4-X18"}],"explanation":["0.3씩 5번 뛰어 세는 것은 0.3을 5번 더한 것이에요.","0.3 × 5 = 0.3 + 0.3 + 0.3 + 0.3 + 0.3이에요.","0.3 + 0.3 + 0.3 + 0.3 + 0.3 = 1.5 — 수직선에서 1.5에 닿아요."],"asset":{"type":"number_line","cells":["0","0.3","0.6","0.9","1.2","?"]},"variant_rule":{"alt":[{"stem":"수직선의 0에서 0.4씩 4번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"16","mis":"M5-2-u4-X01"},{"t":"4.4","mis":"M5-2-u4-X05"},{"t":"2","mis":"M5-2-u4-X18"}],"explanation":["0.4씩 4번 뛰어 세는 것은 0.4를 4번 더한 것이에요.","0.4 × 4 = 0.4 + 0.4 + 0.4 + 0.4예요.","0.4 + 0.4 + 0.4 + 0.4 = 1.6 — 수직선에서 1.6에 닿아요."],"asset":{"type":"number_line","cells":["0","0.4","0.8","1.2","?"]}},{"stem":"수직선의 0에서 0.6씩 3번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"1.8","correct":true},{"t":"18","mis":"M5-2-u4-X01"},{"t":"3.6","mis":"M5-2-u4-X05"},{"t":"2.4","mis":"M5-2-u4-X18"}],"explanation":["0.6씩 3번 뛰어 세는 것은 0.6을 3번 더한 것이에요.","0.6 × 3 = 0.6 + 0.6 + 0.6이에요.","0.6 + 0.6 + 0.6 = 1.8 — 수직선에서 1.8에 닿아요."],"asset":{"type":"number_line","cells":["0","0.6","1.2","?"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#4','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','어린이 안전 체험관에서 소방 호스 사용 체험을 해요. 왼쪽 호스의 길이는 3.2 m, 오른쪽 호스의 길이는 1.5 m예요. 왼쪽 호스는 오른쪽 호스보다 몇 m 더 긴가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X13','M5-2-u4-X02']::text[],true,'{"seq":4,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"어린이 안전 체험관에서 소방 호스 사용 체험을 해요. 왼쪽 호스의 길이는 3.2 m, 오른쪽 호스의 길이는 1.5 m예요. 왼쪽 호스는 오른쪽 호스보다 몇 m 더 긴가요?","options":[{"t":"1.7 m","correct":true},{"t":"4.7 m","mis":"M5-2-u4-X18"},{"t":"2.3 m","mis":"M5-2-u4-X13"},{"t":"17 m","mis":"M5-2-u4-X02"}],"explanation":["길이의 차이는 뺄셈으로 구해요.","소수점을 맞추어 빼요 — 3.2 − 1.5 = 1.7이에요.","그래서 1.7 m 더 길어요."],"variant_rule":{"alt":[{"stem":"9.1 − 3.6을 계산하면 얼마인가요?","options":[{"t":"5.5","correct":true},{"t":"12.7","mis":"M5-2-u4-X18"},{"t":"6.5","mis":"M5-2-u4-X13"},{"t":"55","mis":"M5-2-u4-X02"}],"explanation":["차이는 뺄셈으로 구해요.","소수점을 맞추어 같은 자리끼리 빼요 — 9.1 − 3.6 = 5.5예요.","그래서 5.5예요."]},{"stem":"고구마가 들어 있는 상자의 무게는 5.28 kg이에요. 상자의 무게가 0.74 kg일 때 고구마의 무게는 몇 kg인가요?","options":[{"t":"4.54 kg","correct":true},{"t":"6.02 kg","mis":"M5-2-u4-X18"},{"t":"5.54 kg","mis":"M5-2-u4-X13"},{"t":"45.4 kg","mis":"M5-2-u4-X02"}],"explanation":["차이는 뺄셈으로 구해요.","소수점을 맞추어 같은 자리끼리 빼요 — 5.28 − 0.74 = 4.54예요.","그래서 4.54 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#5','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','1.2 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":5,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.2 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨12/10⟩ × 4","correct":true},{"t":"⟨12/100⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/12⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨12/10⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.2 = ⟨12/10⟩예요.","⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요."],"variant_rule":{"alt":[{"stem":"0.3 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨3/10⟩ × 5","correct":true},{"t":"⟨3/100⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨1/3⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨3/10⟩ × ⟨5/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.3 = ⟨3/10⟩이에요.","⟨3/10⟩ × 5 = ⟨15/10⟩ = 1.5예요."]},{"stem":"0.9 × 8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨9/10⟩ × 8","correct":true},{"t":"⟨9/100⟩ × 8","mis":"M5-2-u4-X08"},{"t":"⟨1/9⟩ × 8","mis":"M5-2-u4-X08"},{"t":"⟨9/10⟩ × ⟨8/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.9 = ⟨9/10⟩예요.","⟨9/10⟩ × 8 = ⟨72/10⟩ = 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#6','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','12 × 4 = 48이에요. 1.2 × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"12 × 4 = 48이에요. 1.2 × 4를 계산하면 얼마인가요?","options":[{"t":"4.8","correct":true},{"t":"48","mis":"M5-2-u4-X01"},{"t":"0.48","mis":"M5-2-u4-X02"},{"t":"480","mis":"M5-2-u4-X02"}],"explanation":["1.2와 4의 소수점 아래 자릿수는 1개와 0개예요.","1 + 0 = 1 — 48에서 소수점을 왼쪽으로 한 자리 옮겨요.","1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"4 × 7 = 28이에요. 0.4 × 7을 계산하면 얼마인가요?","options":[{"t":"2.8","correct":true},{"t":"28","mis":"M5-2-u4-X01"},{"t":"0.28","mis":"M5-2-u4-X02"},{"t":"280","mis":"M5-2-u4-X02"}],"explanation":["0.4와 7의 소수점 아래 자릿수는 1개와 0개예요.","1 + 0 = 1 — 28에서 소수점을 왼쪽으로 한 자리 옮겨요.","0.4 × 7 = 2.8이에요."]},{"stem":"82 × 6 = 492예요. 8.2 × 6을 계산하면 얼마인가요?","options":[{"t":"49.2","correct":true},{"t":"492","mis":"M5-2-u4-X01"},{"t":"4.92","mis":"M5-2-u4-X02"},{"t":"4920","mis":"M5-2-u4-X02"}],"explanation":["8.2와 6의 소수점 아래 자릿수는 1개와 0개예요.","1 + 0 = 1 — 492에서 소수점을 왼쪽으로 한 자리 옮겨요.","8.2 × 6 = 49.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#7','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','0.9 × 8을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"0.9 × 8을 계산하면 얼마인가요?","options":[{"t":"7.2","correct":true},{"t":"72","mis":"M5-2-u4-X01"},{"t":"0.72","mis":"M5-2-u4-X02"},{"t":"720","mis":"M5-2-u4-X02"}],"explanation":["9 × 8 = 72예요.","0.9는 9의 ⟨1/10⟩배이므로 곱도 72의 ⟨1/10⟩배예요.","0.9 × 8 = 7.2예요."],"asset":{"type":"expr_grid","rows":[["","0.","9"],["×","","8"],["","?","?"]]},"variant_rule":{"alt":[{"stem":"1.7 × 15를 계산하면 얼마인가요?","options":[{"t":"25.5","correct":true},{"t":"255","mis":"M5-2-u4-X01"},{"t":"2.55","mis":"M5-2-u4-X02"},{"t":"2550","mis":"M5-2-u4-X02"}],"explanation":["17 × 15 = 255예요.","1.7은 17의 ⟨1/10⟩배이므로 곱도 255의 ⟨1/10⟩배예요.","1.7 × 15 = 25.5예요."],"asset":{"type":"expr_grid","rows":[["","","1.","7"],["×","","1","5"],["","?","?","?"]]}},{"stem":"8.2 × 6을 계산하면 얼마인가요?","options":[{"t":"49.2","correct":true},{"t":"492","mis":"M5-2-u4-X01"},{"t":"4.92","mis":"M5-2-u4-X02"},{"t":"4920","mis":"M5-2-u4-X02"}],"explanation":["82 × 6 = 492예요.","8.2는 82의 ⟨1/10⟩배이므로 곱도 492의 ⟨1/10⟩배예요.","8.2 × 6 = 49.2예요."],"asset":{"type":"expr_grid","rows":[["","","8.","2"],["×","","","6"],["","?","?","?"]]}},{"stem":"3.2 × 7을 계산하면 얼마인가요?","options":[{"t":"22.4","correct":true},{"t":"224","mis":"M5-2-u4-X01"},{"t":"2.24","mis":"M5-2-u4-X02"},{"t":"2240","mis":"M5-2-u4-X02"}],"explanation":["32 × 7 = 224예요.","3.2는 32의 ⟨1/10⟩배이므로 곱도 224의 ⟨1/10⟩배예요.","3.2 × 7 = 22.4예요."],"asset":{"type":"expr_grid","rows":[["","","3.","2"],["×","","","7"],["","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#8','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','농장에서 캔 고구마를 상자 1개에 1.4 kg씩 담았어요. 상자 3개에 담은 고구마는 모두 몇 kg인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":8,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"농장에서 캔 고구마를 상자 1개에 1.4 kg씩 담았어요. 상자 3개에 담은 고구마는 모두 몇 kg인가요?","options":[{"t":"4.2 kg","correct":true},{"t":"4.4 kg","mis":"M5-2-u4-X17"},{"t":"42 kg","mis":"M5-2-u4-X01"},{"t":"0.42 kg","mis":"M5-2-u4-X02"}],"explanation":["같은 무게 1.4 kg이 3상자 있으니 식은 1.4 × 3이에요.","14 × 3 = 42예요. 곱은 그 ⟨1/10⟩배예요.","1.4 × 3 = 4.2 — 4.2 kg이에요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 0.6 m인 정삼각형의 둘레는 몇 m인가요?","options":[{"t":"1.8 m","correct":true},{"t":"18 m","mis":"M5-2-u4-X01"},{"t":"3.6 m","mis":"M5-2-u4-X05"},{"t":"0.18 m","mis":"M5-2-u4-X02"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 3이에요.","0.6 × 3 = 1.8 — 둘레는 1.8 m예요."]},{"stem":"한 변의 길이가 5.1 cm인 정사각형의 둘레는 몇 cm인가요?","options":[{"t":"20.4 cm","correct":true},{"t":"204 cm","mis":"M5-2-u4-X01"},{"t":"9.1 cm","mis":"M5-2-u4-X05"},{"t":"2.04 cm","mis":"M5-2-u4-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 4예요.","5.1 × 4 = 20.4 — 둘레는 20.4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#9','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'sa','auto','0.3 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"sa","stem":"0.3 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["0.3은 0.1이 3개예요.","이 묶음이 4개이므로 0.1이 3 × 4 = 12개예요.","그래서 0.3 × 4 = 1.2예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.3 × 5를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["0.3은 0.1이 3개예요.","이 묶음이 5개이므로 0.1이 3 × 5 = 15개예요.","그래서 0.3 × 5 = 1.5예요."]},{"stem":"0.4 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["0.4는 0.1이 4개예요.","이 묶음이 4개이므로 0.1이 4 × 4 = 16개예요.","그래서 0.4 × 4 = 1.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_basic#10','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',3,'mc','auto','기념품으로 1.5 kg인 소화기를 3개 받았어요. 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?',ARRAY['M5-2-u4-X13','M5-2-u4-X18','M5-2-u4-X05']::text[],true,'{"seq":10,"concept":"M5-2-u4-C1","difficulty":3,"kind":"mc","stem":"기념품으로 1.5 kg인 소화기를 3개 받았어요. 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?","options":[{"t":"담을 수 없다 — 4.5 kg은 4 kg보다 무겁다","correct":true},{"t":"담을 수 있다 — 4.5 kg은 4 kg보다 가볍다","mis":"M5-2-u4-X13"},{"t":"담을 수 있다 — 소화기가 3개뿐이다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 곱셈을 아직 안 배웠다","mis":"M5-2-u4-X05"}],"explanation":["소화기 3개의 무게는 1.5 × 3 = 4.5(kg)이에요.","4.5와 4를 견주어요.","4.5 > 4 — 그래서 담을 수 없어요."],"variant_rule":{"alt":[{"stem":"가을 운동회에서 반 친구들과 나누어 마시려고 보리차 7 L를 준비하려고 해요. 한 병에 1.8 L인 보리차를 4병 사면 충분할까요?","options":[{"t":"충분하다 — 보리차 4병은 7.2 L로 7 L보다 많다","correct":true},{"t":"부족하다 — 보리차 4병은 0.72 L뿐이다","mis":"M5-2-u4-X02"},{"t":"부족하다 — 1.8 + 4 = 5.8(L)이다","mis":"M5-2-u4-X05"},{"t":"알 수 없다 — 곱셈으로는 구할 수 없다","mis":"M5-2-u4-X18"}],"explanation":["보리차 4병의 양은 1.8 × 4예요.","18 × 4 = 72의 ⟨1/10⟩배 — 1.8 × 4 = 7.2(L)예요.","7.2 > 7이므로 충분해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#1','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',2,'mc','auto','1.7 × 15를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.7 × 15를 계산하면 얼마인가요?","options":[{"t":"25.5","correct":true},{"t":"255","mis":"M5-2-u4-X01"},{"t":"2.55","mis":"M5-2-u4-X02"},{"t":"2550","mis":"M5-2-u4-X02"}],"explanation":["17 × 15 = 255예요.","1.7은 17의 ⟨1/10⟩배이므로 곱도 255의 ⟨1/10⟩배예요.","1.7 × 15 = 25.5예요."],"variant_rule":{"alt":[{"stem":"1.1 × 15를 계산하면 얼마인가요?","options":[{"t":"16.5","correct":true},{"t":"165","mis":"M5-2-u4-X01"},{"t":"1.65","mis":"M5-2-u4-X02"},{"t":"1650","mis":"M5-2-u4-X02"}],"explanation":["11 × 15 = 165예요.","1.1은 11의 ⟨1/10⟩배이므로 곱도 165의 ⟨1/10⟩배예요.","1.1 × 15 = 16.5예요."]},{"stem":"0.8 × 8을 계산하면 얼마인가요?","options":[{"t":"6.4","correct":true},{"t":"64","mis":"M5-2-u4-X01"},{"t":"0.64","mis":"M5-2-u4-X02"},{"t":"640","mis":"M5-2-u4-X02"}],"explanation":["8 × 8 = 64예요.","0.8은 8의 ⟨1/10⟩배이므로 곱도 64의 ⟨1/10⟩배예요.","0.8 × 8 = 6.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#2','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',2,'mc','auto','1.2 × 4의 곱은 어느 두 수 사이에 있나요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X14']::text[],true,'{"seq":2,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.2 × 4의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"4와 8 사이","correct":true},{"t":"40과 80 사이","mis":"M5-2-u4-X01"},{"t":"0.4와 0.8 사이","mis":"M5-2-u4-X02"},{"t":"8과 12 사이","mis":"M5-2-u4-X14"}],"explanation":["1.2는 1과 2 사이의 수예요.","1 × 4 = 4, 2 × 4 = 8이에요.","그래서 곱은 4와 8 사이 — 실제로 1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"1.7 × 15의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"15와 30 사이","correct":true},{"t":"150과 300 사이","mis":"M5-2-u4-X01"},{"t":"1.5와 3 사이","mis":"M5-2-u4-X02"},{"t":"30과 45 사이","mis":"M5-2-u4-X14"}],"explanation":["1.7은 1과 2 사이의 수예요.","1 × 15 = 15, 2 × 15 = 30이에요.","그래서 곱은 15와 30 사이 — 실제로 1.7 × 15 = 25.5예요."]},{"stem":"1.4 × 3의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"3과 6 사이","correct":true},{"t":"30과 60 사이","mis":"M5-2-u4-X01"},{"t":"0.3과 0.6 사이","mis":"M5-2-u4-X02"},{"t":"6과 9 사이","mis":"M5-2-u4-X14"}],"explanation":["1.4는 1과 2 사이의 수예요.","1 × 3 = 3, 2 × 3 = 6이에요.","그래서 곱은 3과 6 사이 — 실제로 1.4 × 3 = 4.2예요."]},{"stem":"8.2 × 6의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"48과 54 사이","correct":true},{"t":"480과 540 사이","mis":"M5-2-u4-X01"},{"t":"4.8과 5.4 사이","mis":"M5-2-u4-X02"},{"t":"42와 48 사이","mis":"M5-2-u4-X14"}],"explanation":["8.2는 8과 9 사이의 수예요.","8 × 6 = 48, 9 × 6 = 54예요.","그래서 곱은 48과 54 사이 — 실제로 8.2 × 6 = 49.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#3','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'error','auto','1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C2","difficulty":3,"kind":"error","stem":"1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 4.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"12 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.2는 1과 2 사이의 수라 곱은 48보다 훨씬 작아야 해요.","12 × 4 = 48은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 4.8이에요."],"variant_rule":{"alt":[{"stem":"0.9 × 8을 72로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 7.2이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"9 × 8을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.9는 0과 1 사이의 수라 곱은 72보다 훨씬 작아야 해요.","9 × 8 = 72는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 7.2예요."]},{"stem":"8.2 × 6을 492로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 49.2이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"82 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["8.2는 8과 9 사이의 수라 곱은 492보다 훨씬 작아야 해요.","82 × 6 = 492는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 49.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#4','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'mc','auto','한 변의 길이가 5.1 cm인 정사각형의 둘레는 몇 cm인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X02']::text[],true,'{"seq":4,"concept":"M5-2-u4-C2","difficulty":3,"kind":"mc","stem":"한 변의 길이가 5.1 cm인 정사각형의 둘레는 몇 cm인가요?","options":[{"t":"20.4 cm","correct":true},{"t":"204 cm","mis":"M5-2-u4-X01"},{"t":"9.1 cm","mis":"M5-2-u4-X05"},{"t":"2.04 cm","mis":"M5-2-u4-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 4예요.","5.1 × 4 = 20.4 — 둘레는 20.4 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 0.6 m인 정삼각형의 둘레는 몇 m인가요?","options":[{"t":"1.8 m","correct":true},{"t":"18 m","mis":"M5-2-u4-X01"},{"t":"3.6 m","mis":"M5-2-u4-X05"},{"t":"0.18 m","mis":"M5-2-u4-X02"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 3이에요.","0.6 × 3 = 1.8 — 둘레는 1.8 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#5','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'ox','auto','1.2 × 4의 곱은 48이에요.',ARRAY['M5-2-u4-X01']::text[],true,'{"seq":5,"concept":"M5-2-u4-C2","difficulty":3,"kind":"ox","stem":"1.2 × 4의 곱은 48이에요.","answer":"X","reason_options":[{"t":"1.2는 12의 ⟨1/10⟩배이므로 곱은 48의 ⟨1/10⟩배인 4.8이므로","correct":true},{"t":"자연수의 곱셈과 답이 같으므로","mis":"M5-2-u4-X01"}],"mis":"M5-2-u4-X01","explanation":["12 × 4 = 48이에요.","곱해지는 수가 ⟨1/10⟩배이므로 곱도 ⟨1/10⟩배예요.","1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"1.2 × 4의 곱은 4와 8 사이에 있어요.","answer":"O","reason_options":[{"t":"1.2는 1과 2 사이라 곱은 1 × 4 = 4와 2 × 4 = 8 사이이므로","correct":true},{"t":"1.2 × 4는 12 × 4와 곱이 같으므로","mis":"M5-2-u4-X01"}],"explanation":["1 × 4 = 4, 2 × 4 = 8이에요.","1.2는 1과 2 사이의 수예요.","1.2 × 4 = 4.8 — 4와 8 사이에 있어요."]},{"stem":"1.2 × 4 = ⟨12/10⟩ × 4로 계산할 수 있어요.","answer":"O","reason_options":[{"t":"1.2 = ⟨12/10⟩이므로 분수의 곱셈으로 바꿀 수 있으므로","correct":true},{"t":"1.2는 ⟨12/100⟩이므로","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10인 분수예요.","⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요.","그래서 맞아요."]},{"stem":"0.3 × 4는 0.1이 12개예요.","answer":"O","reason_options":[{"t":"0.3은 0.1이 3개이고 이것이 4묶음이므로","correct":true},{"t":"0.3은 0.1이 30개이므로","mis":"M5-2-u4-X09"}],"explanation":["0.3은 0.1이 3개예요.","3 × 4 = 12 — 0.1이 12개예요.","0.3 × 4 = 1.2예요."]},{"stem":"0.9 × 8은 8보다 커요.","answer":"X","reason_options":[{"t":"0.9가 1보다 작아 곱은 1 × 8보다 작으므로","correct":true},{"t":"곱하면 언제나 커지므로","mis":"M5-2-u4-X06"}],"explanation":["1 × 8 = 8이에요.","0.9는 1보다 작으니 곱도 8보다 작아요.","0.9 × 8 = 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#6','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C2","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.9 × 8","r":"7.2"},{"l":"0.4 × 7","r":"2.8"},{"l":"8.2 × 6","r":"49.2"}],"mis":"M5-2-u4-X02","explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.9 × 8 = 7.2 · 0.4 × 7 = 2.8이에요.","8.2 × 6 = 49.2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"1.7 × 15","r":"25.5"},{"l":"0.8 × 8","r":"6.4"},{"l":"3.2 × 7","r":"22.4"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","1.7 × 15 = 25.5 · 0.8 × 8 = 6.4예요.","3.2 × 7 = 22.4예요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"1.1 × 15","r":"16.5"},{"l":"0.3 × 5","r":"1.5"},{"l":"1.4 × 3","r":"4.2"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","1.1 × 15 = 16.5 · 0.3 × 5 = 1.5예요.","1.4 × 3 = 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#7','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'sa','auto','수직선에 0.3 × 5를 나타내려고 해요. 0에서 0.3만큼 뛴 다음, 0.3씩 몇 번 더 뛰어 세어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C2","difficulty":3,"kind":"sa","stem":"수직선에 0.3 × 5를 나타내려고 해요. 0에서 0.3만큼 뛴 다음, 0.3씩 몇 번 더 뛰어 세어야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.3 × 5는 0.3을 5번 더한 것 — 0에서 0.3씩 5번 뛰어 세요.","처음 한 번을 뛰었으니 5 − 1 = 4번 더 뛰어 세어요.","0.3 + 0.3 + 0.3 + 0.3 + 0.3 = 1.5예요."],"mis":"M5-2-u4-X18","asset":{"type":"number_line","cells":["0","0.3","0.6","0.9","1.2","?"]},"variant_rule":{"alt":[{"stem":"수직선에 0.4 × 4를 나타내려고 해요. 0에서 0.4만큼 뛴 다음, 0.4씩 몇 번 더 뛰어 세어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.4 × 4는 0.4를 4번 더한 것 — 0에서 0.4씩 4번 뛰어 세요.","처음 한 번을 뛰었으니 4 − 1 = 3번 더 뛰어 세어요.","0.4 + 0.4 + 0.4 + 0.4 = 1.6이에요."],"asset":{"type":"number_line","cells":["0","0.4","0.8","1.2","?"]}},{"stem":"수직선에 0.6 × 3을 나타내려고 해요. 0에서 0.6만큼 뛴 다음, 0.6씩 몇 번 더 뛰어 세어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.6 × 3은 0.6을 3번 더한 것 — 0에서 0.6씩 3번 뛰어 세요.","처음 한 번을 뛰었으니 3 − 1 = 2번 더 뛰어 세어요.","0.6 + 0.6 + 0.6 = 1.8이에요."],"asset":{"type":"number_line","cells":["0","0.6","1.2","?"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#8','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',4,'essay','teacher','1.2 × 4를 분수의 곱셈과 자연수의 곱셈 두 가지 방법으로 계산하고, 곱을 48로 쓰면 안 되는 까닭을 어림을 이용해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C2","difficulty":4,"kind":"essay","stem":"1.2 × 4를 분수의 곱셈과 자연수의 곱셈 두 가지 방법으로 계산하고, 곱을 48로 쓰면 안 되는 까닭을 어림을 이용해 설명해 보세요.","answer_guide":{"answer":"예: 분수로 — 1.2 = ⟨12/10⟩이므로 ⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이다. 자연수로 — 12 × 4 = 48이고 1.2는 12의 ⟨1/10⟩배이므로 곱도 48의 ⟨1/10⟩배인 4.8이다. 1.2는 1과 2 사이의 수이므로 1.2 × 4는 1 × 4 = 4와 2 × 4 = 8 사이에 있어야 해서 48은 너무 크다.","scoring_points":["분수의 곱셈으로 4.8을 구했는가","자연수의 곱셈과 ⟨1/10⟩배로 4.8을 구했는가","곱이 4와 8 사이여야 해서 48은 틀렸다고 설명했는가"]},"explanation":["⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요.","12 × 4 = 48의 ⟨1/10⟩배는 4.8이에요.","곱은 4와 8 사이에 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#9','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C1',4,'essay','teacher','어린이 안전 체험관에서 기념품으로 1.5 kg인 소화기를 3개 받았어요. 소화기의 무게를 덧셈식과 곱셈식으로 각각 나타내고 모두 몇 kg인지 구해 보세요. 그리고 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C1","difficulty":4,"kind":"essay","stem":"어린이 안전 체험관에서 기념품으로 1.5 kg인 소화기를 3개 받았어요. 소화기의 무게를 덧셈식과 곱셈식으로 각각 나타내고 모두 몇 kg인지 구해 보세요. 그리고 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 덧셈식은 1.5 + 1.5 + 1.5이고 곱셈식은 1.5 × 3이다. 1.5 + 1.5 + 1.5 = 4.5이므로 모두 4.5 kg이다. 4.5 > 4이므로 4 kg까지 담을 수 있는 종이봉투 하나에는 모두 담을 수 없다.","scoring_points":["덧셈식과 곱셈식 1.5 × 3을 모두 썼는가","4.5 kg을 구했는가","4.5 kg이 4 kg보다 무거워 담을 수 없다고 판단했는가"]},"explanation":["1.5 + 1.5 + 1.5 = 1.5 × 3이에요.","1.5 × 3 = 4.5(kg)이에요.","4.5 > 4 — 한 봉투에 다 담을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L02_challenge#10','math',5,2,'u4','L02','tb_g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',4,'essay','teacher','가을 운동회에서 반 친구들과 나누어 마시려고 보리차 7 L를 준비하려고 해요. 한 병에 1.8 L인 보리차를 4병 사면 충분할지 답을 쓰고, 왜 그렇게 생각하는지 이유를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C2","difficulty":4,"kind":"essay","stem":"가을 운동회에서 반 친구들과 나누어 마시려고 보리차 7 L를 준비하려고 해요. 한 병에 1.8 L인 보리차를 4병 사면 충분할지 답을 쓰고, 왜 그렇게 생각하는지 이유를 써 보세요.","answer_guide":{"answer":"예: 충분하다. 보리차 4병의 양은 1.8 × 4로 구한다. 18 × 4 = 72이고 1.8은 18의 ⟨1/10⟩배이므로 1.8 × 4 = 7.2(L)이다. 7.2 > 7이므로 4병을 사면 충분하다.","scoring_points":["식 1.8 × 4를 세웠는가","1.8 × 4 = 7.2(L)를 구했는가","7.2 L가 7 L보다 많아 충분하다고 판단했는가"]},"explanation":["보리차 4병은 1.8 × 4예요.","1.8 × 4 = 7.2(L)예요.","7.2 > 7 — 충분해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#1','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'mc','auto','우리 학교 운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달렸다면 모두 몇 km를 달렸나요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"우리 학교 운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달렸다면 모두 몇 km를 달렸나요?","options":[{"t":"0.72 km","correct":true},{"t":"72 km","mis":"M5-2-u4-X01"},{"t":"0.072 km","mis":"M5-2-u4-X02"},{"t":"7.2 km","mis":"M5-2-u4-X02"}],"explanation":["식은 0.24 × 3이에요.","24 × 3 = 72이고 0.24는 24의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.24 × 3 = 0.72, 0.72 km예요."],"variant_rule":{"alt":[{"stem":"도영이는 매일 4.25 km씩 걷기 운동을 했어요. 도영이가 5일 동안 걸은 거리는 모두 몇 km인가요?","options":[{"t":"21.25 km","correct":true},{"t":"9.25 km","mis":"M5-2-u4-X17"},{"t":"2125 km","mis":"M5-2-u4-X01"},{"t":"212.5 km","mis":"M5-2-u4-X02"}],"explanation":["같은 거리 4.25 km를 5일 걸었으니 식은 4.25 × 5예요.","425 × 5 = 2125예요. 곱은 그 ⟨1/100⟩배예요.","4.25 × 5 = 21.25 — 21.25 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#2','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'mc','auto','0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨24/100⟩ × 3","correct":true},{"t":"⟨24/1000⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨1/24⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨24/100⟩ × ⟨3/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.24 = ⟨24/100⟩예요.","⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요."],"variant_rule":{"alt":[{"stem":"0.59 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨59/100⟩ × 4","correct":true},{"t":"⟨59/1000⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/59⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨59/100⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.59 = ⟨59/100⟩예요.","⟨59/100⟩ × 4 = ⟨236/100⟩ = 2.36이에요."]},{"stem":"4.37 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨437/100⟩ × 5","correct":true},{"t":"⟨437/1000⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨1/437⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨437/100⟩ × ⟨5/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","4.37 = ⟨437/100⟩이에요.","⟨437/100⟩ × 5 = ⟨2185/100⟩ = 21.85예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#3','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'sa','auto','0.24 × 3을 자연수의 곱셈을 이용해 계산하려고 해요. 24 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.24 × 3을 자연수의 곱셈을 이용해 계산하려고 해요. 24 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","24 × 3 = 72예요.","그래서 0.24 × 3 = 0.72예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"4.37 × 5를 자연수의 곱셈을 이용해 계산하려고 해요. 437 × 5는 얼마인가요? 숫자로 쓰세요.","answer":["2185"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","437 × 5 = 2185예요.","그래서 4.37 × 5 = 21.85예요."]},{"stem":"0.59 × 4를 자연수의 곱셈을 이용해 계산하려고 해요. 59 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["236"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","59 × 4 = 236이에요.","그래서 0.59 × 4 = 2.36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#4','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C2',1,'mc','auto','계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 0.9 × 4 ○ 3',ARRAY['M5-2-u4-X20','M5-2-u4-X18']::text[],false,'{"seq":4,"concept":"M5-2-u4-C2","difficulty":1,"kind":"mc","stem":"계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 0.9 × 4 ○ 3","options":[{"t":">","correct":true},{"t":"<","mis":"M5-2-u4-X20"},{"t":"=","mis":"M5-2-u4-X18"}],"explanation":["두 식을 각각 계산해요.","0.9 × 4 = 3.6이에요.","3.6 > 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#5','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','4.37 × 5에서 4.37을 4로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":5,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"4.37 × 5에서 4.37을 4로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"20","correct":true},{"t":"200","mis":"M5-2-u4-X02"},{"t":"25","mis":"M5-2-u4-X13"},{"t":"9","mis":"M5-2-u4-X05"}],"explanation":["4.37을 계산하기 쉬운 수 4로 어림해요.","4 × 5 = 20이에요.","실제 곱 4.37 × 5 = 21.85와 비슷해요 — 소수점 위치를 점검할 수 있어요."],"variant_rule":{"alt":[{"stem":"4.37 × 5에서 4.37을 4.5로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"22.5","correct":true},{"t":"225","mis":"M5-2-u4-X02"},{"t":"27.5","mis":"M5-2-u4-X13"},{"t":"9.5","mis":"M5-2-u4-X05"}],"explanation":["4.37을 계산하기 쉬운 수 4.5로 어림해요.","4.5 × 5 = 22.5예요.","실제 곱 4.37 × 5 = 21.85와 비슷해요 — 소수점 위치를 점검할 수 있어요."]},{"stem":"4.37 × 5에서 4.37을 4.3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"21.5","correct":true},{"t":"215","mis":"M5-2-u4-X02"},{"t":"26.5","mis":"M5-2-u4-X13"},{"t":"9.3","mis":"M5-2-u4-X05"}],"explanation":["4.37을 계산하기 쉬운 수 4.3으로 어림해요.","4.3 × 5 = 21.5예요.","실제 곱 4.37 × 5 = 21.85와 비슷해요 — 소수점 위치를 점검할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#6','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','2.59 × 13을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.59 × 13을 계산하면 얼마인가요?","options":[{"t":"33.67","correct":true},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"336.7","mis":"M5-2-u4-X02"},{"t":"3.367","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배이므로 곱도 3367의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요."],"asset":{"type":"expr_grid","rows":[["","","2.","5","9"],["×","","","1","3"],["","?","?","?","?"]]},"variant_rule":{"alt":[{"stem":"0.14 × 6을 계산하면 얼마인가요?","options":[{"t":"0.84","correct":true},{"t":"84","mis":"M5-2-u4-X01"},{"t":"8.4","mis":"M5-2-u4-X02"},{"t":"0.084","mis":"M5-2-u4-X02"}],"explanation":["14 × 6 = 84예요.","0.14는 14의 ⟨1/100⟩배이므로 곱도 84의 ⟨1/100⟩배예요.","0.14 × 6 = 0.84예요."],"asset":{"type":"expr_grid","rows":[["","0.","1","4"],["×","","","6"],["","?","?","?"]]}},{"stem":"0.84 × 7을 계산하면 얼마인가요?","options":[{"t":"5.88","correct":true},{"t":"588","mis":"M5-2-u4-X01"},{"t":"58.8","mis":"M5-2-u4-X02"},{"t":"0.588","mis":"M5-2-u4-X02"}],"explanation":["84 × 7 = 588이에요.","0.84는 84의 ⟨1/100⟩배이므로 곱도 588의 ⟨1/100⟩배예요.","0.84 × 7 = 5.88이에요."],"asset":{"type":"expr_grid","rows":[["","0.","8","4"],["×","","","7"],["","?","?","?"]]}},{"stem":"4.23 × 8을 계산하면 얼마인가요?","options":[{"t":"33.84","correct":true},{"t":"3384","mis":"M5-2-u4-X01"},{"t":"338.4","mis":"M5-2-u4-X02"},{"t":"3.384","mis":"M5-2-u4-X02"}],"explanation":["423 × 8 = 3384예요.","4.23은 423의 ⟨1/100⟩배이므로 곱도 3384의 ⟨1/100⟩배예요.","4.23 × 8 = 33.84예요."],"asset":{"type":"expr_grid","rows":[["","","4.","2","3"],["×","","","","8"],["","?","?","?","?"]]}},{"stem":"0.92 × 32를 계산하면 얼마인가요?","options":[{"t":"29.44","correct":true},{"t":"2944","mis":"M5-2-u4-X01"},{"t":"294.4","mis":"M5-2-u4-X02"},{"t":"2.944","mis":"M5-2-u4-X02"}],"explanation":["92 × 32 = 2944예요.","0.92는 92의 ⟨1/100⟩배이므로 곱도 2944의 ⟨1/100⟩배예요.","0.92 × 32 = 29.44예요."],"asset":{"type":"expr_grid","rows":[["","","0.","9","2"],["×","","","3","2"],["","?","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#7','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','24 × 3 = 72예요. 0.24 × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"24 × 3 = 72예요. 0.24 × 3을 계산하면 얼마인가요?","options":[{"t":"0.72","correct":true},{"t":"72","mis":"M5-2-u4-X01"},{"t":"7.2","mis":"M5-2-u4-X02"},{"t":"0.072","mis":"M5-2-u4-X02"}],"explanation":["0.24와 3의 소수점 아래 자릿수는 2개와 0개예요.","2 + 0 = 2 — 72에서 소수점을 왼쪽으로 두 자리 옮겨요.","0.24 × 3 = 0.72예요."],"variant_rule":{"alt":[{"stem":"437 × 5 = 2185예요. 4.37 × 5를 계산하면 얼마인가요?","options":[{"t":"21.85","correct":true},{"t":"2185","mis":"M5-2-u4-X01"},{"t":"218.5","mis":"M5-2-u4-X02"},{"t":"2.185","mis":"M5-2-u4-X02"}],"explanation":["4.37과 5의 소수점 아래 자릿수는 2개와 0개예요.","2 + 0 = 2 — 2185에서 소수점을 왼쪽으로 두 자리 옮겨요.","4.37 × 5 = 21.85예요."]},{"stem":"59 × 4 = 236이에요. 0.59 × 4를 계산하면 얼마인가요?","options":[{"t":"2.36","correct":true},{"t":"236","mis":"M5-2-u4-X01"},{"t":"23.6","mis":"M5-2-u4-X02"},{"t":"0.236","mis":"M5-2-u4-X02"}],"explanation":["0.59와 4의 소수점 아래 자릿수는 2개와 0개예요.","2 + 0 = 2 — 236에서 소수점을 왼쪽으로 두 자리 옮겨요.","0.59 × 4 = 2.36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#8','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'sa','auto','4.23 × 8을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C3","difficulty":2,"kind":"sa","stem":"4.23 × 8을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["소수점을 생각하지 않고 423 × 8 = 3384를 계산해요.","4.23의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","4.23 × 8 = 33.84 — ?는 8이에요."],"mis":"M5-2-u4-X13","asset":{"type":"expr_grid","rows":[["","","4.","2","3"],["×","","","","8"],["","3","3.","?","4"]]},"variant_rule":{"alt":[{"stem":"0.84 × 7을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["소수점을 생각하지 않고 84 × 7 = 588을 계산해요.","0.84의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","0.84 × 7 = 5.88 — ?는 8이에요."],"asset":{"type":"expr_grid","rows":[["","0.","8","4"],["×","","","7"],["","5.","?","8"]]}},{"stem":"2.59 × 13을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 생각하지 않고 259 × 13 = 3367을 계산해요.","2.59의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","2.59 × 13 = 33.67 — ?는 6이에요."],"asset":{"type":"expr_grid","rows":[["","","2.","5","9"],["×","","","1","3"],["","3","3.","?","7"]]}},{"stem":"2.27 × 3을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["소수점을 생각하지 않고 227 × 3 = 681을 계산해요.","2.27의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","2.27 × 3 = 6.81 — ?는 8이에요."],"asset":{"type":"expr_grid","rows":[["","2.","2","7"],["×","","","3"],["","6.","?","1"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#9','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'ox','auto','5.40은 끝자리 0을 생략해 5.4로 쓸 수 있어요.',ARRAY['M5-2-u4-X04']::text[],true,'{"seq":9,"concept":"M5-2-u4-C3","difficulty":2,"kind":"ox","stem":"5.40은 끝자리 0을 생략해 5.4로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"소수의 끝자리 0은 생략해도 크기가 같으므로","correct":true},{"t":"끝자리 0을 생략하면 0.54가 되므로","mis":"M5-2-u4-X04"}],"mis":"M5-2-u4-X04","explanation":["5.40은 5와 0.4와 0.00을 더한 수예요.","끝자리 0은 크기를 바꾸지 않아요.","5.40 = 5.4예요."],"variant_rule":{"alt":[{"stem":"0.24 × 3 = 0.72예요.","answer":"O","reason_options":[{"t":"24 × 3 = 72의 ⟨1/100⟩배이므로","correct":true},{"t":"24 × 3 = 72의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["24 × 3 = 72예요.","0.24는 24의 ⟨1/100⟩배예요.","0.24 × 3 = 0.72 — 맞아요."]},{"stem":"0.24는 ⟨24/100⟩와 같아요.","answer":"O","reason_options":[{"t":"소수 두 자리 수는 분모가 100인 분수로 나타내므로","correct":true},{"t":"소수는 분모가 언제나 10이므로","mis":"M5-2-u4-X08"}],"explanation":["0.01이 24개이면 0.24예요.","⟨1/100⟩이 24개이면 ⟨24/100⟩예요.","0.24 = ⟨24/100⟩ — 맞아요."]},{"stem":"4.37 × 5는 20보다 조금 커요.","answer":"O","reason_options":[{"t":"4.37을 4로 어림하면 4 × 5 = 20이고 4.37은 4보다 조금 크므로","correct":true},{"t":"4.37에 소수점이 있어 곱이 20보다 작으므로","mis":"M5-2-u4-X07"}],"explanation":["4.37을 4로 어림하면 4 × 5 = 20이에요.","4.37은 4보다 조금 커요.","4.37 × 5 = 21.85 — 20보다 조금 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_basic#10','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',3,'mc','auto','망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고 4 kg으로 망고주스 16잔을 만들 수 있는지 어림하여 고르세요.',ARRAY['M5-2-u4-X07','M5-2-u4-X02','M5-2-u4-X14']::text[],false,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고 4 kg으로 망고주스 16잔을 만들 수 있는지 어림하여 고르세요.","options":[{"t":"만들 수 없다 — 0.3 × 15 = 4.5(kg)쯤 필요하다","correct":true},{"t":"만들 수 있다 — 망고주스 한 잔에 망고가 1 kg도 들지 않는다","mis":"M5-2-u4-X07"},{"t":"만들 수 있다 — 0.3 × 15 = 0.45(kg)쯤이면 된다","mis":"M5-2-u4-X02"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.32를 0.3으로, 16을 15로 계산하기 쉬운 수로 어림해요.","0.3 × 15 = 4.5(kg)쯤 필요해요.","4.5 > 4 — 망고 4 kg으로는 16잔을 만들 수 없어요(정확히는 0.32 × 16 = 5.12(kg))."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#1','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',2,'mc','auto','4.37 × 5를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"4.37 × 5를 계산하면 얼마인가요?","options":[{"t":"21.85","correct":true},{"t":"2185","mis":"M5-2-u4-X01"},{"t":"218.5","mis":"M5-2-u4-X02"},{"t":"2.185","mis":"M5-2-u4-X02"}],"explanation":["437 × 5 = 2185예요.","4.37은 437의 ⟨1/100⟩배이므로 곱도 2185의 ⟨1/100⟩배예요.","4.37 × 5 = 21.85예요."],"variant_rule":{"alt":[{"stem":"0.92 × 32를 계산하면 얼마인가요?","options":[{"t":"29.44","correct":true},{"t":"2944","mis":"M5-2-u4-X01"},{"t":"294.4","mis":"M5-2-u4-X02"},{"t":"2.944","mis":"M5-2-u4-X02"}],"explanation":["92 × 32 = 2944예요.","0.92는 92의 ⟨1/100⟩배이므로 곱도 2944의 ⟨1/100⟩배예요.","0.92 × 32 = 29.44예요."]},{"stem":"2.27 × 3을 계산하면 얼마인가요?","options":[{"t":"6.81","correct":true},{"t":"681","mis":"M5-2-u4-X01"},{"t":"68.1","mis":"M5-2-u4-X02"},{"t":"0.681","mis":"M5-2-u4-X02"}],"explanation":["227 × 3 = 681이에요.","2.27은 227의 ⟨1/100⟩배이므로 곱도 681의 ⟨1/100⟩배예요.","2.27 × 3 = 6.81이에요."]},{"stem":"0.06 × 8을 계산하면 얼마인가요?","options":[{"t":"0.48","correct":true},{"t":"48","mis":"M5-2-u4-X01"},{"t":"4.8","mis":"M5-2-u4-X02"},{"t":"0.048","mis":"M5-2-u4-X02"}],"explanation":["6 × 8 = 48이에요.","0.06은 6의 ⟨1/100⟩배이므로 곱도 48의 ⟨1/100⟩배예요.","0.06 × 8 = 0.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#2','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',2,'mc','auto','0.24 × 3을 자연수의 곱셈 24 × 3 = 72를 이용해 계산하려고 해요. 0.24 × 3의 곱은 72의 몇 배인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X02','M5-2-u4-X10']::text[],true,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.24 × 3을 자연수의 곱셈 24 × 3 = 72를 이용해 계산하려고 해요. 0.24 × 3의 곱은 72의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"100배","mis":"M5-2-u4-X10"}],"explanation":["0.24는 24의 ⟨1/100⟩배예요.","그래서 곱은 72의 ⟨1/100⟩배예요.","0.24 × 3 = 0.72예요."],"variant_rule":{"alt":[{"stem":"4.37 × 5를 자연수의 곱셈 437 × 5 = 2185를 이용해 계산하려고 해요. 4.37 × 5의 곱은 2185의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"100배","mis":"M5-2-u4-X10"}],"explanation":["4.37은 437의 ⟨1/100⟩배예요.","그래서 곱은 2185의 ⟨1/100⟩배예요.","4.37 × 5 = 21.85예요."]},{"stem":"1.2 × 4를 자연수의 곱셈 12 × 4 = 48을 이용해 계산하려고 해요. 1.2 × 4의 곱은 48의 몇 배인가요?","options":[{"t":"⟨1/10⟩배","correct":true},{"t":"⟨1/100⟩배","mis":"M5-2-u4-X02"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"10배","mis":"M5-2-u4-X10"}],"explanation":["1.2는 12의 ⟨1/10⟩배예요.","그래서 곱은 48의 ⟨1/10⟩배예요.","1.2 × 4 = 4.8이에요."]},{"stem":"0.59 × 4를 자연수의 곱셈 59 × 4 = 236을 이용해 계산하려고 해요. 0.59 × 4의 곱은 236의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"100배","mis":"M5-2-u4-X10"}],"explanation":["0.59는 59의 ⟨1/100⟩배예요.","그래서 곱은 236의 ⟨1/100⟩배예요.","0.59 × 4 = 2.36이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#3','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'error','auto','1.35 × 4를 세로로 계산한 것이에요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X04']::text[],false,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":3,"kind":"error","stem":"1.35 × 4를 세로로 계산한 것이에요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 5.4이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"135 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["1.35는 1보다 크므로 곱은 1 × 4 = 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배이므로 곱은 5.40이에요.","바른 곱은 5.4 — 0.540은 ⟨1/10⟩배 더 작게 쓴 거예요."],"asset":{"type":"expr_grid","rows":[["","","1.","3","5"],["×","","","","4"],["","0.","5","4","0"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#4','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'sa','auto','0.83 × 15 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u4-C3","difficulty":3,"kind":"sa","stem":"0.83 × 15 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["0.83 × 15 = 12.45예요.","12.45 < □이므로 □는 12.45보다 큰 자연수예요 — 12는 12.45보다 작아서 안 돼요.","가장 작은 자연수는 13이에요."],"mis":"M5-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#5','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'mc','auto','망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고주스 16잔을 만들려면 가지고 있는 망고 4 kg보다 망고가 몇 kg 더 필요한가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X02','M5-2-u4-X14']::text[],false,'{"seq":5,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고주스 16잔을 만들려면 가지고 있는 망고 4 kg보다 망고가 몇 kg 더 필요한가요?","options":[{"t":"1.12 kg","correct":true},{"t":"5.12 kg","mis":"M5-2-u4-X18"},{"t":"47.2 kg","mis":"M5-2-u4-X02"},{"t":"0.5 kg","mis":"M5-2-u4-X14"}],"explanation":["16잔에 필요한 망고는 0.32 × 16이에요.","32 × 16 = 512의 ⟨1/100⟩배 — 0.32 × 16 = 5.12(kg)예요.","5.12 − 4 = 1.12 — 1.12 kg 더 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#6','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'ox','auto','1.35 × 4 = 0.540이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C3","difficulty":3,"kind":"ox","stem":"1.35 × 4 = 0.540이에요.","answer":"X","reason_options":[{"t":"1.35는 1보다 커서 곱은 4보다 커야 하고 바른 곱은 5.4이므로","correct":true},{"t":"135 × 4 = 540의 ⟨1/1000⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["1 × 4 = 4니 곱은 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략하면 5.4예요."],"variant_rule":{"alt":[{"stem":"2.59 × 13 = 336.7이에요.","answer":"X","reason_options":[{"t":"259 × 13 = 3367의 ⟨1/100⟩배인 33.67이므로","correct":true},{"t":"259 × 13 = 3367의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요 — 3 × 13 = 39쯤과도 맞아요."]},{"stem":"4.37 × 5는 20보다 조금 커요.","answer":"O","reason_options":[{"t":"4.37을 4로 어림하면 4 × 5 = 20이고 4.37은 4보다 조금 크므로","correct":true},{"t":"4.37에 소수점이 있어 곱이 20보다 작으므로","mis":"M5-2-u4-X07"}],"explanation":["4.37을 4로 어림하면 4 × 5 = 20이에요.","4.37은 4보다 조금 커요.","4.37 × 5 = 21.85 — 20보다 조금 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#7','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C3","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.14 × 6","r":"0.84"},{"l":"2.59 × 13","r":"33.67"},{"l":"0.84 × 7","r":"5.88"}],"mis":"M5-2-u4-X02","explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.14 × 6 = 0.84 · 2.59 × 13 = 33.67이에요.","0.84 × 7 = 5.88이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"4.23 × 8","r":"33.84"},{"l":"0.06 × 8","r":"0.48"},{"l":"2.27 × 3","r":"6.81"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","4.23 × 8 = 33.84 · 0.06 × 8 = 0.48이에요.","2.27 × 3 = 6.81이에요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.92 × 32","r":"29.44"},{"l":"0.59 × 4","r":"2.36"},{"l":"4.25 × 5","r":"21.25"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.92 × 32 = 29.44 · 0.59 × 4 = 2.36이에요.","4.25 × 5 = 21.25예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#8','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'essay','teacher','어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.","answer_guide":{"answer":"예: 1.35는 1보다 크므로 1.35 × 4는 1 × 4 = 4보다 커야 하는데 0.540은 4보다 작아 틀렸다. 135 × 4 = 540이고 1.35는 135의 ⟨1/100⟩배이므로 곱은 540의 ⟨1/100⟩배인 5.40이다. 끝자리 0은 생략하여 5.4로 쓸 수 있다.","scoring_points":["곱이 4보다 커야 한다고 어림으로 설명했는가","135 × 4 = 540의 ⟨1/100⟩배로 5.40을 구했는가","끝자리 0을 생략해 5.4로 쓸 수 있다고 했는가"]},"explanation":["1 × 4 = 4보다 커야 해요.","540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략해 5.4로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#9','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'essay','teacher','운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달린 거리를 분수의 곱셈과 자연수의 곱셈으로 각각 구하고, 0.24 × 3과 2.4 × 3의 곱이 어떤 관계인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달린 거리를 분수의 곱셈과 자연수의 곱셈으로 각각 구하고, 0.24 × 3과 2.4 × 3의 곱이 어떤 관계인지 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72이다. 자연수로 — 24 × 3 = 72이고 0.24는 24의 ⟨1/100⟩배이므로 곱도 72의 ⟨1/100⟩배인 0.72이다. 2.4 × 3 = 7.2이고 0.24는 2.4의 ⟨1/10⟩배이므로 0.24 × 3의 곱은 2.4 × 3의 곱의 ⟨1/10⟩배이다.","scoring_points":["분수의 곱셈으로 0.72 km를 구했는가","자연수의 곱셈과 ⟨1/100⟩배로 0.72를 구했는가","0.24 × 3의 곱이 2.4 × 3의 곱의 ⟨1/10⟩배라고 썼는가"]},"explanation":["⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요.","72의 ⟨1/100⟩배 — 0.72 km예요.","2.4 × 3 = 7.2의 ⟨1/10⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L03_challenge#10','math',5,2,'u4','L03','tb_g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'essay','teacher','망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고 4 kg으로 망고주스 16잔을 만들 수 있는지 어림하여 판단하고, 그렇게 어림한 방법을 쓴 다음 정확히 계산하여 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"망고주스 1잔을 만드는 데 망고 0.32 kg이 필요해요. 망고 4 kg으로 망고주스 16잔을 만들 수 있는지 어림하여 판단하고, 그렇게 어림한 방법을 쓴 다음 정확히 계산하여 확인해 보세요.","answer_guide":{"answer":"예: 0.32를 0.3으로, 16을 15로 어림하면 0.3 × 15 = 4.5(kg)쯤 필요하다. 4.5 > 4이므로 망고 4 kg으로는 16잔을 만들 수 없다. 정확히 계산하면 32 × 16 = 512이고 0.32는 32의 ⟨1/100⟩배이므로 0.32 × 16 = 5.12(kg)이다. 5.12 > 4이므로 어림한 판단이 맞다.","scoring_points":["계산하기 쉬운 수로 어림해 4.5 kg쯤이라고 했는가","4 kg으로는 만들 수 없다고 판단했는가","0.32 × 16 = 5.12(kg)로 확인했는가"]},"explanation":["0.3 × 15 = 4.5(kg)쯤이에요.","4.5 > 4 — 만들 수 없어요.","정확히는 0.32 × 16 = 5.12(kg)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#1','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'sa','auto','2 × 0.8을 그림으로 나타내려고 해요. 2를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C4","difficulty":1,"kind":"sa","stem":"2 × 0.8을 그림으로 나타내려고 해요. 2를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.8 = ⟨8/10⟩이에요.","2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.","그래서 10칸 중 8칸을 칠해요 — 곱은 1.6이에요."],"mis":"M5-2-u4-X09","asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,2],[0,2]],"hi":true},{"p":[[2,0],[4,0],[4,2],[2,2]],"hi":true},{"p":[[4,0],[6,0],[6,2],[4,2]],"hi":true},{"p":[[6,0],[8,0],[8,2],[6,2]],"hi":true},{"p":[[8,0],[10,0],[10,2],[8,2]],"hi":true},{"p":[[10,0],[12,0],[12,2],[10,2]],"hi":true},{"p":[[12,0],[14,0],[14,2],[12,2]],"hi":true},{"p":[[14,0],[16,0],[16,2],[14,2]],"hi":true},{"p":[[16,0],[18,0],[18,2],[16,2]]},{"p":[[18,0],[20,0],[20,2],[18,2]]}],"u":14},"variant_rule":{"alt":[{"stem":"5 × 0.6을 그림으로 나타내려고 해요. 5를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["0.6 = ⟨6/10⟩이에요.","5 × 0.6은 5를 똑같이 10으로 나눈 것 중의 6이에요.","그래서 10칸 중 6칸을 칠해요 — 곱은 3이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[2,0],[2,2],[0,2]],"hi":true},{"p":[[2,0],[4,0],[4,2],[2,2]],"hi":true},{"p":[[4,0],[6,0],[6,2],[4,2]],"hi":true},{"p":[[6,0],[8,0],[8,2],[6,2]],"hi":true},{"p":[[8,0],[10,0],[10,2],[8,2]],"hi":true},{"p":[[10,0],[12,0],[12,2],[10,2]],"hi":true},{"p":[[12,0],[14,0],[14,2],[12,2]]},{"p":[[14,0],[16,0],[16,2],[14,2]]},{"p":[[16,0],[18,0],[18,2],[16,2]]},{"p":[[18,0],[20,0],[20,2],[18,2]]}],"u":14}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#2','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'mc','auto','2 × 0.8은 2보다 큰가요, 작은가요?',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],true,'{"seq":2,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"2 × 0.8은 2보다 큰가요, 작은가요?","options":[{"t":"작다 — 2의 ⟨8/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 2를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.8이 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.8을 1과 견주어요.","0.8은 1보다 작으니 곱은 2보다 작아요.","실제로 2 × 0.8 = 1.6이에요."],"variant_rule":{"alt":[{"stem":"7 × 1.6은 7보다 큰가요, 작은가요?","options":[{"t":"크다 — 1.6이 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 7을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 1.6에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 1.6을 1과 견주어요.","1.6은 1보다 크니 곱은 7보다 커요.","실제로 7 × 1.6 = 11.2예요."]},{"stem":"6 × 1.4는 6보다 큰가요, 작은가요?","options":[{"t":"크다 — 1.4가 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 6을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 1.4에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 1.4를 1과 견주어요.","1.4는 1보다 크니 곱은 6보다 커요.","실제로 6 × 1.4 = 8.4예요."]},{"stem":"5 × 0.9는 5보다 큰가요, 작은가요?","options":[{"t":"작다 — 5의 ⟨9/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 5를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.9가 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.9를 1과 견주어요.","0.9는 1보다 작으니 곱은 5보다 작아요.","실제로 5 × 0.9 = 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#3','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'mc','auto','우리 반이 어제 남긴 음식은 2 kg이었는데, 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식은 몇 kg인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":3,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"우리 반이 어제 남긴 음식은 2 kg이었는데, 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식은 몇 kg인가요?","options":[{"t":"1.6 kg","correct":true},{"t":"2.8 kg","mis":"M5-2-u4-X17"},{"t":"16 kg","mis":"M5-2-u4-X01"},{"t":"0.16 kg","mis":"M5-2-u4-X02"}],"explanation":["「2의 0.8배」는 2 × 0.8이에요.","2 × 8 = 16의 ⟨1/10⟩배예요.","2 × 0.8 = 1.6 — 1.6 kg이에요."],"variant_rule":{"alt":[{"stem":"작년에 수호네 마을에서 생산한 쌀은 6 t이에요. 올해 수호네 마을의 쌀 생산량이 작년 생산량의 1.4배라면 올해 생산한 쌀은 몇 t인가요?","options":[{"t":"8.4 t","correct":true},{"t":"7.4 t","mis":"M5-2-u4-X17"},{"t":"84 t","mis":"M5-2-u4-X01"},{"t":"0.84 t","mis":"M5-2-u4-X02"}],"explanation":["「6의 1.4배」는 6 × 1.4예요.","6 × 14 = 84의 ⟨1/10⟩배예요.","6 × 1.4 = 8.4 — 8.4 t이에요."]},{"stem":"현수가 텃밭에서 수확한 고구마는 2 kg이에요. 수확한 감자가 고구마의 1.2배라면 수확한 감자는 몇 kg인가요?","options":[{"t":"2.4 kg","correct":true},{"t":"3.2 kg","mis":"M5-2-u4-X17"},{"t":"24 kg","mis":"M5-2-u4-X01"},{"t":"0.24 kg","mis":"M5-2-u4-X02"}],"explanation":["「2 kg의 1.2배」는 2 × 1.2예요.","2 × 12 = 24예요. 곱은 그 ⟨1/10⟩배예요.","2 × 1.2 = 2.4 — 2.4 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#4','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'mc','auto','7 × 1.6과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X17','M5-2-u4-X02']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"7 × 1.6과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"1.6 × 7","correct":true},{"t":"7 × 16","mis":"M5-2-u4-X01"},{"t":"1.6 + 7","mis":"M5-2-u4-X17"},{"t":"0.16 × 7","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","7 × 1.6 = 11.2예요.","1.6 × 7 = 11.2 — 그래서 같아요."],"variant_rule":{"alt":[{"stem":"8 × 2.4와 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"2.4 × 8","correct":true},{"t":"8 × 24","mis":"M5-2-u4-X01"},{"t":"2.4 + 8","mis":"M5-2-u4-X17"},{"t":"0.24 × 8","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","8 × 2.4 = 19.2예요.","2.4 × 8 = 19.2 — 그래서 같아요."]},{"stem":"36 × 0.6과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"0.6 × 36","correct":true},{"t":"36 × 6","mis":"M5-2-u4-X01"},{"t":"0.6 + 36","mis":"M5-2-u4-X17"},{"t":"0.06 × 36","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","36 × 0.6 = 21.6이에요.","0.6 × 36 = 21.6 — 그래서 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#5','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','7 × 1.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03','M5-2-u4-X17']::text[],true,'{"seq":5,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 1.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × ⟨16/10⟩","correct":true},{"t":"7 × ⟨16/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨7/10⟩ × ⟨16/10⟩","mis":"M5-2-u4-X03"},{"t":"7 + ⟨16/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.6 = ⟨16/10⟩이에요.","7 × ⟨16/10⟩ = ⟨112/10⟩ = 11.2예요."],"variant_rule":{"alt":[{"stem":"2 × 0.8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨8/10⟩","correct":true},{"t":"2 × ⟨8/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨2/10⟩ × ⟨8/10⟩","mis":"M5-2-u4-X03"},{"t":"2 + ⟨8/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.8 = ⟨8/10⟩이에요.","2 × ⟨8/10⟩ = ⟨16/10⟩ = 1.6이에요."]},{"stem":"5 × 0.9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 × ⟨9/10⟩","correct":true},{"t":"5 × ⟨9/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨5/10⟩ × ⟨9/10⟩","mis":"M5-2-u4-X03"},{"t":"5 + ⟨9/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.9 = ⟨9/10⟩예요.","5 × ⟨9/10⟩ = ⟨45/10⟩ = 4.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#6','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','7 × 16 = 112예요. 7 × 1.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 16 = 112예요. 7 × 1.6을 계산하면 얼마인가요?","options":[{"t":"11.2","correct":true},{"t":"112","mis":"M5-2-u4-X01"},{"t":"1.12","mis":"M5-2-u4-X02"},{"t":"1120","mis":"M5-2-u4-X02"}],"explanation":["7과 1.6의 소수점 아래 자릿수는 0개와 1개예요.","0 + 1 = 1 — 112에서 소수점을 왼쪽으로 한 자리 옮겨요.","7 × 1.6 = 11.2예요."],"variant_rule":{"alt":[{"stem":"8 × 24 = 192예요. 8 × 2.4를 계산하면 얼마인가요?","options":[{"t":"19.2","correct":true},{"t":"192","mis":"M5-2-u4-X01"},{"t":"1.92","mis":"M5-2-u4-X02"},{"t":"1920","mis":"M5-2-u4-X02"}],"explanation":["8과 2.4의 소수점 아래 자릿수는 0개와 1개예요.","0 + 1 = 1 — 192에서 소수점을 왼쪽으로 한 자리 옮겨요.","8 × 2.4 = 19.2예요."]},{"stem":"17 × 53 = 901이에요. 17 × 5.3을 계산하면 얼마인가요?","options":[{"t":"90.1","correct":true},{"t":"901","mis":"M5-2-u4-X01"},{"t":"9.01","mis":"M5-2-u4-X02"},{"t":"9010","mis":"M5-2-u4-X02"}],"explanation":["17과 5.3의 소수점 아래 자릿수는 0개와 1개예요.","0 + 1 = 1 — 901에서 소수점을 왼쪽으로 한 자리 옮겨요.","17 × 5.3 = 90.1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#7','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','8 × 2.4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"8 × 2.4를 계산하면 얼마인가요?","options":[{"t":"19.2","correct":true},{"t":"192","mis":"M5-2-u4-X01"},{"t":"1.92","mis":"M5-2-u4-X02"},{"t":"1920","mis":"M5-2-u4-X02"}],"explanation":["8 × 24 = 192예요.","2.4는 24의 ⟨1/10⟩배이므로 곱도 192의 ⟨1/10⟩배예요.","8 × 2.4 = 19.2예요."],"asset":{"type":"expr_grid","rows":[["","","","8"],["×","","2.","4"],["","?","?","?"]]},"variant_rule":{"alt":[{"stem":"17 × 5.3을 계산하면 얼마인가요?","options":[{"t":"90.1","correct":true},{"t":"901","mis":"M5-2-u4-X01"},{"t":"9.01","mis":"M5-2-u4-X02"},{"t":"9010","mis":"M5-2-u4-X02"}],"explanation":["17 × 53 = 901이에요.","5.3은 53의 ⟨1/10⟩배이므로 곱도 901의 ⟨1/10⟩배예요.","17 × 5.3 = 90.1이에요."],"asset":{"type":"expr_grid","rows":[["","","1","7"],["×","","5.","3"],["","?","?","?"]]}},{"stem":"5 × 0.9를 계산하면 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"45","mis":"M5-2-u4-X01"},{"t":"0.45","mis":"M5-2-u4-X02"},{"t":"450","mis":"M5-2-u4-X02"}],"explanation":["5 × 9 = 45예요.","0.9는 9의 ⟨1/10⟩배이므로 곱도 45의 ⟨1/10⟩배예요.","5 × 0.9 = 4.5예요."],"asset":{"type":"expr_grid","rows":[["","","5"],["×","0.","9"],["","?","?"]]}},{"stem":"36 × 0.6을 계산하면 얼마인가요?","options":[{"t":"21.6","correct":true},{"t":"216","mis":"M5-2-u4-X01"},{"t":"2.16","mis":"M5-2-u4-X02"},{"t":"2160","mis":"M5-2-u4-X02"}],"explanation":["36 × 6 = 216이에요.","0.6은 6의 ⟨1/10⟩배이므로 곱도 216의 ⟨1/10⟩배예요.","36 × 0.6 = 21.6이에요."],"asset":{"type":"expr_grid","rows":[["","","3","6"],["×","","0.","6"],["","?","?","?"]]}},{"stem":"45 × 0.9를 계산하면 얼마인가요?","options":[{"t":"40.5","correct":true},{"t":"405","mis":"M5-2-u4-X01"},{"t":"4.05","mis":"M5-2-u4-X02"},{"t":"4050","mis":"M5-2-u4-X02"}],"explanation":["45 × 9 = 405예요.","0.9는 9의 ⟨1/10⟩배이므로 곱도 405의 ⟨1/10⟩배예요.","45 × 0.9 = 40.5예요."],"asset":{"type":"expr_grid","rows":[["","","4","5"],["×","","0.","9"],["","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#8','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','7 × 1.6 = 7 × 1 + 7 × □에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":8,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 1.6 = 7 × 1 + 7 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.6","correct":true},{"t":"6","mis":"M5-2-u4-X01"},{"t":"0.06","mis":"M5-2-u4-X02"},{"t":"1.6","mis":"M5-2-u4-X18"}],"explanation":["1.6 = 1 + 0.6이에요.","7의 1배와 7의 0.6배를 더하면 돼요.","7 × 1 + 7 × 0.6 = 7 + 4.2 = 11.2예요."],"variant_rule":{"alt":[{"stem":"8 × 2.4 = 8 × 2 + 8 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.4","correct":true},{"t":"4","mis":"M5-2-u4-X01"},{"t":"0.04","mis":"M5-2-u4-X02"},{"t":"2.4","mis":"M5-2-u4-X18"}],"explanation":["2.4 = 2 + 0.4예요.","8의 2배와 8의 0.4배를 더하면 돼요.","8 × 2 + 8 × 0.4 = 16 + 3.2 = 19.2예요."]},{"stem":"7 × 3.4 = 7 × 3 + 7 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.4","correct":true},{"t":"4","mis":"M5-2-u4-X01"},{"t":"0.04","mis":"M5-2-u4-X02"},{"t":"3.4","mis":"M5-2-u4-X18"}],"explanation":["3.4 = 3 + 0.4예요.","7의 3배와 7의 0.4배를 더하면 돼요.","7 × 3 + 7 × 0.4 = 21 + 2.8 = 23.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#9','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'ox','auto','2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":9,"concept":"M5-2-u4-C4","difficulty":2,"kind":"ox","stem":"2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.","answer":"O","reason_options":[{"t":"0.8 = ⟨8/10⟩이므로","correct":true},{"t":"0.8을 곱하면 2가 8배가 되므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["0.8 = ⟨8/10⟩이에요.","2의 ⟨8/10⟩은 2를 10으로 나눈 것 중의 8이에요.","2 × 0.8 = 1.6이에요."],"variant_rule":{"alt":[{"stem":"7 × 1.6과 1.6 × 7의 곱은 같아요.","answer":"O","reason_options":[{"t":"두 수의 자리를 바꾸어 곱해도 곱은 같으므로","correct":true},{"t":"곱하는 수가 소수이면 자리를 바꿀 때 곱이 달라지므로","mis":"M5-2-u4-X18"}],"explanation":["7 × 1.6 = 11.2예요.","1.6 × 7 = 11.2예요.","그래서 맞아요."]},{"stem":"7 × 1.6은 7에 7 × 0.6을 더한 것과 같아요.","answer":"O","reason_options":[{"t":"1.6 = 1 + 0.6이라 7의 1배와 7의 0.6배를 더하면 되므로","correct":true},{"t":"1.6은 1과 6으로 가르므로","mis":"M5-2-u4-X01"}],"explanation":["1.6 = 1 + 0.6이에요.","7 × 1 = 7, 7 × 0.6 = 4.2예요.","7 + 4.2 = 11.2 = 7 × 1.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_basic#10','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',3,'mc','auto','높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":10,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"19.2 cm","correct":true},{"t":"28.4 cm","mis":"M5-2-u4-X17"},{"t":"192 cm","mis":"M5-2-u4-X02"},{"t":"24 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.8 = 24(cm)예요.","두 번째 인형은 24 × 0.8 = 19.2(cm)예요.","그래서 19.2 cm예요."],"variant_rule":{"alt":[{"stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 첫 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"24 cm","correct":true},{"t":"29.2 cm","mis":"M5-2-u4-X17"},{"t":"240 cm","mis":"M5-2-u4-X02"},{"t":"19.2 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.8 = 24(cm)예요.","0.8은 1보다 작으니 30 cm보다 작아야 해요.","그래서 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#1','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',2,'mc','auto','17 × 5.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"17 × 5.3을 계산하면 얼마인가요?","options":[{"t":"90.1","correct":true},{"t":"901","mis":"M5-2-u4-X01"},{"t":"9.01","mis":"M5-2-u4-X02"},{"t":"9010","mis":"M5-2-u4-X02"}],"explanation":["17 × 53 = 901이에요.","5.3은 53의 ⟨1/10⟩배이므로 곱도 901의 ⟨1/10⟩배예요.","17 × 5.3 = 90.1이에요."],"variant_rule":{"alt":[{"stem":"36 × 0.6을 계산하면 얼마인가요?","options":[{"t":"21.6","correct":true},{"t":"216","mis":"M5-2-u4-X01"},{"t":"2.16","mis":"M5-2-u4-X02"},{"t":"2160","mis":"M5-2-u4-X02"}],"explanation":["36 × 6 = 216이에요.","0.6은 6의 ⟨1/10⟩배이므로 곱도 216의 ⟨1/10⟩배예요.","36 × 0.6 = 21.6이에요."]},{"stem":"45 × 0.9를 계산하면 얼마인가요?","options":[{"t":"40.5","correct":true},{"t":"405","mis":"M5-2-u4-X01"},{"t":"4.05","mis":"M5-2-u4-X02"},{"t":"4050","mis":"M5-2-u4-X02"}],"explanation":["45 × 9 = 405예요.","0.9는 9의 ⟨1/10⟩배이므로 곱도 405의 ⟨1/10⟩배예요.","45 × 0.9 = 40.5예요."]},{"stem":"7 × 3.4를 계산하면 얼마인가요?","options":[{"t":"23.8","correct":true},{"t":"238","mis":"M5-2-u4-X01"},{"t":"2.38","mis":"M5-2-u4-X02"},{"t":"2380","mis":"M5-2-u4-X02"}],"explanation":["7 × 34 = 238이에요.","3.4는 34의 ⟨1/10⟩배이므로 곱도 238의 ⟨1/10⟩배예요.","7 × 3.4 = 23.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#2','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C3',2,'sa','auto','0.35 × 5를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":2,"kind":"sa","stem":"0.35 × 5를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["소수점을 생각하지 않고 35 × 5 = 175를 계산해요.","0.35의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","0.35 × 5 = 1.75 — ?는 7이에요."],"mis":"M5-2-u4-X13","asset":{"type":"expr_grid","rows":[["","0.","3","5"],["×","","","5"],["","1.","?","5"]]},"variant_rule":{"alt":[{"stem":"1.13 × 11을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["소수점을 생각하지 않고 113 × 11 = 1243을 계산해요.","1.13의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","1.13 × 11 = 12.43 — ?는 4예요."],"asset":{"type":"expr_grid","rows":[["","","1.","1","3"],["×","","","1","1"],["","1","2.","?","3"]]}},{"stem":"0.05 × 7을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["소수점을 생각하지 않고 5 × 7 = 35를 계산해요.","0.05의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","0.05 × 7 = 0.35 — ?는 3이에요."],"asset":{"type":"expr_grid","rows":[["","0.","0","5"],["×","","","7"],["","0.","?","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#3','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'mc','auto','어림하여 계산 결과가 6보다 큰 것을 고르세요. 6 × 0.9 · 3의 2.1배 · 2 × 2.7',ARRAY['M5-2-u4-X07','M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"어림하여 계산 결과가 6보다 큰 것을 고르세요. 6 × 0.9 · 3의 2.1배 · 2 × 2.7","options":[{"t":"3의 2.1배","correct":true},{"t":"6 × 0.9","mis":"M5-2-u4-X07"},{"t":"2 × 2.7","mis":"M5-2-u4-X07"},{"t":"셋 모두 6보다 크다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","0.9를 1로 어림하면 6 × 1 = 6 — 6 × 0.9는 6보다 작아요 · 2.1을 2로 어림하면 3 × 2 = 6 — 3의 2.1배는 6보다 커요 · 2.7을 3으로 어림하면 2 × 3 = 6 — 2 × 2.7은 6보다 작아요.","그래서 6보다 큰 것은 3의 2.1배 — 실제로 6 × 0.9 = 5.4, 3 × 2.1 = 6.3, 2 × 2.7 = 5.4."],"variant_rule":{"alt":[{"stem":"어림하여 계산 결과가 8보다 작은 것을 고르세요. 4의 2.1배 · 3 × 3.01 · 2의 3.98배","options":[{"t":"2의 3.98배","correct":true},{"t":"4의 2.1배","mis":"M5-2-u4-X06"},{"t":"3 × 3.01","mis":"M5-2-u4-X06"},{"t":"셋 모두 8보다 작다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","2.1을 2로 어림하면 4 × 2 = 8 — 4의 2.1배는 8보다 커요 · 3.01을 3으로 어림하면 3 × 3 = 9 — 8보다 커요 · 3.98을 4로 어림하면 2 × 4 = 8 — 2의 3.98배는 8보다 작아요.","그래서 8보다 작은 것은 2의 3.98배 — 실제로 4 × 2.1 = 8.4, 3 × 3.01 = 9.03, 2 × 3.98 = 7.96."]},{"stem":"어림하여 계산 결과가 6보다 큰 것을 고르세요. 2.9 × 2 · 2.03 × 3 · 1.39 × 4","options":[{"t":"2.03 × 3","correct":true},{"t":"2.9 × 2","mis":"M5-2-u4-X07"},{"t":"1.39 × 4","mis":"M5-2-u4-X07"},{"t":"셋 모두 6보다 크다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","2.9를 3으로 어림하면 3 × 2 = 6 — 2.9 × 2는 6보다 작아요 · 2.03을 2로 어림하면 2 × 3 = 6 — 2.03 × 3은 6보다 커요 · 1.39를 1.4로 어림하면 1.4 × 4 = 5.6 — 1.39 × 4는 6보다 작아요.","그래서 6보다 큰 것은 2.03 × 3 — 실제로 2.9 × 2 = 5.8, 2.03 × 3 = 6.09, 1.39 × 4 = 5.56."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#4','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'error','auto','어제 우리 반이 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 됐어요. 어떤 친구가 「곱셈을 하면 언제나 커지니까 오늘 남긴 음식은 2 kg보다 많아요.」라고 말했어요. 바르게 고친 것은 어느 것인가요?',ARRAY['M5-2-u4-X06','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":3,"kind":"error","stem":"어제 우리 반이 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 됐어요. 어떤 친구가 「곱셈을 하면 언제나 커지니까 오늘 남긴 음식은 2 kg보다 많아요.」라고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"0.8이 1보다 작아 2 kg보다 적다 — 오늘 남긴 음식은 1.6 kg이다","correct":true,"mis_target":"M5-2-u4-X06"},{"t":"0.8배는 2에 0.8을 더한 것 — 2.8 kg이다","mis":"M5-2-u4-X17"},{"t":"바르게 말했다 — 16 kg이다","mis":"M5-2-u4-X01"}],"explanation":["곱하는 수 0.8을 1과 견주어요.","0.8 < 1이므로 2 kg의 0.8배는 2 kg보다 적어요.","2 × 0.8 = 1.6 — 오늘 남긴 음식은 1.6 kg이에요."],"variant_rule":{"alt":[{"stem":"작년에 수호네 마을에서 생산한 쌀은 6 t이에요. 올해 생산량이 작년의 1.4배일 때 어떤 친구가 「1.4에 소수점이 있으니까 올해는 작년보다 적게 생산했어요.」라고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"1.4가 1보다 커서 작년보다 많다 — 올해 생산한 쌀은 8.4 t이다","correct":true,"mis_target":"M5-2-u4-X07"},{"t":"6에 1.4를 더해 7.4 t이다","mis":"M5-2-u4-X17"},{"t":"바르게 말했다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 1.4를 1과 견주어요.","1.4 > 1이므로 6 t의 1.4배는 6 t보다 많아요.","6 × 1.4 = 8.4 — 올해 생산한 쌀은 8.4 t이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#5','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'mc','auto','작년에 수호네 마을에서 생산한 쌀은 6 t이에요. 올해 수호네 마을의 쌀 생산량이 작년 생산량의 1.4배라면 올해 생산한 쌀은 몇 t인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"작년에 수호네 마을에서 생산한 쌀은 6 t이에요. 올해 수호네 마을의 쌀 생산량이 작년 생산량의 1.4배라면 올해 생산한 쌀은 몇 t인가요?","options":[{"t":"8.4 t","correct":true},{"t":"7.4 t","mis":"M5-2-u4-X17"},{"t":"84 t","mis":"M5-2-u4-X01"},{"t":"0.84 t","mis":"M5-2-u4-X02"}],"explanation":["「6의 1.4배」는 6 × 1.4예요.","6 × 14 = 84의 ⟨1/10⟩배예요.","6 × 1.4 = 8.4 — 8.4 t이에요."],"variant_rule":{"alt":[{"stem":"현수가 텃밭에서 수확한 고구마는 2 kg이에요. 수확한 감자가 고구마의 1.2배라면 수확한 감자는 몇 kg인가요?","options":[{"t":"2.4 kg","correct":true},{"t":"3.2 kg","mis":"M5-2-u4-X17"},{"t":"24 kg","mis":"M5-2-u4-X01"},{"t":"0.24 kg","mis":"M5-2-u4-X02"}],"explanation":["「2 kg의 1.2배」는 2 × 1.2예요.","2 × 12 = 24예요. 곱은 그 ⟨1/10⟩배예요.","2 × 1.2 = 2.4 — 2.4 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#6','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'ox','auto','6 × 0.9는 6보다 커요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":6,"concept":"M5-2-u4-C4","difficulty":3,"kind":"ox","stem":"6 × 0.9는 6보다 커요.","answer":"X","reason_options":[{"t":"0.9가 1보다 작아 곱은 6보다 작으므로","correct":true},{"t":"곱하면 언제나 커지므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["곱하는 수 0.9는 1보다 작아요.","그러니 곱은 6보다 작아요.","6 × 0.9 = 5.4예요."],"variant_rule":{"alt":[{"stem":"3의 2.1배는 6보다 커요.","answer":"O","reason_options":[{"t":"2.1은 2보다 커서 곱이 3 × 2 = 6보다 크므로","correct":true},{"t":"2.1에 소수점이 있어 곱이 작아지므로","mis":"M5-2-u4-X07"}],"explanation":["3 × 2 = 6이에요.","2.1은 2보다 조금 커요.","3 × 2.1 = 6.3 — 6보다 커요."]},{"stem":"7 × 1.6과 1.6 × 7의 곱은 같아요.","answer":"O","reason_options":[{"t":"두 수의 자리를 바꾸어 곱해도 곱은 같으므로","correct":true},{"t":"곱하는 수가 소수이면 자리를 바꿀 때 곱이 달라지므로","mis":"M5-2-u4-X18"}],"explanation":["7 × 1.6 = 11.2예요.","1.6 × 7 = 11.2예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#7','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C4","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"8 × 2.4","r":"19.2"},{"l":"5 × 0.9","r":"4.5"},{"l":"36 × 0.6","r":"21.6"}],"mis":"M5-2-u4-X02","explanation":["소수점을 생각하지 않고 자연수끼리 곱한 뒤, 소수의 자릿수만큼 곱의 소수점을 찍어요.","8 × 2.4 = 19.2 · 5 × 0.9 = 4.5예요.","36 × 0.6 = 21.6이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"17 × 5.3","r":"90.1"},{"l":"8 × 0.4","r":"3.2"},{"l":"45 × 0.9","r":"40.5"}],"explanation":["소수점을 생각하지 않고 자연수끼리 곱한 뒤, 소수의 자릿수만큼 곱의 소수점을 찍어요.","17 × 5.3 = 90.1 · 8 × 0.4 = 3.2예요.","45 × 0.9 = 40.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#8','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'essay','teacher','어제 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식이 2 kg보다 많을지 적을지 먼저 판단하고, 2 × 0.8을 「2를 똑같이 10으로 나눈 것」으로 설명하며 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C4","difficulty":4,"kind":"essay","stem":"어제 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식이 2 kg보다 많을지 적을지 먼저 판단하고, 2 × 0.8을 「2를 똑같이 10으로 나눈 것」으로 설명하며 계산해 보세요.","answer_guide":{"answer":"예: 곱하는 수 0.8이 1보다 작으므로 오늘 남긴 음식은 2 kg보다 적다. 0.8 = ⟨8/10⟩이므로 2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이다. 2 × ⟨8/10⟩ = ⟨16/10⟩ = 1.6이므로 오늘 남긴 음식은 1.6 kg이다.","scoring_points":["0.8이 1보다 작아 2 kg보다 적다고 판단했는가","2를 10으로 나눈 것 중의 8로 설명했는가","1.6 kg을 구했는가"]},"explanation":["0.8은 1보다 작아요 — 곱은 2보다 작아요.","2의 ⟨8/10⟩ — 10으로 나눈 것 중의 8이에요.","2 × 0.8 = 1.6(kg)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#9','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'essay','teacher','7 × 1.6을 세 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용 · 「7의 1배와 7의 0.6배를 더하기」)으로 계산하고, 1.6 × 7의 계산 결과와 비교해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C4","difficulty":4,"kind":"essay","stem":"7 × 1.6을 세 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용 · 「7의 1배와 7의 0.6배를 더하기」)으로 계산하고, 1.6 × 7의 계산 결과와 비교해 보세요.","answer_guide":{"answer":"예: 분수로 — 7 × ⟨16/10⟩ = ⟨112/10⟩ = 11.2이다. 자연수로 — 7 × 16 = 112이고 1.6은 16의 ⟨1/10⟩배이므로 7 × 1.6은 112의 ⟨1/10⟩배인 11.2이다. 7의 1배는 7이고 7의 0.6배는 4.2이므로 7 × 1.6 = 7 + 4.2 = 11.2이다. 1.6 × 7 = 11.2로 계산 결과가 같다. 곱해지는 수와 곱하는 수의 자리를 바꾸어도 계산 결과는 같다.","scoring_points":["분수의 곱셈으로 11.2를 구했는가","자연수의 곱셈과 ⟨1/10⟩배로 11.2를 구했는가","7 + 4.2 = 11.2로 계산하고 1.6 × 7과 같음을 밝혔는가"]},"explanation":["7 × ⟨16/10⟩ = ⟨112/10⟩ = 11.2예요.","7 + 4.2 = 11.2예요.","1.6 × 7 = 11.2 — 자리를 바꾸어도 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L04_challenge#10','math',5,2,'u4','L04','tb_g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'essay','teacher','6 × 0.9, 3의 2.1배, 2 × 2.7을 직접 계산하지 않고 어림하여 계산 결과가 6보다 큰 것을 찾으려고 해요. 어떻게 어림했는지 쓰고, 계산하여 확인해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C4","difficulty":4,"kind":"essay","stem":"6 × 0.9, 3의 2.1배, 2 × 2.7을 직접 계산하지 않고 어림하여 계산 결과가 6보다 큰 것을 찾으려고 해요. 어떻게 어림했는지 쓰고, 계산하여 확인해 보세요.","answer_guide":{"answer":"예: 0.9를 1로 어림하면 6 × 1 = 6이므로 6 × 0.9는 6보다 작다. 2.1을 2로 어림하면 3 × 2 = 6이므로 3의 2.1배는 6보다 크다. 2.7을 3으로 어림하면 2 × 3 = 6이므로 2 × 2.7은 6보다 작다. 6보다 큰 것은 3의 2.1배이다. 계산하면 6 × 0.9 = 5.4, 3 × 2.1 = 6.3, 2 × 2.7 = 5.4로 어림한 것이 맞다.","scoring_points":["곱하는 수를 1·2·3으로 어림했는가","6보다 큰 것을 3의 2.1배로 찾았는가","계산하여 5.4·6.3·5.4로 확인했는가"]},"explanation":["0.9 → 1, 2.1 → 2, 2.7 → 3으로 어림해요.","3 × 2 = 6보다 조금 큰 3의 2.1배만 6보다 커요.","3 × 2.1 = 6.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#1','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'sa','auto','6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.","answer":["228"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","6 × 38 = 228이에요.","그래서 6 × 0.38 = 2.28이에요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"8 × 3.16을 자연수의 곱셈을 이용해 계산하려고 해요. 8 × 316은 얼마인가요? 숫자로 쓰세요.","answer":["2528"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","8 × 316 = 2528이에요.","그래서 8 × 3.16 = 25.28이에요."]},{"stem":"9 × 0.28을 자연수의 곱셈을 이용해 계산하려고 해요. 9 × 28은 얼마인가요? 숫자로 쓰세요.","answer":["252"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","9 × 28 = 252예요.","그래서 9 × 0.28 = 2.52예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#2','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'mc','auto','6 × 0.38을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03','M5-2-u4-X17']::text[],true,'{"seq":2,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"6 × 0.38을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨38/100⟩","correct":true},{"t":"6 × ⟨38/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨6/10⟩ × ⟨38/100⟩","mis":"M5-2-u4-X03"},{"t":"6 + ⟨38/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.38 = ⟨38/100⟩이에요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요."],"variant_rule":{"alt":[{"stem":"8 × 3.16을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 × ⟨316/100⟩","correct":true},{"t":"8 × ⟨316/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨8/10⟩ × ⟨316/100⟩","mis":"M5-2-u4-X03"},{"t":"8 + ⟨316/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","3.16 = ⟨316/100⟩이에요.","8 × ⟨316/100⟩ = ⟨2528/100⟩ = 25.28이에요."]},{"stem":"4 × 3.14를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨314/100⟩","correct":true},{"t":"4 × ⟨314/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨4/10⟩ × ⟨314/100⟩","mis":"M5-2-u4-X03"},{"t":"4 + ⟨314/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","3.14 = ⟨314/100⟩예요.","4 × ⟨314/100⟩ = ⟨1256/100⟩ = 12.56이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#3','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'ox','auto','6 × 0.38은 6보다 작아요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C5","difficulty":1,"kind":"ox","stem":"6 × 0.38은 6보다 작아요.","answer":"O","reason_options":[{"t":"0.38은 1보다 작으므로","correct":true},{"t":"곱하면 늘 커지므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["곱하는 수 0.38을 1과 견주어요.","1보다 작으니 곱은 6보다 작아요.","6 × 0.38 = 2.28이에요."],"variant_rule":{"alt":[{"stem":"6 × 0.38 = 6 × ⟨38/100⟩로 계산할 수 있어요.","answer":"O","reason_options":[{"t":"0.38 = ⟨38/100⟩이므로","correct":true},{"t":"0.38은 ⟨38/10⟩이므로","mis":"M5-2-u4-X08"}],"explanation":["소수 두 자리 수는 분모가 100인 분수예요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요.","그래서 맞아요."]},{"stem":"8 × 3.16과 3.16 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"두 수의 자리를 바꾸어 곱해도 곱이 같으므로","correct":true},{"t":"앞의 수가 자연수일 때만 곱을 구할 수 있으므로","mis":"M5-2-u4-X18"}],"explanation":["8 × 3.16 = 25.28이에요.","3.16 × 8 = 25.28이에요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#4','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'mc','auto','8 × 3.16에서 3.16을 3으로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"8 × 3.16에서 3.16을 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"24","correct":true},{"t":"240","mis":"M5-2-u4-X02"},{"t":"32","mis":"M5-2-u4-X13"},{"t":"11","mis":"M5-2-u4-X05"}],"explanation":["3.16을 계산하기 쉬운 수 3으로 어림해요.","8 × 3 = 24예요.","실제 곱 8 × 3.16 = 25.28과 비슷해요."],"variant_rule":{"alt":[{"stem":"5 × 2.98에서 2.98을 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"15","correct":true},{"t":"150","mis":"M5-2-u4-X02"},{"t":"20","mis":"M5-2-u4-X13"},{"t":"8","mis":"M5-2-u4-X05"}],"explanation":["2.98을 계산하기 쉬운 수 3으로 어림해요.","5 × 3 = 15예요.","실제 곱 5 × 2.98 = 14.9와 비슷해요."]},{"stem":"4 × 3.14에서 3.14를 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"12","correct":true},{"t":"120","mis":"M5-2-u4-X02"},{"t":"16","mis":"M5-2-u4-X13"},{"t":"7","mis":"M5-2-u4-X05"}],"explanation":["3.14를 계산하기 쉬운 수 3으로 어림해요.","4 × 3 = 12예요.","실제 곱 4 × 3.14 = 12.56과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#5','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','19 × 0.33을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"19 × 0.33을 계산하면 얼마인가요?","options":[{"t":"6.27","correct":true},{"t":"627","mis":"M5-2-u4-X01"},{"t":"62.7","mis":"M5-2-u4-X02"},{"t":"0.627","mis":"M5-2-u4-X02"}],"explanation":["19 × 33 = 627이에요.","0.33은 33의 ⟨1/100⟩배이므로 곱도 627의 ⟨1/100⟩배예요.","19 × 0.33 = 6.27이에요."],"asset":{"type":"expr_grid","rows":[["","","1","9"],["×","0.","3","3"],["","?","?","?"]]},"variant_rule":{"alt":[{"stem":"2 × 4.52를 계산하면 얼마인가요?","options":[{"t":"9.04","correct":true},{"t":"904","mis":"M5-2-u4-X01"},{"t":"90.4","mis":"M5-2-u4-X02"},{"t":"0.904","mis":"M5-2-u4-X02"}],"explanation":["2 × 452 = 904예요.","4.52는 452의 ⟨1/100⟩배이므로 곱도 904의 ⟨1/100⟩배예요.","2 × 4.52 = 9.04예요."],"asset":{"type":"expr_grid","rows":[["","","","2"],["×","4.","5","2"],["","?","?","?"]]}},{"stem":"7 × 0.29를 계산하면 얼마인가요?","options":[{"t":"2.03","correct":true},{"t":"203","mis":"M5-2-u4-X01"},{"t":"20.3","mis":"M5-2-u4-X02"},{"t":"0.203","mis":"M5-2-u4-X02"}],"explanation":["7 × 29 = 203이에요.","0.29는 29의 ⟨1/100⟩배이므로 곱도 203의 ⟨1/100⟩배예요.","7 × 0.29 = 2.03이에요."],"asset":{"type":"expr_grid","rows":[["","","","7"],["×","0.","2","9"],["","?","?","?"]]}},{"stem":"4 × 3.24를 계산하면 얼마인가요?","options":[{"t":"12.96","correct":true},{"t":"1296","mis":"M5-2-u4-X01"},{"t":"129.6","mis":"M5-2-u4-X02"},{"t":"1.296","mis":"M5-2-u4-X02"}],"explanation":["4 × 324 = 1296이에요.","3.24는 324의 ⟨1/100⟩배이므로 곱도 1296의 ⟨1/100⟩배예요.","4 × 3.24 = 12.96이에요."],"asset":{"type":"expr_grid","rows":[["","","","","4"],["×","","3.","2","4"],["","?","?","?","?"]]}},{"stem":"56 × 0.27을 계산하면 얼마인가요?","options":[{"t":"15.12","correct":true},{"t":"1512","mis":"M5-2-u4-X01"},{"t":"151.2","mis":"M5-2-u4-X02"},{"t":"1.512","mis":"M5-2-u4-X02"}],"explanation":["56 × 27 = 1512예요.","0.27은 27의 ⟨1/100⟩배이므로 곱도 1512의 ⟨1/100⟩배예요.","56 × 0.27 = 15.12예요."],"asset":{"type":"expr_grid","rows":[["","","","5","6"],["×","","0.","2","7"],["","?","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#6','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','화성에서 잰 무게는 지구에서 잰 무게의 0.38배라고 해요. 지구에서 6 kg인 강아지를 화성에서 재면 몇 kg일까요?',ARRAY['M5-2-u4-X02','M5-2-u4-X01','M5-2-u4-X17']::text[],true,'{"seq":6,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"화성에서 잰 무게는 지구에서 잰 무게의 0.38배라고 해요. 지구에서 6 kg인 강아지를 화성에서 재면 몇 kg일까요?","options":[{"t":"2.28 kg","correct":true},{"t":"22.8 kg","mis":"M5-2-u4-X02"},{"t":"228 kg","mis":"M5-2-u4-X01"},{"t":"6.38 kg","mis":"M5-2-u4-X17"}],"explanation":["「6의 0.38배」이므로 식은 6 × 0.38이에요.","6 × 38 = 228의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 2.28 kg이에요 (1보다 작은 수를 곱해 작아졌어요)."],"variant_rule":{"alt":[{"stem":"150 cm 높이에서 떨어뜨린 공이 떨어진 높이의 0.71배만큼 튀어 올랐어요. 튀어 오른 높이는 몇 cm인가요?","options":[{"t":"106.5 cm","correct":true},{"t":"1065 cm","mis":"M5-2-u4-X02"},{"t":"10650 cm","mis":"M5-2-u4-X01"},{"t":"150.71 cm","mis":"M5-2-u4-X17"}],"explanation":["「150의 0.71배」이므로 식은 150 × 0.71이에요.","150 × 71 = 10650의 ⟨1/100⟩배예요.","150 × 0.71 = 106.5 — 106.5 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#7','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','재영이네 텃밭은 가로가 12 m, 세로가 6.05 m인 직사각형 모양이에요. 재영이네 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":7,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"재영이네 텃밭은 가로가 12 m, 세로가 6.05 m인 직사각형 모양이에요. 재영이네 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"72.6 m²","correct":true},{"t":"7260 m²","mis":"M5-2-u4-X01"},{"t":"7.26 m²","mis":"M5-2-u4-X02"},{"t":"36.1 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","12 × 605 = 7260이에요.","12 × 6.05 = 72.6 — 넓이는 72.6 m²예요."],"variant_rule":{"alt":[{"stem":"도영이가 그린 직사각형의 가로는 12 cm예요. 직사각형의 세로가 가로의 2.5배일 때 세로는 몇 cm인가요?","options":[{"t":"30 cm","correct":true},{"t":"14.5 cm","mis":"M5-2-u4-X17"},{"t":"300 cm","mis":"M5-2-u4-X01"},{"t":"3 cm","mis":"M5-2-u4-X02"}],"explanation":["「12 cm의 2.5배」는 12 × 2.5예요.","12 × 25 = 300이에요. 곱은 그 ⟨1/10⟩배예요.","12 × 2.5 = 30 — 30 cm예요."]},{"stem":"가로가 4 cm이고 세로가 2.56 cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"10.24 cm²","correct":true},{"t":"6.56 cm²","mis":"M5-2-u4-X17"},{"t":"1024 cm²","mis":"M5-2-u4-X01"},{"t":"102.4 cm²","mis":"M5-2-u4-X02"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 4 × 2.56이에요.","4 × 256 = 1024예요. 곱은 그 ⟨1/100⟩배예요.","4 × 2.56 = 10.24 — 10.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#8','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'ox','auto','6 × 0.38 = 22.8이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":2,"kind":"ox","stem":"6 × 0.38 = 22.8이에요.","answer":"X","reason_options":[{"t":"6 × 38 = 228의 ⟨1/100⟩배인 2.28이므로","correct":true},{"t":"6 × 38 = 228의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["6 × 38 = 228이에요.","0.38은 38의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 22.8은 6보다 커서 틀려요."],"variant_rule":{"alt":[{"stem":"8 × 3.16을 어림하면 24쯤이에요.","answer":"O","reason_options":[{"t":"3.16을 3으로 어림하면 8 × 3 = 24이므로","correct":true},{"t":"3.16을 4로 어림해야 하므로","mis":"M5-2-u4-X14"}],"explanation":["3.16은 3에 가까워요.","8 × 3 = 24예요.","8 × 3.16 = 25.28 — 24와 비슷해요."]},{"stem":"12 × 2.5 = 3이에요.","answer":"X","reason_options":[{"t":"12 × 25 = 300의 ⟨1/10⟩배인 30이므로","correct":true},{"t":"12 × 25 = 300의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["12 × 25 = 300이에요.","2.5는 25의 ⟨1/10⟩배예요.","12 × 2.5 = 30 — 2.5가 1보다 크니 12보다 커야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#9','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','9 × 28 = 252예요. 9 × 0.28을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":9,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"9 × 28 = 252예요. 9 × 0.28을 계산하면 얼마인가요?","options":[{"t":"2.52","correct":true},{"t":"252","mis":"M5-2-u4-X01"},{"t":"25.2","mis":"M5-2-u4-X02"},{"t":"0.252","mis":"M5-2-u4-X02"}],"explanation":["9와 0.28의 소수점 아래 자릿수는 0개와 2개예요.","0 + 2 = 2 — 252에서 소수점을 왼쪽으로 두 자리 옮겨요.","9 × 0.28 = 2.52예요."],"variant_rule":{"alt":[{"stem":"6 × 38 = 228이에요. 6 × 0.38을 계산하면 얼마인가요?","options":[{"t":"2.28","correct":true},{"t":"228","mis":"M5-2-u4-X01"},{"t":"22.8","mis":"M5-2-u4-X02"},{"t":"0.228","mis":"M5-2-u4-X02"}],"explanation":["6과 0.38의 소수점 아래 자릿수는 0개와 2개예요.","0 + 2 = 2 — 228에서 소수점을 왼쪽으로 두 자리 옮겨요.","6 × 0.38 = 2.28이에요."]},{"stem":"8 × 316 = 2528이에요. 8 × 3.16을 계산하면 얼마인가요?","options":[{"t":"25.28","correct":true},{"t":"2528","mis":"M5-2-u4-X01"},{"t":"252.8","mis":"M5-2-u4-X02"},{"t":"2.528","mis":"M5-2-u4-X02"}],"explanation":["8과 3.16의 소수점 아래 자릿수는 0개와 2개예요.","0 + 2 = 2 — 2528에서 소수점을 왼쪽으로 두 자리 옮겨요.","8 × 3.16 = 25.28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_basic#10','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',3,'mc','auto','수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":10,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"29.58","correct":true},{"t":"2958","mis":"M5-2-u4-X01"},{"t":"295.8","mis":"M5-2-u4-X02"},{"t":"2.958","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 87이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.34가 돼요.","87 × 0.34 = 29.58이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#1','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',2,'mc','auto','4 × 3.24를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"4 × 3.24를 계산하면 얼마인가요?","options":[{"t":"12.96","correct":true},{"t":"1296","mis":"M5-2-u4-X01"},{"t":"129.6","mis":"M5-2-u4-X02"},{"t":"1.296","mis":"M5-2-u4-X02"}],"explanation":["4 × 324 = 1296이에요.","3.24는 324의 ⟨1/100⟩배이므로 곱도 1296의 ⟨1/100⟩배예요.","4 × 3.24 = 12.96이에요."],"variant_rule":{"alt":[{"stem":"5 × 2.98을 계산하면 얼마인가요?","options":[{"t":"14.9","correct":true},{"t":"1490","mis":"M5-2-u4-X01"},{"t":"149","mis":"M5-2-u4-X02"},{"t":"1.49","mis":"M5-2-u4-X02"}],"explanation":["5 × 298 = 1490이에요.","2.98은 298의 ⟨1/100⟩배이므로 곱도 1490의 ⟨1/100⟩배예요.","5 × 2.98 = 14.9예요."]},{"stem":"56 × 0.27을 계산하면 얼마인가요?","options":[{"t":"15.12","correct":true},{"t":"1512","mis":"M5-2-u4-X01"},{"t":"151.2","mis":"M5-2-u4-X02"},{"t":"1.512","mis":"M5-2-u4-X02"}],"explanation":["56 × 27 = 1512예요.","0.27은 27의 ⟨1/100⟩배이므로 곱도 1512의 ⟨1/100⟩배예요.","56 × 0.27 = 15.12예요."]},{"stem":"19 × 0.33을 계산하면 얼마인가요?","options":[{"t":"6.27","correct":true},{"t":"627","mis":"M5-2-u4-X01"},{"t":"62.7","mis":"M5-2-u4-X02"},{"t":"0.627","mis":"M5-2-u4-X02"}],"explanation":["19 × 33 = 627이에요.","0.33은 33의 ⟨1/100⟩배이므로 곱도 627의 ⟨1/100⟩배예요.","19 × 0.33 = 6.27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#2','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',2,'mc','auto','8 × 3.16과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X17','M5-2-u4-X02']::text[],true,'{"seq":2,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"8 × 3.16과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"3.16 × 8","correct":true},{"t":"8 × 316","mis":"M5-2-u4-X01"},{"t":"3.16 + 8","mis":"M5-2-u4-X17"},{"t":"0.316 × 8","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","8 × 3.16 = 25.28이에요.","3.16 × 8 = 25.28 — 그래서 같아요."],"variant_rule":{"alt":[{"stem":"6 × 0.38과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"0.38 × 6","correct":true},{"t":"6 × 38","mis":"M5-2-u4-X01"},{"t":"0.38 + 6","mis":"M5-2-u4-X17"},{"t":"0.038 × 6","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","6 × 0.38 = 2.28이에요.","0.38 × 6 = 2.28 — 그래서 같아요."]},{"stem":"4 × 3.14와 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"3.14 × 4","correct":true},{"t":"4 × 314","mis":"M5-2-u4-X01"},{"t":"3.14 + 4","mis":"M5-2-u4-X17"},{"t":"0.314 × 4","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","4 × 3.14 = 12.56이에요.","3.14 × 4 = 12.56 — 그래서 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#3','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'error','auto','6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C5","difficulty":3,"kind":"error","stem":"6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.28이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"6 × 38을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.38은 38의 ⟨1/100⟩배이므로 곱도 6 × 38 = 228의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 6보다 작아야 하는데 22.8은 6보다 커요.","바른 곱은 2.28이에요."],"variant_rule":{"alt":[{"stem":"7 × 0.29를 20.3으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.03이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"7 × 29를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.29는 29의 ⟨1/100⟩배이므로 곱도 7 × 29 = 203의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 7보다 작아야 하는데 20.3은 7보다 커요.","바른 곱은 2.03이에요."]},{"stem":"9 × 0.28을 25.2로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.52이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"9 × 28을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.28은 28의 ⟨1/100⟩배이므로 곱도 9 × 28 = 252의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 9보다 작아야 하는데 25.2는 9보다 커요.","바른 곱은 2.52예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#4','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'mc','auto','성진이네 가족이 지난달에 사용한 물은 494 L예요. 이번 달에 사용한 물이 지난달의 0.85배라면 이번 달에 사용한 물은 몇 L인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"성진이네 가족이 지난달에 사용한 물은 494 L예요. 이번 달에 사용한 물이 지난달의 0.85배라면 이번 달에 사용한 물은 몇 L인가요?","options":[{"t":"419.9 L","correct":true},{"t":"494.85 L","mis":"M5-2-u4-X17"},{"t":"41990 L","mis":"M5-2-u4-X01"},{"t":"4199 L","mis":"M5-2-u4-X02"}],"explanation":["「494 L의 0.85배」는 494 × 0.85예요.","494 × 85 = 41990이에요. 곱은 그 ⟨1/100⟩배예요.","494 × 0.85 = 419.9 — 419.9 L예요."],"variant_rule":{"alt":[{"stem":"150 cm 높이에서 떨어뜨린 공이 떨어진 높이의 0.71배만큼 튀어 올랐어요. 튀어 오른 높이는 몇 cm인가요?","options":[{"t":"106.5 cm","correct":true},{"t":"1065 cm","mis":"M5-2-u4-X02"},{"t":"10650 cm","mis":"M5-2-u4-X01"},{"t":"150.71 cm","mis":"M5-2-u4-X17"}],"explanation":["「150의 0.71배」이므로 식은 150 × 0.71이에요.","150 × 71 = 10650의 ⟨1/100⟩배예요.","150 × 0.71 = 106.5 — 106.5 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#5','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'mc','auto','150 cm 높이에서 축구공을 떨어뜨렸더니 떨어진 높이의 0.71배만큼 튀어 올랐어요. 튀어 오른 높이는 떨어뜨린 높이보다 몇 cm 낮은가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X02']::text[],false,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"150 cm 높이에서 축구공을 떨어뜨렸더니 떨어진 높이의 0.71배만큼 튀어 올랐어요. 튀어 오른 높이는 떨어뜨린 높이보다 몇 cm 낮은가요?","options":[{"t":"43.5 cm","correct":true},{"t":"106.5 cm","mis":"M5-2-u4-X18"},{"t":"139.35 cm","mis":"M5-2-u4-X02"},{"t":"435 cm","mis":"M5-2-u4-X02"}],"explanation":["튀어 오른 높이는 150 × 0.71이에요.","150 × 71 = 10650의 ⟨1/100⟩배 — 106.5 cm예요.","150 − 106.5 = 43.5 — 43.5 cm 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#6','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'ox','auto','12 × 2.5 = 3이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C5","difficulty":3,"kind":"ox","stem":"12 × 2.5 = 3이에요.","answer":"X","reason_options":[{"t":"12 × 25 = 300의 ⟨1/10⟩배인 30이므로","correct":true},{"t":"12 × 25 = 300의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["12 × 25 = 300이에요.","2.5는 25의 ⟨1/10⟩배예요.","12 × 2.5 = 30 — 2.5가 1보다 크니 12보다 커야 해요."],"variant_rule":{"alt":[{"stem":"6 × 0.38 = 22.8이에요.","answer":"X","reason_options":[{"t":"6 × 38 = 228의 ⟨1/100⟩배인 2.28이므로","correct":true},{"t":"6 × 38 = 228의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["6 × 38 = 228이에요.","0.38은 38의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 22.8은 6보다 커서 틀려요."]},{"stem":"8 × 3.16을 어림하면 24쯤이에요.","answer":"O","reason_options":[{"t":"3.16을 3으로 어림하면 8 × 3 = 24이므로","correct":true},{"t":"3.16을 4로 어림해야 하므로","mis":"M5-2-u4-X14"}],"explanation":["3.16은 3에 가까워요.","8 × 3 = 24예요.","8 × 3.16 = 25.28 — 24와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#7','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C5","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"19 × 0.33","r":"6.27"},{"l":"2 × 4.52","r":"9.04"},{"l":"7 × 0.29","r":"2.03"}],"mis":"M5-2-u4-X02","explanation":["소수점을 생각하지 않고 자연수끼리 곱한 뒤, 소수의 자릿수만큼 곱의 소수점을 찍어요.","19 × 0.33 = 6.27 · 2 × 4.52 = 9.04예요.","7 × 0.29 = 2.03이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"4 × 3.24","r":"12.96"},{"l":"5 × 2.98","r":"14.9"},{"l":"56 × 0.27","r":"15.12"}],"explanation":["소수점을 생각하지 않고 자연수끼리 곱한 뒤, 소수의 자릿수만큼 곱의 소수점을 찍어요.","4 × 3.24 = 12.96 · 5 × 2.98 = 14.9예요.","56 × 0.27 = 15.12예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#8','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'essay','teacher','화성에서 잰 무게는 지구에서 잰 무게의 0.38배예요. 지구에서 6 kg인 강아지의 화성 몸무게를 친구가 22.8 kg이라고 했어요. 친구의 답이 틀린 까닭을 쓰고, 두 가지 방법으로 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"화성에서 잰 무게는 지구에서 잰 무게의 0.38배예요. 지구에서 6 kg인 강아지의 화성 몸무게를 친구가 22.8 kg이라고 했어요. 친구의 답이 틀린 까닭을 쓰고, 두 가지 방법으로 바르게 계산해 보세요.","answer_guide":{"answer":"예: 0.38은 1보다 작으므로 곱은 6보다 작아야 하는데 22.8은 6보다 커서 틀렸다. 분수로 — 6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이다. 자연수로 — 6 × 38 = 228이고 0.38은 38의 ⟨1/100⟩배이므로 곱은 228의 ⟨1/100⟩배인 2.28이다. 화성에서 강아지의 몸무게는 2.28 kg이다.","scoring_points":["곱이 6보다 작아야 해서 22.8은 틀렸다고 했는가","분수의 곱셈으로 2.28을 구했는가","자연수의 곱셈과 ⟨1/100⟩배로 2.28을 구했는가"]},"explanation":["0.38 < 1이니 곱은 6보다 작아요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요.","228의 ⟨1/100⟩배 — 2.28 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#9','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'essay','teacher','수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들어 곱하려고 해요. 두 수를 만드는 방법을 쓰고 곱을 구한 뒤, 곱이 가장 큰 두 자리 수보다 작은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들어 곱하려고 해요. 두 수를 만드는 방법을 쓰고 곱을 구한 뒤, 곱이 가장 큰 두 자리 수보다 작은 까닭을 쓰세요.","answer_guide":{"answer":"예: 큰 카드 8과 7로 가장 큰 두 자리 수 87을 만든다. 남은 0, 3, 4로 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.34가 된다. 87 × 34 = 2958이므로 87 × 0.34 = 29.58이다. 곱하는 수 0.34가 1보다 작으므로 곱은 87보다 작다.","scoring_points":["87과 0.34를 바르게 만들었는가","87 × 0.34 = 29.58을 구했는가","0.34가 1보다 작아 곱이 87보다 작다고 설명했는가"]},"explanation":["가장 큰 두 자리 수는 87, 가장 작은 소수 두 자리 수는 0.34예요.","87 × 0.34 = 29.58이에요.","0.34 < 1이라 곱은 87보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L05_challenge#10','math',5,2,'u4','L05','tb_g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'essay','teacher','8 × 3.16은 얼마쯤일지 어림한 다음, 여러 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용 · 3.16 × 8로 바꾸기)으로 계산하고 계산 결과와 어림한 값을 비교해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"8 × 3.16은 얼마쯤일지 어림한 다음, 여러 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용 · 3.16 × 8로 바꾸기)으로 계산하고 계산 결과와 어림한 값을 비교해 보세요.","answer_guide":{"answer":"예: 3.16을 3으로 어림하면 8 × 3 = 24이므로 24쯤이다. 분수로 — 8 × ⟨316/100⟩ = ⟨2528/100⟩ = 25.28이다. 자연수로 — 8 × 316 = 2528이고 3.16은 316의 ⟨1/100⟩배이므로 곱은 2528의 ⟨1/100⟩배인 25.28이다. 3.16 × 8로 바꾸어 계산해도 25.28이다. 계산 결과 25.28과 어림한 값 24가 비슷하다.","scoring_points":["3.16을 3으로 어림해 24쯤이라고 했는가","두 가지 이상의 방법으로 25.28을 구했는가","25.28과 24가 비슷하다고 비교했는가"]},"explanation":["8 × 3 = 24쯤이에요.","8 × 3.16 = 25.28이에요.","25.28과 24는 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#1','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'mc','auto','넓이가 1인 정사각형 모눈종이를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?',ARRAY['M5-2-u4-X09','M5-2-u4-X12','M5-2-u4-X18']::text[],false,'{"seq":1,"concept":"M5-2-u4-C6","difficulty":1,"kind":"mc","stem":"넓이가 1인 정사각형 모눈종이를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?","options":[{"t":"0.01","correct":true},{"t":"0.1","mis":"M5-2-u4-X09"},{"t":"0.001","mis":"M5-2-u4-X12"},{"t":"10","mis":"M5-2-u4-X18"}],"explanation":["가로·세로 10칸씩이면 모두 10 × 10 = 100칸이에요.","한 칸은 100칸 중의 1칸 — ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[4,0],[5,0],[5,1],[4,1]]},{"p":[[5,0],[6,0],[6,1],[5,1]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[8,0],[9,0],[9,1],[8,1]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[5,1],[6,1],[6,2],[5,2]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[1,2],[2,2],[2,3],[1,3]]},{"p":[[2,2],[3,2],[3,3],[2,3]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[5,2],[6,2],[6,3],[5,3]]},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[2,3],[3,3],[3,4],[2,4]]},{"p":[[3,3],[4,3],[4,4],[3,4]]},{"p":[[4,3],[5,3],[5,4],[4,4]]},{"p":[[5,3],[6,3],[6,4],[5