INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#3','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'ox','auto','0.6 × 0.9 = 0.54예요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C6","difficulty":1,"kind":"ox","stem":"0.6 × 0.9 = 0.54예요.","answer":"O","reason_options":[{"t":"0.01인 칸이 6 × 9 = 54칸이므로","correct":true},{"t":"6 × 9 = 54의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["모눈 한 칸은 0.01이에요.","가로 6칸, 세로 9칸 — 6 × 9 = 54칸이에요.","0.6 × 0.9 = 0.54 — 맞아요."],"variant_rule":{"alt":[{"stem":"1을 100칸으로 나눈 모눈에서 한 칸은 0.01이에요.","answer":"O","reason_options":[{"t":"100칸 중의 1칸은 ⟨1/100⟩ = 0.01이므로","correct":true},{"t":"한 줄이 10칸이니 한 칸은 0.1이므로","mis":"M5-2-u4-X09"}],"explanation":["전체 1을 100칸으로 나누었어요.","한 칸은 ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01 — 맞아요."]},{"stem":"0.6 × 0.8은 0.6보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 수 0.8이 1보다 작으므로","correct":true},{"t":"두 수를 곱하면 늘 커지므로","mis":"M5-2-u4-X06"}],"explanation":["0.8은 1보다 작아요.","그러니 곱은 0.6보다 작아요.","0.6 × 0.8 = 0.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#4','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'mc','auto','도서관 벽화를 나누어 그려요. 내가 맡은 곳은 가로 0.6 m, 세로 0.9 m인 직사각형이에요. 그려야 할 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X18','M5-2-u4-X01']::text[],false,'{"seq":4,"concept":"M5-2-u4-C6","difficulty":1,"kind":"mc","stem":"도서관 벽화를 나누어 그려요. 내가 맡은 곳은 가로 0.6 m, 세로 0.9 m인 직사각형이에요. 그려야 할 넓이는 몇 m²인가요?","options":[{"t":"0.54 m²","correct":true},{"t":"5.4 m²","mis":"M5-2-u4-X03"},{"t":"3 m²","mis":"M5-2-u4-X18"},{"t":"54 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 0.6 × 0.9예요.","6 × 9 = 54이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","0.6 × 0.9 = 0.54 — 0.54 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#5','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','1.9 × 3.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],true,'{"seq":5,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"1.9 × 3.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨19/10⟩ × ⟨36/10⟩","correct":true},{"t":"⟨19/100⟩ × ⟨36/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/19⟩ × ⟨36/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨19/10⟩ × ⟨36/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.9 = ⟨19/10⟩ · 3.6 = ⟨36/10⟩이에요.","⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩ = 6.84예요."],"variant_rule":{"alt":[{"stem":"0.6 × 0.9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨6/10⟩ × ⟨9/10⟩","correct":true},{"t":"⟨6/100⟩ × ⟨9/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/6⟩ × ⟨9/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨6/10⟩ × ⟨9/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.6 = ⟨6/10⟩ · 0.9 = ⟨9/10⟩예요.","⟨6/10⟩ × ⟨9/10⟩ = ⟨54/100⟩ = 0.54예요."]},{"stem":"3.4 × 6.4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨34/10⟩ × ⟨64/10⟩","correct":true},{"t":"⟨34/100⟩ × ⟨64/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/34⟩ × ⟨64/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨34/10⟩ × ⟨64/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","3.4 = ⟨34/10⟩ · 6.4 = ⟨64/10⟩예요.","⟨34/10⟩ × ⟨64/10⟩ = ⟨2176/100⟩ = 21.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#6','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','19 × 36 = 684예요. 1.9 × 3.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"19 × 36 = 684예요. 1.9 × 3.6을 계산하면 얼마인가요?","options":[{"t":"6.84","correct":true},{"t":"68.4","mis":"M5-2-u4-X03"},{"t":"684","mis":"M5-2-u4-X01"},{"t":"0.684","mis":"M5-2-u4-X02"}],"explanation":["1.9와 3.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 684에서 소수점을 왼쪽으로 두 자리 옮겨요.","1.9 × 3.6 = 6.84예요."],"variant_rule":{"alt":[{"stem":"6 × 9 = 54예요. 0.6 × 0.9를 계산하면 얼마인가요?","options":[{"t":"0.54","correct":true},{"t":"5.4","mis":"M5-2-u4-X03"},{"t":"54","mis":"M5-2-u4-X01"},{"t":"0.054","mis":"M5-2-u4-X02"}],"explanation":["0.6과 0.9의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 54에서 소수점을 왼쪽으로 두 자리 옮겨요.","0.6 × 0.9 = 0.54예요."]},{"stem":"32 × 6 = 192예요. 3.2 × 0.6을 계산하면 얼마인가요?","options":[{"t":"1.92","correct":true},{"t":"19.2","mis":"M5-2-u4-X03"},{"t":"192","mis":"M5-2-u4-X01"},{"t":"0.192","mis":"M5-2-u4-X02"}],"explanation":["3.2와 0.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 192에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.2 × 0.6 = 1.92예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#7','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','1.9 × 9.2를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"1.9 × 9.2를 계산하면 얼마인가요?","options":[{"t":"17.48","correct":true},{"t":"174.8","mis":"M5-2-u4-X03"},{"t":"1748","mis":"M5-2-u4-X01"},{"t":"1.748","mis":"M5-2-u4-X02"}],"explanation":["19 × 92 = 1748이에요.","1.9는 19의 ⟨1/10⟩배, 9.2는 92의 ⟨1/10⟩배예요.","그래서 곱은 1748의 ⟨1/100⟩배인 17.48이에요."],"asset":{"type":"expr_grid","rows":[["","","","1.","9"],["×","","","9.","2"],["","?","?","?","?"]]},"variant_rule":{"alt":[{"stem":"0.8 × 0.6을 계산하면 얼마인가요?","options":[{"t":"0.48","correct":true},{"t":"4.8","mis":"M5-2-u4-X03"},{"t":"48","mis":"M5-2-u4-X01"},{"t":"0.048","mis":"M5-2-u4-X02"}],"explanation":["8 × 6 = 48이에요.","0.8은 8의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","그래서 곱은 48의 ⟨1/100⟩배인 0.48이에요."],"asset":{"type":"expr_grid","rows":[["","","0.","8"],["×","","0.","6"],["","?","?","?"]]}},{"stem":"1.8 × 3.7을 계산하면 얼마인가요?","options":[{"t":"6.66","correct":true},{"t":"66.6","mis":"M5-2-u4-X03"},{"t":"666","mis":"M5-2-u4-X01"},{"t":"0.666","mis":"M5-2-u4-X02"}],"explanation":["18 × 37 = 666이에요.","1.8은 18의 ⟨1/10⟩배, 3.7은 37의 ⟨1/10⟩배예요.","그래서 곱은 666의 ⟨1/100⟩배인 6.66이에요."],"asset":{"type":"expr_grid","rows":[["","","1.","8"],["×","","3.","7"],["","?","?","?"]]}},{"stem":"3.4 × 6.4를 계산하면 얼마인가요?","options":[{"t":"21.76","correct":true},{"t":"217.6","mis":"M5-2-u4-X03"},{"t":"2176","mis":"M5-2-u4-X01"},{"t":"2.176","mis":"M5-2-u4-X02"}],"explanation":["34 × 64 = 2176이에요.","3.4는 34의 ⟨1/10⟩배, 6.4는 64의 ⟨1/10⟩배예요.","그래서 곱은 2176의 ⟨1/100⟩배인 21.76이에요."],"asset":{"type":"expr_grid","rows":[["","","","3.","4"],["×","","","6.","4"],["","?","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#8','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'sa','auto','0.4 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C6","difficulty":2,"kind":"sa","stem":"0.4 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["0.4는 0.1이 4개, 0.3은 0.1이 3개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 4 × 3 = 12개예요.","0.4 × 0.3 = 0.12예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.2 × 1.5의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["0.2는 0.1이 2개, 1.5는 0.1이 15개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 2 × 15 = 30개예요.","0.2 × 1.5 = 0.3이에요."]},{"stem":"0.8 × 0.6의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["0.8은 0.1이 8개, 0.6은 0.1이 6개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 8 × 6 = 48개예요.","0.8 × 0.6 = 0.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#9','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','빨간색 끈은 1.5 m예요. 노란색 끈이 빨간색 끈의 1.2배라면 노란색 끈은 몇 m인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X03','M5-2-u4-X01']::text[],false,'{"seq":9,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"빨간색 끈은 1.5 m예요. 노란색 끈이 빨간색 끈의 1.2배라면 노란색 끈은 몇 m인가요?","options":[{"t":"1.8 m","correct":true},{"t":"2.7 m","mis":"M5-2-u4-X17"},{"t":"18 m","mis":"M5-2-u4-X03"},{"t":"180 m","mis":"M5-2-u4-X01"}],"explanation":["「1.5의 1.2배」는 곱셈 1.5 × 1.2예요.","15 × 12 = 180이에요.","1.5 × 1.2 = 1.8 — 노란색 끈은 1.8 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_basic#10','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',3,'mc','auto','배드민턴 복식 경기장은 가로가 13.4 m, 세로가 6.1 m인 직사각형 모양이에요. 배드민턴 복식 경기장의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],false,'{"seq":10,"concept":"M5-2-u4-C6","difficulty":3,"kind":"mc","stem":"배드민턴 복식 경기장은 가로가 13.4 m, 세로가 6.1 m인 직사각형 모양이에요. 배드민턴 복식 경기장의 넓이는 몇 m²인가요?","options":[{"t":"81.74 m²","correct":true},{"t":"817.4 m²","mis":"M5-2-u4-X03"},{"t":"19.5 m²","mis":"M5-2-u4-X17"},{"t":"8174 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 13.4 × 6.1이에요.","134 × 61 = 8174예요. 곱은 그 ⟨1/100⟩배예요.","13.4 × 6.1 = 81.74 — 81.74 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#1','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',2,'mc','auto','3.4 × 6.4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"3.4 × 6.4를 계산하면 얼마인가요?","options":[{"t":"21.76","correct":true},{"t":"217.6","mis":"M5-2-u4-X03"},{"t":"2176","mis":"M5-2-u4-X01"},{"t":"2.176","mis":"M5-2-u4-X02"}],"explanation":["34 × 64 = 2176이에요.","3.4는 34의 ⟨1/10⟩배, 6.4는 64의 ⟨1/10⟩배예요.","그래서 곱은 2176의 ⟨1/100⟩배인 21.76이에요."],"variant_rule":{"alt":[{"stem":"3.2 × 0.6을 계산하면 얼마인가요?","options":[{"t":"1.92","correct":true},{"t":"19.2","mis":"M5-2-u4-X03"},{"t":"192","mis":"M5-2-u4-X01"},{"t":"0.192","mis":"M5-2-u4-X02"}],"explanation":["32 × 6 = 192예요.","3.2는 32의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","그래서 곱은 192의 ⟨1/100⟩배인 1.92예요."]},{"stem":"1.8 × 3.7을 계산하면 얼마인가요?","options":[{"t":"6.66","correct":true},{"t":"66.6","mis":"M5-2-u4-X03"},{"t":"666","mis":"M5-2-u4-X01"},{"t":"0.666","mis":"M5-2-u4-X02"}],"explanation":["18 × 37 = 666이에요.","1.8은 18의 ⟨1/10⟩배, 3.7은 37의 ⟨1/10⟩배예요.","그래서 곱은 666의 ⟨1/100⟩배인 6.66이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#2','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',2,'mc','auto','0.2 × 1.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X02']::text[],false,'{"seq":2,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"0.2 × 1.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.3","correct":true},{"t":"0.03","mis":"M5-2-u4-X02"},{"t":"3","mis":"M5-2-u4-X02"},{"t":"30","mis":"M5-2-u4-X02"}],"explanation":["2 × 15 = 30이에요.","두 수의 소수점 아래 자릿수의 합은 2 — 곱은 0.30이에요.","끝자리 0을 생략하면 0.3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#3','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'error','auto','75.9 × 0.6을 다음과 같이 세로로 계산했어요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C6","difficulty":3,"kind":"error","stem":"75.9 × 0.6을 다음과 같이 세로로 계산했어요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4554의 ⟨1/100⟩배인 45.54이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"759 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","곱은 759 × 6 = 4554의 ⟨1/100⟩배여야 해요.","바른 곱은 45.54예요."],"asset":{"type":"expr_grid","rows":[["","","7","5.","9"],["×","","","0.","6"],["","4","5","5.","4"]]},"variant_rule":{"alt":[{"stem":"1.9 × 3.6을 다음과 같이 세로로 계산했어요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 684의 ⟨1/100⟩배인 6.84이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"19 × 36을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","곱은 19 × 36 = 684의 ⟨1/100⟩배여야 해요.","바른 곱은 6.84예요."],"asset":{"type":"expr_grid","rows":[["","","1.","9"],["×","","3.","6"],["","6","8.","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#4','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'ox','auto','1.9 × 3.6 = 68.4예요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":4,"concept":"M5-2-u4-C6","difficulty":3,"kind":"ox","stem":"1.9 × 3.6 = 68.4예요.","answer":"X","reason_options":[{"t":"두 수가 모두 ⟨1/10⟩배라 곱은 684의 ⟨1/100⟩배인 6.84이므로","correct":true},{"t":"한 수만 ⟨1/10⟩배로 보면 되므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["19 × 36 = 684예요.","곱은 ⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩배예요.","1.9 × 3.6 = 6.84예요."],"variant_rule":{"alt":[{"stem":"1.9 × 3.6 = ⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩예요.","answer":"O","reason_options":[{"t":"분모끼리 10 × 10 = 100, 분자끼리 19 × 36 = 684이므로","correct":true},{"t":"분모는 곱하지 않고 10 그대로 두므로","mis":"M5-2-u4-X08"}],"explanation":["1.9 = ⟨19/10⟩, 3.6 = ⟨36/10⟩이에요.","분모끼리·분자끼리 곱해요.","⟨684/100⟩ = 6.84예요."]},{"stem":"0.2 × 1.5의 곱은 0.1이 3개예요.","answer":"O","reason_options":[{"t":"0.2 × 1.5 = 0.3이므로","correct":true},{"t":"2 × 15 = 30이므로 0.1이 30개이므로","mis":"M5-2-u4-X09"}],"explanation":["2 × 15 = 30이에요.","곱은 30의 ⟨1/100⟩배 — 0.30 = 0.3이에요.","0.3은 0.1이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#5','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C6","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.8 × 0.6","r":"0.48"},{"l":"1.9 × 9.2","r":"17.48"},{"l":"0.2 × 1.5","r":"0.3"}],"mis":"M5-2-u4-X03","explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","0.8 × 0.6 = 0.48 · 1.9 × 9.2 = 17.48이에요.","0.2 × 1.5 = 0.3이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"1.8 × 3.7","r":"6.66"},{"l":"0.4 × 0.3","r":"0.12"},{"l":"3.2 × 0.6","r":"1.92"}],"explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","1.8 × 3.7 = 6.66 · 0.4 × 0.3 = 0.12예요.","3.2 × 0.6 = 1.92예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#6','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'mc','auto','한 변의 길이가 7.5 cm인 정사각형 모양의 색종이를 직사각형 모양이 되도록 반으로 접었더니 가로가 처음의 0.5배가 되었어요. 반으로 접은 색종이의 가로는 몇 cm인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":3,"kind":"mc","stem":"한 변의 길이가 7.5 cm인 정사각형 모양의 색종이를 직사각형 모양이 되도록 반으로 접었더니 가로가 처음의 0.5배가 되었어요. 반으로 접은 색종이의 가로는 몇 cm인가요?","options":[{"t":"3.75 cm","correct":true},{"t":"37.5 cm","mis":"M5-2-u4-X03"},{"t":"8 cm","mis":"M5-2-u4-X17"},{"t":"375 cm","mis":"M5-2-u4-X01"}],"explanation":["「7.5 cm의 0.5배」는 7.5 × 0.5예요.","75 × 5 = 375예요. 곱은 그 ⟨1/100⟩배예요.","7.5 × 0.5 = 3.75 — 3.75 cm예요."],"variant_rule":{"alt":[{"stem":"가로가 4 cm이고 세로가 2.56 cm인 직사각형의 넓이는 몇 cm²인가요?","options":[{"t":"10.24 cm²","correct":true},{"t":"6.56 cm²","mis":"M5-2-u4-X17"},{"t":"1024 cm²","mis":"M5-2-u4-X01"},{"t":"102.4 cm²","mis":"M5-2-u4-X02"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 4 × 2.56이에요.","4 × 256 = 1024예요. 곱은 그 ⟨1/100⟩배예요.","4 × 2.56 = 10.24 — 10.24 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#7','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'mc','auto','전체 크기가 1인 정사각형 모눈종이에 가로 6칸, 세로 8칸을 색칠했어요. 색칠한 부분의 넓이를 나타내는 곱셈식은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X17','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C6","difficulty":3,"kind":"mc","stem":"전체 크기가 1인 정사각형 모눈종이에 가로 6칸, 세로 8칸을 색칠했어요. 색칠한 부분의 넓이를 나타내는 곱셈식은 어느 것인가요?","options":[{"t":"0.6 × 0.8","correct":true},{"t":"6 × 8","mis":"M5-2-u4-X01"},{"t":"0.6 + 0.8","mis":"M5-2-u4-X17"},{"t":"0.06 × 0.08","mis":"M5-2-u4-X02"}],"explanation":["모눈 한 줄은 10칸 — 가로 6칸은 0.6, 세로 8칸은 0.8이에요.","한 칸은 0.01이고 색칠한 칸은 6 × 8 = 48칸이에요.","그래서 0.6 × 0.8 = 0.48이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[5,0],[6,0],[6,1],[5,1]],"hi":true},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[8,0],[9,0],[9,1],[8,1]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[3,1],[4,1],[4,2],[3,2]],"hi":true},{"p":[[4,1],[5,1],[5,2],[4,2]],"hi":true},{"p":[[5,1],[6,1],[6,2],[5,2]],"hi":true},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]],"hi":true},{"p":[[1,2],[2,2],[2,3],[1,3]],"hi":true},{"p":[[2,2],[3,2],[3,3],[2,3]],"hi":true},{"p":[[3,2],[4,2],[4,3],[3,3]],"hi":true},{"p":[[4,2],[5,2],[5,3],[4,3]],"hi":true},{"p":[[5,2],[6,2],[6,3],[5,3]],"hi":true},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},