INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#8','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'essay','teacher','가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.","answer_guide":{"answer":"예: 넓이 1인 정사각형을 가로·세로 10칸씩 나누면 모두 100칸이고 한 칸의 넓이는 ⟨1/100⟩ = 0.01이다. 가로 6칸, 세로 9칸을 칠하면 6 × 9 = 54칸이다. 0.01이 54칸이므로 0.6 × 0.9 = 0.54이고 벽화의 넓이는 0.54 m²이다.","scoring_points":["한 칸의 넓이가 0.01임을 밝혔는가","칠한 칸 6 × 9 = 54칸을 구했는가","0.54 m²를 구했는가"]},"explanation":["100칸 중의 1칸 — 한 칸은 0.01이에요.","6 × 9 = 54칸이에요.","0.6 × 0.9 = 0.54(m²)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#9','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'essay','teacher','1.9 × 3.6을 분수의 곱셈으로 계산하는 방법과 자연수의 곱셈 19 × 36을 이용하는 방법으로 각각 계산하고, 곱이 소수 두 자리 수가 되는 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"1.9 × 3.6을 분수의 곱셈으로 계산하는 방법과 자연수의 곱셈 19 × 36을 이용하는 방법으로 각각 계산하고, 곱이 소수 두 자리 수가 되는 까닭을 써 보세요.","answer_guide":{"answer":"예: 분수로 — ⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩ = 6.84이다. 자연수로 — 19 × 36 = 684이고 1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배이므로 1.9 × 3.6은 684의 ⟨1/100⟩배인 6.84이다. 두 수가 모두 ⟨1/10⟩배이므로 곱은 ⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩배가 되어 소수 두 자리 수이다.","scoring_points":["분수의 곱셈으로 6.84를 구했는가","19 × 36 = 684의 ⟨1/100⟩배로 6.84를 구했는가","⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩이라 소수 두 자리라고 설명했는가"]},"explanation":["⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩ = 6.84예요.","19 × 36 = 684의 ⟨1/100⟩배예요.","⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩ — 소수 두 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L06_challenge#10','math',5,2,'u4','L06','tb_g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'essay','teacher','75.9 × 0.6을 455.4로 잘못 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"75.9 × 0.6을 455.4로 잘못 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 759 × 6 = 4554이고 75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배이므로 75.9 × 0.6은 4554의 ⟨1/100⟩배인 45.54이다. 455.4는 한 수의 소수점 아래 자릿수만 생각해 4554의 ⟨1/10⟩배로 계산한 것이다. 0.6이 1보다 작으므로 곱은 75.9보다 작아야 하는데 455.4는 75.9보다 커서 틀렸다.","scoring_points":["두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배라고 설명했는가","바른 곱 45.54를 구했는가","어림(0.6 < 1)로 455.4가 틀렸음을 밝혔는가"]},"explanation":["759 × 6 = 4554예요.","곱은 4554의 ⟨1/100⟩배 — 45.54예요.","0.6 < 1이니 곱은 75.9보다 작아야 해요."],"asset":{"type":"expr_grid","rows":[["","","7","5.","9"],["×","","","0.","6"],["","4","5","5.","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#1','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'mc','auto','해달 인형의 길이는 0.47 m이고, 물고기 인형의 길이는 해달 인형의 0.3배예요. 물고기 인형의 길이는 몇 m인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"해달 인형의 길이는 0.47 m이고, 물고기 인형의 길이는 해달 인형의 0.3배예요. 물고기 인형의 길이는 몇 m인가요?","options":[{"t":"0.141 m","correct":true},{"t":"1.41 m","mis":"M5-2-u4-X03"},{"t":"0.77 m","mis":"M5-2-u4-X17"},{"t":"141 m","mis":"M5-2-u4-X01"}],"explanation":["「0.47의 0.3배」는 0.47 × 0.3이에요.","47 × 3 = 141이고 곱은 그 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141 — 0.141 m예요."],"variant_rule":{"alt":[{"stem":"현우는 가족들과 함께 사과즙과 배즙을 만들었어요. 사과즙은 0.9 L 만들고 배즙은 사과즙의 0.25배만큼 만들었다면 배즙은 몇 L인가요?","options":[{"t":"0.225 L","correct":true},{"t":"2.25 L","mis":"M5-2-u4-X03"},{"t":"1.15 L","mis":"M5-2-u4-X17"},{"t":"225 L","mis":"M5-2-u4-X01"}],"explanation":["「0.9의 0.25배」는 0.9 × 0.25예요.","9 × 25 = 225이고 곱은 그 ⟨1/1000⟩배예요.","0.9 × 0.25 = 0.225 — 0.225 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#2','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'mc','auto','0.47 × 0.3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],true,'{"seq":2,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"0.47 × 0.3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨47/100⟩ × ⟨3/10⟩","correct":true},{"t":"⟨47/1000⟩ × ⟨3/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/47⟩ × ⟨3/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨47/100⟩ × ⟨3/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.47 = ⟨47/100⟩ · 0.3 = ⟨3/10⟩이에요.","⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩ = 0.141이에요."],"variant_rule":{"alt":[{"stem":"5.1 × 1.12를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨51/10⟩ × ⟨112/100⟩","correct":true},{"t":"⟨51/100⟩ × ⟨112/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/51⟩ × ⟨112/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨51/10⟩ × ⟨112/1000⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","5.1 = ⟨51/10⟩ · 1.12 = ⟨112/100⟩예요.","⟨51/10⟩ × ⟨112/100⟩ = ⟨5712/1000⟩ = 5.712예요."]},{"stem":"1.7 × 5.31을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨17/10⟩ × ⟨531/100⟩","correct":true},{"t":"⟨17/100⟩ × ⟨531/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/17⟩ × ⟨531/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨17/10⟩ × ⟨531/1000⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.7 = ⟨17/10⟩ · 5.31 = ⟨531/100⟩이에요.","⟨17/10⟩ × ⟨531/100⟩ = ⟨9027/1000⟩ = 9.027이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#3','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'sa','auto','2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2.5는 소수 한 자리, 1.89는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 2.5 × 1.89 = 4.725 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.47은 소수 두 자리, 0.3은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 0.47 × 0.3 = 0.141 — 소수 세 자리 수예요."]},{"stem":"3.8 × 0.26의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3.8은 소수 한 자리, 0.26은 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 3.8 × 0.26 = 0.988 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#4','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'ox','auto','0.47 × 0.3 = 0.141이에요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":4,"concept":"M5-2-u4-C7","difficulty":1,"kind":"ox","stem":"0.47 × 0.3 = 0.141이에요.","answer":"O","reason_options":[{"t":"47 × 3 = 141의 ⟨1/1000⟩배이므로","correct":true},{"t":"47 × 3 = 141의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["47 × 3 = 141이에요.","0.47은 ⟨1/100⟩배, 0.3은 ⟨1/10⟩배 — 곱은 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141 — 맞아요."],"variant_rule":{"alt":[{"stem":"5.1 × 1.12는 5쯤이에요.","answer":"O","reason_options":[{"t":"5.1을 5로, 1.12를 1로 어림하면 5 × 1 = 5이므로","correct":true},{"t":"5.1 × 1.12는 51 × 112와 같으므로","mis":"M5-2-u4-X01"}],"explanation":["5.1은 5에, 1.12는 1에 가까워요.","5 × 1 = 5예요.","5.1 × 1.12 = 5.712 — 5쯤이에요."]},{"stem":"2.5 × 1.89의 곱은 소수 세 자리 수예요.","answer":"O","reason_options":[{"t":"소수 한 자리 수와 두 자리 수의 곱이라 1 + 2 = 3자리이므로","correct":true},{"t":"자릿수가 더 많은 1.89만 세어 두 자리이므로","mis":"M5-2-u4-X03"}],"explanation":["2.5는 한 자리, 1.89는 두 자리예요.","1 + 2 = 3 — 소수 세 자리 수예요.","2.5 × 1.89 = 4.725예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#5','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','5.1 × 1.12는 얼마쯤일지 어림하려고 해요. 5.1을 5로, 1.12를 1로 어림하면 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X05']::text[],false,'{"seq":5,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"5.1 × 1.12는 얼마쯤일지 어림하려고 해요. 5.1을 5로, 1.12를 1로 어림하면 얼마쯤인가요?","options":[{"t":"5쯤","correct":true},{"t":"50쯤","mis":"M5-2-u4-X02"},{"t":"0.5쯤","mis":"M5-2-u4-X02"},{"t":"6쯤","mis":"M5-2-u4-X05"}],"explanation":["5.1은 5에, 1.12는 1에 가까워요.","5 × 1 = 5예요.","실제로 5.1 × 1.12 = 5.712 — 5쯤과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#6','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','5.07 × 1.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"5.07 × 1.3을 계산하면 얼마인가요?","options":[{"t":"6.591","correct":true},{"t":"65.91","mis":"M5-2-u4-X03"},{"t":"6591","mis":"M5-2-u4-X01"},{"t":"0.6591","mis":"M5-2-u4-X02"}],"explanation":["507 × 13 = 6591이에요.","5.07은 507의 ⟨1/100⟩배, 1.3은 13의 ⟨1/10⟩배예요.","그래서 곱은 6591의 ⟨1/1000⟩배인 6.591이에요."],"asset":{"type":"expr_grid","rows":[["","","5.","0","7"],["×","","","1.","3"],["","?","?","?","?"]]},"variant_rule":{"alt":[{"stem":"3.8 × 0.26을 계산하면 얼마인가요?","options":[{"t":"0.988","correct":true},{"t":"9.88","mis":"M5-2-u4-X03"},{"t":"988","mis":"M5-2-u4-X01"},{"t":"0.0988","mis":"M5-2-u4-X02"}],"explanation":["38 × 26 = 988이에요.","3.8은 38의 ⟨1/10⟩배, 0.26은 26의 ⟨1/100⟩배예요.","그래서 곱은 988의 ⟨1/1000⟩배인 0.988이에요."],"asset":{"type":"expr_grid","rows":[["","","","3.","8"],["×","","0.","2","6"],["","?","?","?","?"]]}},{"stem":"2.5 × 1.89를 계산하면 얼마인가요?","options":[{"t":"4.725","correct":true},{"t":"47.25","mis":"M5-2-u4-X03"},{"t":"4725","mis":"M5-2-u4-X01"},{"t":"0.4725","mis":"M5-2-u4-X02"}],"explanation":["25 × 189 = 4725예요.","2.5는 25의 ⟨1/10⟩배, 1.89는 189의 ⟨1/100⟩배예요.","그래서 곱은 4725의 ⟨1/1000⟩배인 4.725예요."],"asset":{"type":"expr_grid","rows":[["","","","2.","5"],["×","","1.","8","9"],["","?","?","?","?"]]}},{"stem":"0.32 × 4.5를 계산하면 얼마인가요?","options":[{"t":"1.44","correct":true},{"t":"14.4","mis":"M5-2-u4-X03"},{"t":"1440","mis":"M5-2-u4-X01"},{"t":"0.144","mis":"M5-2-u4-X02"}],"explanation":["32 × 45 = 1440이에요.","0.32는 32의 ⟨1/100⟩배, 4.5는 45의 ⟨1/10⟩배예요.","그래서 곱은 1440의 ⟨1/1000⟩배인 1.440이에요 — 끝자리 0은 생략해 1.44로 써요."],"asset":{"type":"expr_grid","rows":[["","","0.","3","2"],["×","","","4.","5"],["","?","?","?","?"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#7','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','51 × 112 = 5712예요. 5.1 × 1.12를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"51 × 112 = 5712예요. 5.1 × 1.12를 계산하면 얼마인가요?","options":[{"t":"5.712","correct":true},{"t":"57.12","mis":"M5-2-u4-X03"},{"t":"5712","mis":"M5-2-u4-X01"},{"t":"0.5712","mis":"M5-2-u4-X02"}],"explanation":["5.1과 1.12의 소수점 아래 자릿수는 1개와 2개예요.","1 + 2 = 3 — 5712에서 소수점을 왼쪽으로 세 자리 옮겨요.","5.1 × 1.12 = 5.712예요."],"variant_rule":{"alt":[{"stem":"47 × 3 = 141이에요. 0.47 × 0.3을 계산하면 얼마인가요?","options":[{"t":"0.141","correct":true},{"t":"1.41","mis":"M5-2-u4-X03"},{"t":"141","mis":"M5-2-u4-X01"},{"t":"0.0141","mis":"M5-2-u4-X02"}],"explanation":["0.47과 0.3의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 141에서 소수점을 왼쪽으로 세 자리 옮겨요.","0.47 × 0.3 = 0.141이에요."]},{"stem":"17 × 531 = 9027이에요. 1.7 × 5.31을 계산하면 얼마인가요?","options":[{"t":"9.027","correct":true},{"t":"90.27","mis":"M5-2-u4-X03"},{"t":"9027","mis":"M5-2-u4-X01"},{"t":"0.9027","mis":"M5-2-u4-X02"}],"explanation":["1.7과 5.31의 소수점 아래 자릿수는 1개와 2개예요.","1 + 2 = 3 — 9027에서 소수점을 왼쪽으로 세 자리 옮겨요.","1.7 × 5.31 = 9.027이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#8','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 0.4 × 0.26은 0.12보다 …',ARRAY['M5-2-u4-X06','M5-2-u4-X14']::text[],true,'{"seq":8,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.4 × 0.26은 0.12보다 …","options":[{"t":"작다 — 0.26은 0.3보다 작다","correct":true},{"t":"크다 — 0.26이 1보다 작다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.4 × 0.3 = 0.12이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.4 × 0.3 = 0.12를 기준으로 삼아요.","0.26은 0.3보다 작아요 — 그래서 곱도 0.12보다 작아요.","실제로 0.4 × 0.26 = 0.104예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 4.21 × 0.5는 2보다 …","options":[{"t":"크다 — 4.21은 4보다 크다","correct":true},{"t":"작다 — 0.5가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 4 × 0.5 = 2이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["4 × 0.5 = 2를 기준으로 삼아요.","4.21은 4보다 커요 — 그래서 곱도 2보다 커요.","실제로 4.21 × 0.5 = 2.105예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.3 × 0.26은 0.09보다 …","options":[{"t":"작다 — 0.26은 0.3보다 작다","correct":true},{"t":"크다 — 0.26이 1보다 작다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.3 × 0.3 = 0.09이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.3 × 0.3 = 0.09를 기준으로 삼아요.","0.26은 0.3보다 작아요 — 그래서 곱도 0.09보다 작아요.","실제로 0.3 × 0.26 = 0.078이에요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.81 × 0.5는 1.9보다 …","options":[{"t":"크다 — 3.81은 3.8보다 크다","correct":true},{"t":"작다 — 0.5가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3.8 × 0.5 = 1.9이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3.8 × 0.5 = 1.9를 기준으로 삼아요.","3.81은 3.8보다 커요 — 그래서 곱도 1.9보다 커요.","실제로 3.81 × 0.5 = 1.905예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#9','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','0.32 × 4.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X04']::text[],false,'{"seq":9,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"0.32 × 4.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"1.44","correct":true},{"t":"0.144","mis":"M5-2-u4-X02"},{"t":"14.4","mis":"M5-2-u4-X02"},{"t":"1.4","mis":"M5-2-u4-X04"}],"explanation":["32 × 45 = 1440이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 1.440이에요.","끝자리 0을 생략하면 1.44예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_basic#10','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',3,'sa','auto','0.75 × 3.6 < 2.□에서 □ 안에 들어갈 수 있는 9 이하의 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u4-C7","difficulty":3,"kind":"sa","stem":"0.75 × 3.6 < 2.□에서 □ 안에 들어갈 수 있는 9 이하의 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["75 × 36 = 2700이고 곱은 그 ⟨1/1000⟩배 — 0.75 × 3.6 = 2.7이에요.","2.□가 2.7보다 커야 하므로 □는 7보다 커야 해요 — 7을 넣으면 2.7과 같아 안 돼요.","□는 8, 9 — 모두 2개예요."],"mis":"M5-2-u4-X19","variant_rule":{"alt":[{"stem":"9.4 × 3.61 < □ < 7.13 × 5.5에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9.4 × 3.61 = 33.934, 7.13 × 5.5 = 39.215예요.","33.934 < □ < 39.215이므로 □는 34부터 39까지예요 — 33과 40은 안 돼요.","34, 35, 36, 37, 38, 39 — 모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#1','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',2,'mc','auto','2.5 × 1.89를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"2.5 × 1.89를 계산하면 얼마인가요?","options":[{"t":"4.725","correct":true},{"t":"47.25","mis":"M5-2-u4-X03"},{"t":"4725","mis":"M5-2-u4-X01"},{"t":"0.4725","mis":"M5-2-u4-X02"}],"explanation":["25 × 189 = 4725예요.","2.5는 25의 ⟨1/10⟩배, 1.89는 189의 ⟨1/100⟩배예요.","그래서 곱은 4725의 ⟨1/1000⟩배인 4.725예요."],"variant_rule":{"alt":[{"stem":"3.8 × 0.26을 계산하면 얼마인가요?","options":[{"t":"0.988","correct":true},{"t":"9.88","mis":"M5-2-u4-X03"},{"t":"988","mis":"M5-2-u4-X01"},{"t":"0.0988","mis":"M5-2-u4-X02"}],"explanation":["38 × 26 = 988이에요.","3.8은 38의 ⟨1/10⟩배, 0.26은 26의 ⟨1/100⟩배예요.","그래서 곱은 988의 ⟨1/1000⟩배인 0.988이에요."]},{"stem":"2.64 × 0.6을 계산하면 얼마인가요?","options":[{"t":"1.584","correct":true},{"t":"15.84","mis":"M5-2-u4-X03"},{"t":"1584","mis":"M5-2-u4-X01"},{"t":"0.1584","mis":"M5-2-u4-X02"}],"explanation":["264 × 6 = 1584예요.","2.64는 264의 ⟨1/100⟩배, 0.6은 6의 ⟨1/10⟩배예요.","그래서 곱은 1584의 ⟨1/1000⟩배인 1.584예요."]},{"stem":"0.4 × 0.72를 계산하면 얼마인가요?","options":[{"t":"0.288","correct":true},{"t":"2.88","mis":"M5-2-u4-X03"},{"t":"288","mis":"M5-2-u4-X01"},{"t":"0.0288","mis":"M5-2-u4-X02"}],"explanation":["4 × 72 = 288이에요.","0.4는 4의 ⟨1/10⟩배, 0.72는 72의 ⟨1/100⟩배예요.","그래서 곱은 288의 ⟨1/1000⟩배인 0.288이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#2','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',2,'mc','auto','5.1 × 1.12는 5.1 × 1과 5.1 × 0.12를 더한 것과 같아요. 5.1 × 0.12는 얼마이고, 5.1 × 1.12는 얼마인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X03','M5-2-u4-X18']::text[],false,'{"seq":2,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"5.1 × 1.12는 5.1 × 1과 5.1 × 0.12를 더한 것과 같아요. 5.1 × 0.12는 얼마이고, 5.1 × 1.12는 얼마인가요?","options":[{"t":"0.612, 5.712","correct":true},{"t":"6.12, 11.22","mis":"M5-2-u4-X02"},{"t":"0.0612, 5.1612","mis":"M5-2-u4-X03"},{"t":"0.612, 3.1212","mis":"M5-2-u4-X18"}],"explanation":["1.12 = 1 + 0.12예요.","51 × 12 = 612이고 곱은 그 ⟨1/1000⟩배 — 5.1 × 0.12 = 0.612예요.","5.1 × 1 + 5.1 × 0.12 = 5.1 + 0.612 = 5.712예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#3','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','태하네 학교에서는 작년에 플라스틱 병뚜껑을 2.7 kg 모았어요. 올해 모은 병뚜껑의 양이 작년의 1.48배라면 올해 모은 병뚜껑은 몇 kg인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"태하네 학교에서는 작년에 플라스틱 병뚜껑을 2.7 kg 모았어요. 올해 모은 병뚜껑의 양이 작년의 1.48배라면 올해 모은 병뚜껑은 몇 kg인가요?","options":[{"t":"3.996 kg","correct":true},{"t":"39.96 kg","mis":"M5-2-u4-X03"},{"t":"4.18 kg","mis":"M5-2-u4-X17"},{"t":"3996 kg","mis":"M5-2-u4-X01"}],"explanation":["「2.7의 1.48배」는 2.7 × 1.48이에요.","27 × 148 = 3996이고 곱은 그 ⟨1/1000⟩배예요.","2.7 × 1.48 = 3.996 — 3.996 kg이에요."],"variant_rule":{"alt":[{"stem":"현우는 가족들과 함께 사과즙과 배즙을 만들었어요. 사과즙은 0.9 L 만들고 배즙은 사과즙의 0.25배만큼 만들었다면 배즙은 몇 L인가요?","options":[{"t":"0.225 L","correct":true},{"t":"2.25 L","mis":"M5-2-u4-X03"},{"t":"1.15 L","mis":"M5-2-u4-X17"},{"t":"225 L","mis":"M5-2-u4-X01"}],"explanation":["「0.9의 0.25배」는 0.9 × 0.25예요.","9 × 25 = 225이고 곱은 그 ⟨1/1000⟩배예요.","0.9 × 0.25 = 0.225 — 0.225 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#4','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','배드민턴 단식 경기장은 길이가 13.4 m, 폭이 5.18 m인 직사각형 모양이에요. 배드민턴 단식 경기장의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],false,'{"seq":4,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"배드민턴 단식 경기장은 길이가 13.4 m, 폭이 5.18 m인 직사각형 모양이에요. 배드민턴 단식 경기장의 넓이는 몇 m²인가요?","options":[{"t":"69.412 m²","correct":true},{"t":"694.12 m²","mis":"M5-2-u4-X03"},{"t":"18.58 m²","mis":"M5-2-u4-X17"},{"t":"69412 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 길이 × 폭이므로 13.4 × 5.18이에요.","134 × 518 = 69412예요. 곱은 그 ⟨1/1000⟩배예요.","13.4 × 5.18 = 69.412 — 69.412 m²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#5','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','1.7 × 5.31을 자연수의 곱셈 17 × 531 = 9027을 이용해 계산하려고 해요. 1.7 × 5.31의 곱은 9027의 몇 배인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X10']::text[],true,'{"seq":5,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"1.7 × 5.31을 자연수의 곱셈 17 × 531 = 9027을 이용해 계산하려고 해요. 1.7 × 5.31의 곱은 9027의 몇 배인가요?","options":[{"t":"⟨1/1000⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/100⟩배","mis":"M5-2-u4-X03"},{"t":"1000배","mis":"M5-2-u4-X10"}],"explanation":["1.7은 17의 ⟨1/10⟩배, 5.31은 531의 ⟨1/100⟩배예요.","그래서 곱은 9027의 ⟨1/1000⟩배예요.","1.7 × 5.31 = 9.027이에요."],"variant_rule":{"alt":[{"stem":"0.47 × 0.3을 자연수의 곱셈 47 × 3 = 141을 이용해 계산하려고 해요. 0.47 × 0.3의 곱은 141의 몇 배인가요?","options":[{"t":"⟨1/1000⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/100⟩배","mis":"M5-2-u4-X03"},{"t":"1000배","mis":"M5-2-u4-X10"}],"explanation":["0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","그래서 곱은 141의 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141이에요."]},{"stem":"5.1 × 1.12를 자연수의 곱셈 51 × 112 = 5712를 이용해 계산하려고 해요. 5.1 × 1.12의 곱은 5712의 몇 배인가요?","options":[{"t":"⟨1/1000⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/100⟩배","mis":"M5-2-u4-X03"},{"t":"1000배","mis":"M5-2-u4-X10"}],"explanation":["5.1은 51의 ⟨1/10⟩배, 1.12는 112의 ⟨1/100⟩배예요.","그래서 곱은 5712의 ⟨1/1000⟩배예요.","5.1 × 1.12 = 5.712예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#6','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'ox','auto','0.32 × 4.5의 곱 1.440은 1.44로 쓸 수 있어요.',ARRAY['M5-2-u4-X04']::text[],true,'{"seq":6,"concept":"M5-2-u4-C7","difficulty":3,"kind":"ox","stem":"0.32 × 4.5의 곱 1.440은 1.44로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"끝자리 0은 생략해도 크기가 같으므로","correct":true},{"t":"끝자리 0을 생략하면 0.144가 되므로","mis":"M5-2-u4-X04"}],"mis":"M5-2-u4-X04","explanation":["32 × 45 = 1440이에요.","곱은 ⟨1/1000⟩배인 1.440이에요.","끝자리 0을 생략해 1.44로 써요."],"variant_rule":{"alt":[{"stem":"0.47 × 0.3 = 0.141이에요.","answer":"O","reason_options":[{"t":"47 × 3 = 141의 ⟨1/1000⟩배이므로","correct":true},{"t":"47 × 3 = 141의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X03"}],"explanation":["47 × 3 = 141이에요.","0.47은 ⟨1/100⟩배, 0.3은 ⟨1/10⟩배 — 곱은 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141 — 맞아요."]},{"stem":"2.5 × 1.89의 곱은 소수 세 자리 수예요.","answer":"O","reason_options":[{"t":"소수 한 자리 수와 두 자리 수의 곱이라 1 + 2 = 3자리이므로","correct":true},{"t":"자릿수가 더 많은 1.89만 세어 두 자리이므로","mis":"M5-2-u4-X03"}],"explanation":["2.5는 한 자리, 1.89는 두 자리예요.","1 + 2 = 3 — 소수 세 자리 수예요.","2.5 × 1.89 = 4.725예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#7','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"5.07 × 1.3","r":"6.591"},{"l":"3.8 × 0.26","r":"0.988"},{"l":"0.32 × 4.5","r":"1.44"}],"mis":"M5-2-u4-X03","explanation":["두 수의 소수점 아래 자릿수를 더한 만큼 곱의 소수점을 찍어요.","5.07 × 1.3 = 6.591 · 3.8 × 0.26 = 0.988이에요.","0.32 × 4.5 = 1.44예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"2.5 × 1.89","r":"4.725"},{"l":"0.4 × 0.72","r":"0.288"},{"l":"2.64 × 0.6","r":"1.584"}],"explanation":["두 수의 소수점 아래 자릿수를 더한 만큼 곱의 소수점을 찍어요.","2.5 × 1.89 = 4.725 · 0.4 × 0.72 = 0.288이에요.","2.64 × 0.6 = 1.584예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#8','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'essay','teacher','해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩ = 0.141이다. 자연수로 — 47 × 3 = 141이고 0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배이므로 곱은 141의 ⟨1/1000⟩배인 0.141이다. 소수 두 자리 수와 한 자리 수를 곱했으므로 곱은 2 + 1 = 3, 소수 세 자리 수이다. 물고기 인형은 0.141 m이다.","scoring_points":["분수의 곱셈으로 0.141을 구했는가","자연수의 곱셈과 ⟨1/1000⟩배로 0.141을 구했는가","소수점 아래 자릿수 2 + 1 = 3이라고 설명했는가"]},"explanation":["⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩이에요.","141의 ⟨1/1000⟩배는 0.141이에요.","2 + 1 = 3 — 소수 세 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#9','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'essay','teacher','5.1 × 1.12는 얼마쯤일지 어림하고, 분수의 곱셈과 자연수의 곱셈을 이용하는 방법으로 계산한 다음, 계산 결과와 어림한 값을 비교해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"5.1 × 1.12는 얼마쯤일지 어림하고, 분수의 곱셈과 자연수의 곱셈을 이용하는 방법으로 계산한 다음, 계산 결과와 어림한 값을 비교해 보세요.","answer_guide":{"answer":"예: 5.1을 5로, 1.12를 1로 어림하면 5 × 1 = 5이므로 5쯤이다. 분수로 — ⟨51/10⟩ × ⟨112/100⟩ = ⟨5712/1000⟩ = 5.712이다. 자연수로 — 51 × 112 = 5712이고 5.1은 51의 ⟨1/10⟩배, 1.12는 112의 ⟨1/100⟩배이므로 곱은 5712의 ⟨1/1000⟩배인 5.712이다. 계산 결과 5.712와 어림한 값 5가 비슷하다.","scoring_points":["5쯤으로 어림했는가","두 가지 방법으로 5.712를 구했는가","5.712와 5가 비슷하다고 비교했는가"]},"explanation":["5 × 1 = 5쯤이에요.","⟨51/10⟩ × ⟨112/100⟩ = ⟨5712/1000⟩ = 5.712예요.","5.712는 5와 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L07_challenge#10','math',5,2,'u4','L07','tb_g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'essay','teacher','0.75 × 3.6 < 2.□에서 □ 안에 들어갈 수 있는 9 이하의 자연수는 모두 몇 개인지 구하는 과정을 쓰세요. 7이 들어갈 수 있는지도 밝혀 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"0.75 × 3.6 < 2.□에서 □ 안에 들어갈 수 있는 9 이하의 자연수는 모두 몇 개인지 구하는 과정을 쓰세요. 7이 들어갈 수 있는지도 밝혀 쓰세요.","answer_guide":{"answer":"예: 75 × 36 = 2700이고 0.75는 75의 ⟨1/100⟩배, 3.6은 36의 ⟨1/10⟩배이므로 0.75 × 3.6은 2700의 ⟨1/1000⟩배인 2.7이다. 2.□가 2.7보다 커야 하므로 □는 7보다 커야 한다. 7을 넣으면 2.7과 같아서 들어갈 수 없다. 들어갈 수 있는 9 이하의 자연수는 8, 9로 모두 2개이다.","scoring_points":["0.75 × 3.6 = 2.7을 구했는가","7은 같아서 들어갈 수 없다고 밝혔는가","8, 9 — 2개라고 답했는가"]},"explanation":["0.75 × 3.6 = 2.7이에요.","2.□가 2.7보다 커야 해요 — □는 7보다 커요.","8, 9 — 2개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#1','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 100번 양치하면 물을 몇 L 아낄 수 있나요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 100번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"481 L","correct":true},{"t":"0.0481 L","mis":"M5-2-u4-X10"},{"t":"48.1 L","mis":"M5-2-u4-X11"},{"t":"4810 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 100번 아끼니 4.81 × 100이에요.","100을 곱하면 소수점이 오른쪽으로 두 자리 옮겨져요.","4.81 × 100 = 481 — 481 L예요."],"variant_rule":{"alt":[{"stem":"양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 10번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"48.1 L","correct":true},{"t":"0.481 L","mis":"M5-2-u4-X10"},{"t":"4.81 L","mis":"M5-2-u4-X11"},{"t":"481 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 10번 아끼니 4.81 × 10이에요.","10을 곱하면 소수점이 오른쪽으로 한 자리 옮겨져요.","4.81 × 10 = 48.1 — 48.1 L예요."]},{"stem":"양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 1000번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"4810 L","correct":true},{"t":"0.00481 L","mis":"M5-2-u4-X10"},{"t":"481 L","mis":"M5-2-u4-X11"},{"t":"48100 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 1000번 아끼니 4.81 × 1000이에요.","1000을 곱하면 소수점이 오른쪽으로 세 자리 옮겨져요.","4.81 × 1000 = 4810 — 4810 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#2','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','4810 × 0.01을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":2,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"4810 × 0.01을 계산하면 얼마인가요?","options":[{"t":"48.1","correct":true},{"t":"481000","mis":"M5-2-u4-X10"},{"t":"4.81","mis":"M5-2-u4-X11"},{"t":"481","mis":"M5-2-u4-X11"}],"explanation":["0.01을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.01은 소수 두 자리 수 — 왼쪽으로 두 자리예요.","4810 × 0.01 = 48.1이에요."],"variant_rule":{"alt":[{"stem":"4810 × 0.1을 계산하면 얼마인가요?","options":[{"t":"481","correct":true},{"t":"48100","mis":"M5-2-u4-X10"},{"t":"48.1","mis":"M5-2-u4-X11"},{"t":"4810","mis":"M5-2-u4-X11"}],"explanation":["0.1을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.1은 소수 한 자리 수 — 왼쪽으로 한 자리예요.","4810 × 0.1 = 481이에요."]},{"stem":"4810 × 0.001을 계산하면 얼마인가요?","options":[{"t":"4.81","correct":true},{"t":"4810000","mis":"M5-2-u4-X10"},{"t":"0.481","mis":"M5-2-u4-X11"},{"t":"48.1","mis":"M5-2-u4-X11"}],"explanation":["0.001을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.001은 소수 세 자리 수 — 왼쪽으로 세 자리예요.","4810 × 0.001 = 4.81이에요."]},{"stem":"16 × 0.001을 계산하면 얼마인가요?","options":[{"t":"0.016","correct":true},{"t":"16000","mis":"M5-2-u4-X10"},{"t":"0.0016","mis":"M5-2-u4-X11"},{"t":"0.16","mis":"M5-2-u4-X11"}],"explanation":["0.001을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.001은 소수 세 자리 수 — 왼쪽으로 세 자리예요.","16 × 0.001 = 0.016이에요."]},{"stem":"31 × 0.01을 계산하면 얼마인가요?","options":[{"t":"0.31","correct":true},{"t":"3100","mis":"M5-2-u4-X10"},{"t":"0.031","mis":"M5-2-u4-X11"},{"t":"3.1","mis":"M5-2-u4-X11"}],"explanation":["0.01을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.01은 소수 두 자리 수 — 왼쪽으로 두 자리예요.","31 × 0.01 = 0.31이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#3','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','2.38 × 1000을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":3,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"2.38 × 1000을 계산하면 얼마인가요?","options":[{"t":"2380","correct":true},{"t":"0.00238","mis":"M5-2-u4-X10"},{"t":"23800","mis":"M5-2-u4-X11"},{"t":"238","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","2.38 × 1000 = 2380이에요."],"variant_rule":{"alt":[{"stem":"2.38 × 10을 계산하면 얼마인가요?","options":[{"t":"23.8","correct":true},{"t":"0.238","mis":"M5-2-u4-X10"},{"t":"238","mis":"M5-2-u4-X11"},{"t":"2.38","mis":"M5-2-u4-X11"}],"explanation":["10을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","10에는 0이 1개 — 오른쪽으로 한 자리예요.","2.38 × 10 = 23.8이에요."]},{"stem":"8.15 × 100을 계산하면 얼마인가요?","options":[{"t":"815","correct":true},{"t":"0.0815","mis":"M5-2-u4-X10"},{"t":"8150","mis":"M5-2-u4-X11"},{"t":"81.5","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","8.15 × 100 = 815예요."]},{"stem":"8.15 × 1000을 계산하면 얼마인가요?","options":[{"t":"8150","correct":true},{"t":"0.00815","mis":"M5-2-u4-X10"},{"t":"81500","mis":"M5-2-u4-X11"},{"t":"815","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","8.15 × 1000 = 8150이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#4','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'ox','auto','4.81 × 100 = 481이에요.',ARRAY['M5-2-u4-X10']::text[],true,'{"seq":4,"concept":"M5-2-u4-C8","difficulty":1,"kind":"ox","stem":"4.81 × 100 = 481이에요.","answer":"O","reason_options":[{"t":"100을 곱하면 소수점이 오른쪽으로 두 자리 옮겨지므로","correct":true},{"t":"100을 곱하면 소수점이 왼쪽으로 옮겨지므로","mis":"M5-2-u4-X10"}],"mis":"M5-2-u4-X10","explanation":["100에는 0이 2개예요.","소수점을 오른쪽으로 두 자리 옮겨요.","4.81 × 100 = 481 — 맞아요."],"variant_rule":{"alt":[{"stem":"4810 × 0.01 = 4.81이에요.","answer":"X","reason_options":[{"t":"0.01을 곱하면 소수점이 왼쪽으로 두 자리 옮겨져 48.1이므로","correct":true},{"t":"0.01을 곱하면 소수점이 세 자리 옮겨지므로","mis":"M5-2-u4-X11"}],"explanation":["0.01은 소수 두 자리 수예요.","왼쪽으로 두 자리 옮겨요.","4810 × 0.01 = 48.1이에요."]},{"stem":"2.38 × 1000 = 238이에요.","answer":"X","reason_options":[{"t":"1000을 곱하면 소수점이 오른쪽으로 세 자리 옮겨져 2380이므로","correct":true},{"t":"1000을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["1000에는 0이 3개예요.","오른쪽으로 세 자리 — 빈 자리는 0이에요.","2.38 × 1000 = 2380이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#5','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','9 × 7 = 63이에요. 0.09 × 0.7을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"9 × 7 = 63이에요. 0.09 × 0.7을 계산하면 얼마인가요?","options":[{"t":"0.063","correct":true},{"t":"0.63","mis":"M5-2-u4-X03"},{"t":"63","mis":"M5-2-u4-X01"},{"t":"0.0063","mis":"M5-2-u4-X02"}],"explanation":["0.09와 0.7의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 63에서 소수점을 왼쪽으로 세 자리 옮겨요.","0.09 × 0.7 = 0.063이에요."],"variant_rule":{"alt":[{"stem":"9 × 7 = 63이에요. 0.9 × 0.7을 계산하면 얼마인가요?","options":[{"t":"0.63","correct":true},{"t":"6.3","mis":"M5-2-u4-X03"},{"t":"63","mis":"M5-2-u4-X01"},{"t":"0.063","mis":"M5-2-u4-X02"}],"explanation":["0.9와 0.7의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 63에서 소수점을 왼쪽으로 두 자리 옮겨요.","0.9 × 0.7 = 0.63이에요."]},{"stem":"9 × 7 = 63이에요. 0.9 × 7을 계산하면 얼마인가요?","options":[{"t":"6.3","correct":true},{"t":"63","mis":"M5-2-u4-X01"},{"t":"0.63","mis":"M5-2-u4-X02"},{"t":"630","mis":"M5-2-u4-X02"}],"explanation":["0.9와 7의 소수점 아래 자릿수는 1개와 0개예요.","1 + 0 = 1 — 63에서 소수점을 왼쪽으로 한 자리 옮겨요.","0.9 × 7 = 6.3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#6','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'sa','auto','49 × 65 = 3185예요. 0.49 × 0.65의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C8","difficulty":2,"kind":"sa","stem":"49 × 65 = 3185예요. 0.49 × 0.65의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.49는 소수 두 자리, 0.65는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 2 = 4예요.","0.49 × 0.65 = 0.3185 — 소수 네 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"37 × 21 = 777이에요. 3.7 × 2.1의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["3.7은 소수 한 자리, 2.1은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 1 = 2예요.","3.7 × 2.1 = 7.77 — 소수 두 자리 수예요."]},{"stem":"25 × 11 = 275예요. 0.25 × 1.1의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.25는 소수 두 자리, 1.1은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","0.25 × 1.1 = 0.275 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#7','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','37 × 21 = 777이에요. 3.7 × 2.1을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"37 × 21 = 777이에요. 3.7 × 2.1을 계산하면 얼마인가요?","options":[{"t":"7.77","correct":true},{"t":"77.7","mis":"M5-2-u4-X03"},{"t":"777","mis":"M5-2-u4-X01"},{"t":"0.777","mis":"M5-2-u4-X02"}],"explanation":["3.7과 2.1의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77이에요."],"variant_rule":{"alt":[{"stem":"37 × 21 = 777이에요. 37 × 2.1을 계산하면 얼마인가요?","options":[{"t":"77.7","correct":true},{"t":"777","mis":"M5-2-u4-X01"},{"t":"7.77","mis":"M5-2-u4-X02"},{"t":"7770","mis":"M5-2-u4-X02"}],"explanation":["37과 2.1의 소수점 아래 자릿수는 0개와 1개예요.","0 + 1 = 1 — 777에서 소수점을 왼쪽으로 한 자리 옮겨요.","37 × 2.1 = 77.7이에요."]},{"stem":"49 × 65 = 3185예요. 0.49 × 65를 계산하면 얼마인가요?","options":[{"t":"31.85","correct":true},{"t":"3185","mis":"M5-2-u4-X01"},{"t":"318.5","mis":"M5-2-u4-X02"},{"t":"3.185","mis":"M5-2-u4-X02"}],"explanation":["0.49와 65의 소수점 아래 자릿수는 2개와 0개예요.","2 + 0 = 2 — 3185에서 소수점을 왼쪽으로 두 자리 옮겨요.","0.49 × 65 = 31.85예요."]},{"stem":"32 × 74 = 2368이에요. 0.032 × 74를 계산하면 얼마인가요?","options":[{"t":"2.368","correct":true},{"t":"2368","mis":"M5-2-u4-X01"},{"t":"23.68","mis":"M5-2-u4-X02"},{"t":"0.2368","mis":"M5-2-u4-X02"}],"explanation":["0.032와 74의 소수점 아래 자릿수는 3개와 0개예요.","3 + 0 = 3 — 2368에서 소수점을 왼쪽으로 세 자리 옮겨요.","0.032 × 74 = 2.368이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#8','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','다을은 「25 × 11 = 275니까 0.25 × 1.1 = 2.75」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"다을은 「25 × 11 = 275니까 0.25 × 1.1 = 2.75」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"다을 — 바른 곱은 0.275","correct":true},{"t":"봄이 — 바른 곱은 0.48","mis":"M5-2-u4-X18"},{"t":"다을 — 바른 곱은 27.5","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.25 × 1.1의 소수점 아래 자릿수는 2 + 1 = 3이에요.","0.06 × 0.8의 소수점 아래 자릿수는 2 + 1 = 3이에요.","다을의 말이 틀렸어요 — 바른 곱은 0.275예요."],"variant_rule":{"alt":[{"stem":"예건은 「138 × 46 = 6348이니까 13.8 × 4.6 = 634.8」, 주연은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"예건 — 바른 곱은 63.48","correct":true},{"t":"주연 — 바른 곱은 1.568","mis":"M5-2-u4-X18"},{"t":"예건 — 바른 곱은 6348","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["13.8 × 4.6의 소수점 아래 자릿수는 1 + 1 = 2예요.","0.49 × 0.32의 소수점 아래 자릿수는 2 + 2 = 4예요.","예건의 말이 틀렸어요 — 바른 곱은 63.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#9','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','계산 결과가 다른 것을 찾아보세요. 19.4 × 0.1 · 0.194 × 10 · 1940 × 0.01',ARRAY['M5-2-u4-X20']::text[],true,'{"seq":9,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"계산 결과가 다른 것을 찾아보세요. 19.4 × 0.1 · 0.194 × 10 · 1940 × 0.01","options":[{"t":"1940 × 0.01","correct":true},{"t":"19.4 × 0.1","mis":"M5-2-u4-X20"},{"t":"0.194 × 10","mis":"M5-2-u4-X20"},{"t":"모두 같다","mis":"M5-2-u4-X20"}],"explanation":["곱하는 수의 소수점 위치를 보고 곱의 소수점이 어디로 옮겨지는지 생각해요.","19.4 × 0.1 = 1.94, 0.194 × 10 = 1.94, 1940 × 0.01 = 19.4예요.","계산 결과가 다른 것은 1940 × 0.01이에요."],"variant_rule":{"alt":[{"stem":"계산 결과가 다른 것을 찾아보세요. 5 × 0.1 · 0.5 × 10 · 0.05 × 10 · 50 × 0.01","options":[{"t":"0.5 × 10","correct":true},{"t":"5 × 0.1","mis":"M5-2-u4-X20"},{"t":"0.05 × 10","mis":"M5-2-u4-X20"},{"t":"모두 같다","mis":"M5-2-u4-X20"}],"explanation":["곱하는 수의 소수점 위치를 보고 곱의 소수점이 어디로 옮겨지는지 생각해요.","5 × 0.1 = 0.5, 0.5 × 10 = 5, 0.05 × 10 = 0.5, 50 × 0.01 = 0.5예요.","계산 결과가 다른 것은 0.5 × 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_basic#10','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',3,'mc','auto','365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. 3.65 × □ = 9.125',ARRAY['M5-2-u4-X01','M5-2-u4-X03','M5-2-u4-X11']::text[],true,'{"seq":10,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. 3.65 × □ = 9.125","options":[{"t":"2.5","correct":true},{"t":"25","mis":"M5-2-u4-X01"},{"t":"0.25","mis":"M5-2-u4-X03"},{"t":"250","mis":"M5-2-u4-X11"}],"explanation":["곱해지는 수 3.65는 소수 두 자리 수이고, 곱 9.125는 소수 세 자리 수예요.","그래서 □는 소수 한 자리 수 — 25의 ⟨1/10⟩배인 2.5예요.","3.65 × 2.5 = 9.125예요."],"variant_rule":{"alt":[{"stem":"365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. □ × 0.25 = 912.5","options":[{"t":"3650","correct":true},{"t":"365","mis":"M5-2-u4-X11"},{"t":"36.5","mis":"M5-2-u4-X10"},{"t":"36500","mis":"M5-2-u4-X11"}],"explanation":["곱하는 수 0.25는 소수 두 자리 수이고, 곱 912.5는 소수 한 자리 수예요.","그래서 □는 365의 10배인 3650이어야 해요.","3650 × 0.25 = 912.5예요."]},{"stem":"564 × 13 = 7332를 이용하여 □ 안에 알맞은 수를 구하세요. 5.64 × □ = 7.332","options":[{"t":"1.3","correct":true},{"t":"13","mis":"M5-2-u4-X01"},{"t":"0.13","mis":"M5-2-u4-X03"},{"t":"130","mis":"M5-2-u4-X11"}],"explanation":["곱해지는 수 5.64는 소수 두 자리 수이고, 곱 7.332는 소수 세 자리 수예요.","그래서 □는 소수 한 자리 수 — 13의 ⟨1/10⟩배인 1.3이에요.","5.64 × 1.3 = 7.332예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#1','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',2,'mc','auto','0.09 × 0.07을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X12','M5-2-u4-X03','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"0.09 × 0.07을 계산하면 얼마인가요?","options":[{"t":"0.0063","correct":true},{"t":"0.063","mis":"M5-2-u4-X12"},{"t":"0.63","mis":"M5-2-u4-X03"},{"t":"0.00063","mis":"M5-2-u4-X11"}],"explanation":["9 × 7 = 63이에요.","소수점 아래 자릿수가 2 + 2 = 4 — 63에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.0063이에요."],"variant_rule":{"alt":[{"stem":"0.49 × 0.65를 계산하면 얼마인가요?","options":[{"t":"0.3185","correct":true},{"t":"3.185","mis":"M5-2-u4-X12"},{"t":"31.85","mis":"M5-2-u4-X03"},{"t":"0.03185","mis":"M5-2-u4-X11"}],"explanation":["49 × 65 = 3185예요.","소수점 아래 자릿수가 2 + 2 = 4 — 3185에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.3185예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#2','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',2,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C8","difficulty":2,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"8.15 × 100","r":"815"},{"l":"8.15 × 1000","r":"8150"},{"l":"31 × 0.01","r":"0.31"}],"mis":"M5-2-u4-X10","explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","8.15 × 100 = 815 · 8.15 × 1000 = 8150이에요.","31 × 0.01 = 0.31이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"31 × 0.001","r":"0.031"},{"l":"16 × 0.01","r":"0.16"},{"l":"2.38 × 100","r":"238"}],"explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","31 × 0.001 = 0.031 · 16 × 0.01 = 0.16이에요.","2.38 × 100 = 238이에요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"4810 × 0.1","r":"481"},{"l":"4.81 × 10","r":"48.1"},{"l":"16 × 0.001","r":"0.016"}],"explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","4810 × 0.1 = 481 · 4.81 × 10 = 48.1이에요.","16 × 0.001 = 0.016이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#3','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 1.7 × 0.7 · 17 × 0.07 · 7 × 0.17 · 1.9 × 0.8',ARRAY['M5-2-u4-X20']::text[],true,'{"seq":3,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 1.7 × 0.7 · 17 × 0.07 · 7 × 0.17 · 1.9 × 0.8","options":[{"t":"1.9 × 0.8","correct":true},{"t":"1.7 × 0.7","mis":"M5-2-u4-X20"},{"t":"17 × 0.07","mis":"M5-2-u4-X20"},{"t":"7 × 0.17","mis":"M5-2-u4-X20"}],"explanation":["곱의 소수점 위치의 규칙 — 자연수의 곱을 구한 다음 두 수의 소수점 아래 자릿수의 합만큼 소수점을 왼쪽으로 옮겨요.","1.7 × 0.7 = 1.19, 17 × 0.07 = 1.19, 7 × 0.17 = 1.19, 1.9 × 0.8 = 1.52예요.","곱이 다른 칸은 1.9 × 0.8이에요 — 숫자가 비슷해도 소수점 위치가 달라요."],"variant_rule":{"alt":[{"stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 2.8 × 5.6 · 0.28 × 5.6 · 28 × 0.56 · 0.28 × 56","options":[{"t":"0.28 × 5.6","correct":true},{"t":"2.8 × 5.6","mis":"M5-2-u4-X20"},{"t":"28 × 0.56","mis":"M5-2-u4-X20"},{"t":"0.28 × 56","mis":"M5-2-u4-X20"}],"explanation":["곱의 소수점 위치의 규칙 — 자연수의 곱을 구한 다음 두 수의 소수점 아래 자릿수의 합만큼 소수점을 왼쪽으로 옮겨요.","2.8 × 5.6 = 15.68, 0.28 × 5.6 = 1.568, 28 × 0.56 = 15.68, 0.28 × 56 = 15.68이에요.","곱이 다른 칸은 0.28 × 5.6이에요 — 숫자가 비슷해도 소수점 위치가 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#4','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 작은 칸은 어느 것인가요? 0.14 × 0.01 · 3.65 × 0.01 · 0.5 × 0.22 · 36.5 × 0.01',ARRAY['M5-2-u4-X20']::text[],true,'{"seq":4,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 작은 칸은 어느 것인가요? 0.14 × 0.01 · 3.65 × 0.01 · 0.5 × 0.22 · 36.5 × 0.01","options":[{"t":"0.14 × 0.01","correct":true},{"t":"3.65 × 0.01","mis":"M5-2-u4-X20"},{"t":"0.5 × 0.22","mis":"M5-2-u4-X20"},{"t":"36.5 × 0.01","mis":"M5-2-u4-X20"}],"explanation":["곱하는 수가 0.01이면 소수점이 왼쪽으로 두 자리, 10배씩 커지면 오른쪽으로 옮겨져요.","0.14 × 0.01 = 0.0014, 3.65 × 0.01 = 0.0365, 0.5 × 0.22 = 0.11, 36.5 × 0.01 = 0.365예요.","소수점 위치를 기준으로 견주면 가장 작은 곱은 0.14 × 0.01 = 0.0014예요."],"variant_rule":{"alt":[{"stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 큰 칸은 어느 것인가요? 12 × 16.6 · 30 × 5.3 · 1.5 × 80 · 40 × 10.2","options":[{"t":"40 × 10.2","correct":true},{"t":"12 × 16.6","mis":"M5-2-u4-X07"},{"t":"30 × 5.3","mis":"M5-2-u4-X07"},{"t":"1.5 × 80","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 0.01이면 소수점이 왼쪽으로 두 자리, 10배씩 커지면 오른쪽으로 옮겨져요.","12 × 16.6 = 199.2, 30 × 5.3 = 159, 1.5 × 80 = 120, 40 × 10.2 = 408이에요.","소수점 위치를 기준으로 견주면 가장 큰 곱은 40 × 10.2 = 408이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#5','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'ox','auto','0.09 × 0.07 = 0.0063이에요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":3,"kind":"ox","stem":"0.09 × 0.07 = 0.0063이에요.","answer":"O","reason_options":[{"t":"9 × 7 = 63에서 소수점을 왼쪽으로 네 자리 옮기고 빈 자리를 0으로 채우므로","correct":true},{"t":"소수 두 자리 수끼리 곱하면 소수 두 자리 수이므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["9 × 7 = 63이에요.","2 + 2 = 4 — 왼쪽으로 네 자리, 빈 자리는 0이에요.","0.09 × 0.07 = 0.0063 — 맞아요."],"variant_rule":{"alt":[{"stem":"37 × 21 = 777이므로 3.7 × 2.1 = 7.77이에요.","answer":"O","reason_options":[{"t":"소수 한 자리 수끼리의 곱은 소수 두 자리 수이므로","correct":true},{"t":"두 수 가운데 한 수의 자릿수만 세면 되므로","mis":"M5-2-u4-X03"}],"explanation":["1 + 1 = 2 — 소수 두 자리 수예요.","777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77 — 맞아요."]},{"stem":"16 × 0.001 = 0.16이에요.","answer":"X","reason_options":[{"t":"0.001을 곱하면 소수점이 왼쪽으로 세 자리 옮겨져 0.016이므로","correct":true},{"t":"0.001을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["0.001은 소수 세 자리 수예요.","16 → 1.6 → 0.16 → 0.016이에요.","16 × 0.001 = 0.016이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#6','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'sa','auto','4810 × 0.001 = 4.81이에요. 4810의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C8","difficulty":3,"kind":"sa","stem":"4810 × 0.001 = 4.81이에요. 4810의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.001은 소수 세 자리 수예요.","4810 × 0.001은 소수점을 왼쪽으로 3자리 옮겨요.","4810 → 4.81 — 3자리예요."],"mis":"M5-2-u4-X11","variant_rule":{"alt":[{"stem":"16 × 0.01 = 0.16이에요. 16의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.01은 소수 두 자리 수예요.","16 × 0.01은 소수점을 왼쪽으로 2자리 옮겨요.","16 → 0.16 — 2자리예요."]},{"stem":"31 × 0.001 = 0.031이에요. 31의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.001은 소수 세 자리 수예요.","31 × 0.001은 소수점을 왼쪽으로 3자리 옮겨요.","31 → 0.031 — 3자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#7','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','32 × 74 = 2368이에요. 0.032 × 74를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"32 × 74 = 2368이에요. 0.032 × 74를 계산하면 얼마인가요?","options":[{"t":"2.368","correct":true},{"t":"2368","mis":"M5-2-u4-X01"},{"t":"23.68","mis":"M5-2-u4-X02"},{"t":"0.2368","mis":"M5-2-u4-X02"}],"explanation":["0.032와 74의 소수점 아래 자릿수는 3개와 0개예요.","3 + 0 = 3 — 2368에서 소수점을 왼쪽으로 세 자리 옮겨요.","0.032 × 74 = 2.368이에요."],"variant_rule":{"alt":[{"stem":"32 × 74 = 2368이에요. 32 × 7.4를 계산하면 얼마인가요?","options":[{"t":"236.8","correct":true},{"t":"2368","mis":"M5-2-u4-X01"},{"t":"23.68","mis":"M5-2-u4-X02"},{"t":"23680","mis":"M5-2-u4-X02"}],"explanation":["32와 7.4의 소수점 아래 자릿수는 0개와 1개예요.","0 + 1 = 1 — 2368에서 소수점을 왼쪽으로 한 자리 옮겨요.","32 × 7.4 = 236.8이에요."]},{"stem":"49 × 65 = 3185예요. 0.49 × 0.65를 계산하면 얼마인가요?","options":[{"t":"0.3185","correct":true},{"t":"31.85","mis":"M5-2-u4-X03"},{"t":"3185","mis":"M5-2-u4-X01"},{"t":"3.185","mis":"M5-2-u4-X02"}],"explanation":["0.49와 0.65의 소수점 아래 자릿수는 2개와 2개예요.","2 + 2 = 4 — 3185에서 소수점을 왼쪽으로 네 자리 옮겨요.","0.49 × 0.65 = 0.3185예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#8','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'essay','teacher','양치 컵으로 한 번 양치하면 물 4.81 L를 아껴요. 10번, 100번, 1000번 양치할 때 아끼는 물의 양을 구하고 곱의 소수점이 옮겨지는 규칙을 쓰세요. 그리고 0.09 × 0.07을 그 규칙으로 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"양치 컵으로 한 번 양치하면 물 4.81 L를 아껴요. 10번, 100번, 1000번 양치할 때 아끼는 물의 양을 구하고 곱의 소수점이 옮겨지는 규칙을 쓰세요. 그리고 0.09 × 0.07을 그 규칙으로 계산해 보세요.","answer_guide":{"answer":"예: 4.81 × 10 = 48.1, 4.81 × 100 = 481, 4.81 × 1000 = 4810이다. 곱하는 수가 10배 될 때마다 곱의 소수점이 오른쪽으로 한 자리씩 옮겨진다. 0.09 × 0.07은 9 × 7 = 63에서 두 수의 소수점 아래 자릿수 2 + 2 = 4만큼 소수점을 왼쪽으로 옮기고 빈 자리를 0으로 채워 0.0063이다.","scoring_points":["48.1 L, 481 L, 4810 L를 구했는가","10배마다 소수점이 오른쪽으로 한 자리씩 옮겨진다고 썼는가","0.09 × 0.07 = 0.0063을 자릿수 규칙으로 구했는가"]},"explanation":["4.81 × 10 = 48.1, 4.81 × 100 = 481, 4.81 × 1000 = 4810이에요.","10배마다 오른쪽으로 한 자리씩 옮겨져요.","9 × 7 = 63 → 0.0063이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#9','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'essay','teacher','다을이는 「25 × 11 = 275니까 0.25 × 1.1 = 2.75예요.」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048이에요.」라고 말했어요. 잘못 말한 친구를 찾고 이유를 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"다을이는 「25 × 11 = 275니까 0.25 × 1.1 = 2.75예요.」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048이에요.」라고 말했어요. 잘못 말한 친구를 찾고 이유를 써 보세요.","answer_guide":{"answer":"예: 잘못 말한 친구는 다을이다. 0.25 × 1.1은 소수 두 자리 수와 소수 한 자리 수의 곱이므로 소수점 아래 자릿수가 2 + 1 = 3인 소수 세 자리 수 0.275이다. 봄이는 48에서 소수점을 왼쪽으로 2 + 1 = 3자리 옮기고 빈 자리를 0으로 채워 0.048로 바르게 말했다.","scoring_points":["잘못 말한 친구를 다을이로 찾았는가","자릿수 2 + 1 = 3으로 곱이 소수 세 자리 수임을 밝혔는가","바른 곱 0.275를 구했는가"]},"explanation":["0.25는 두 자리, 1.1은 한 자리예요.","2 + 1 = 3 — 소수 세 자리 수예요.","바른 곱은 0.275 — 다을이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L08_challenge#10','math',5,2,'u4','L08','tb_g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'essay','teacher','사각사각 사목 놀이판에는 1.7 × 0.7, 17 × 0.07, 7 × 0.17처럼 곱이 같은 칸이 있어요. (소수)×(소수)를 계산하는 방법을 이야기하고, 세 칸의 곱이 같은 까닭을 곱의 소수점 위치로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"사각사각 사목 놀이판에는 1.7 × 0.7, 17 × 0.07, 7 × 0.17처럼 곱이 같은 칸이 있어요. (소수)×(소수)를 계산하는 방법을 이야기하고, 세 칸의 곱이 같은 까닭을 곱의 소수점 위치로 설명해 보세요.","answer_guide":{"answer":"예: (소수)×(소수)는 분수의 곱셈으로 계산하거나, 자연수의 곱셈 17 × 7 = 119를 한 다음 두 수의 소수점 아래 자릿수를 더한 만큼 소수점을 왼쪽으로 옮겨 계산한다. 1.7 × 0.7은 1 + 1 = 2, 17 × 0.07은 0 + 2 = 2, 7 × 0.17은 0 + 2 = 2이므로 세 칸 모두 119에서 소수점을 왼쪽으로 두 자리 옮긴 1.19이다.","scoring_points":["분수의 곱셈이나 자연수의 곱셈을 이용한 계산 방법을 말했는가","세 식의 소수점 아래 자릿수 합이 모두 2임을 밝혔는가","세 칸의 곱이 모두 1.19라고 했는가"]},"explanation":["17 × 7 = 119예요.","세 식 모두 소수점 아래 자릿수의 합이 2예요.","그래서 곱은 모두 1.19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L09_basic#1','math',5,2,'u4','L09','tb_g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'sa','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C9","difficulty":1,"kind":"sa","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["표에서 사용하지 않는 가전제품의 플러그 뽑기 줄을 찾아요.","한 사람의 효과는 1.9그루, 학생 수는 15명이에요.","그래서 15명이에요."],"mis":"M5-2-u4-X18","asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]},"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 재활용이 가능한 유리병, 캔 등 분리배출하기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["표에서 재활용이 가능한 유리병, 캔 등 분리배출하기 줄을 찾아요.","한 사람의 효과는 0.4그루, 학생 수는 22명이에요.","그래서 22명이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 비닐봉지 대신 장바구니 사용하기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["표에서 비닐봉지 대신 장바구니 사용하기 줄을 찾아요.","한 사람의 효과는 1.2그루, 학생 수는 16명이에요.","그래서 16명이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L09_basic#2','math',5,2,'u4','L09','tb_g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'mc','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u4-X14','M5-2-u4-X01','M5-2-u4-X05']::text[],true,'{"seq":2,"concept":"M5-2-u4-C9","difficulty":1,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 15","correct":true},{"t":"3 × 15","mis":"M5-2-u4-X14"},{"t":"19 × 15","mis":"M5-2-u4-X01"},{"t":"2 + 15","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.9를 2로 어림해요.","식은 2 × 15 = 30이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]},"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 재활용이 가능한 유리병, 캔 등 분리배출하기의 반 전체 효과를 0.4 → 0.5로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"0.5 × 22","correct":true},{"t":"1.5 × 22","mis":"M5-2-u4-X14"},{"t":"4 × 22","mis":"M5-2-u4-X01"},{"t":"0.5 + 22","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","0.4를 0.5로 어림해요.","식은 0.5 × 22 = 11이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 비닐봉지 대신 장바구니 사용하기의 반 전체 효과를 1.2 → 1로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"1 × 16","correct":true},{"t":"2 × 16","mis":"M5-2-u4-X14"},{"t":"12 × 16","mis":"M5-2-u4-X01"},{"t":"1 + 16","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.2를 1로 어림해요.","식은 1 × 16 = 16이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 텔레비전 사용 시간 1시간 줄이기의 반 전체 효과를 13.3 → 13으로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"13 × 2","correct":true},{"t":"14 × 2","mis":"M5-2-u4-X14"},{"t":"133 × 2","mis":"M5-2-u4-X01"},{"t":"13 + 2","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","13.3을 13으로 어림해요.","식은 13 × 2 = 26이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L09_basic#3','math',5,2,'u4','L09','tb_g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'ox','auto','반 전체 효과는 한 사람의 효과에 실천한 학생 수를 곱해 구해요.',ARRAY['M5-2-u4-X05']::text[],true,'{"seq":3,"concept":"M5-2-u4-C9","difficulty":1,"kind":"ox","stem":"반 전체 효과는 한 사람의 효과에 실천한 학생 수를 곱해 구해요.","answer":"O","reason_options":[{"t":"같은 효과가 학생 수만큼 있으므로","correct":true},{"t":"한 사람의 효과와 학생 수를 더하므로","mis":"M5-2-u4-X05"}],"mis":"M5-2-u4-X05","explanation":["한 사람이 1.9그루라면 15명이면 1.9가 15번이에요.","같은 수를 여러 번 더하면 곱셈이에요.","1.9 × 15 = 28.5예요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]},"variant_rule":{"alt":[{"stem":"어림셈으로 1.9 × 15를 2 × 15 = 30으로 볼 수 있어요.","answer":"O","reason_options":[{"t":"1.9는 2에 가까운 수이므로","correct":true},{"t":"1.9를 19로 바꾸어야 하므로","mis":"M5-2-u4-X01"}],"explanation":["1.9를 2로 어림해요.","2 × 15 = 30이에요.","실제로는 1.9 × 15 = 28.5 — 비슷해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"0.4 × 22는 22보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 0.4가 1보다 작으므로","correct":true},{"t":"22가 가장 큰 수이므로","mis":"M5-2-u4-X06"}],"explanation":["0.4는 1보다 작아요.","그래서 곱은 22보다 작아요.","0.4 × 22 = 8.8이에요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_L09_basic#4','math',5,2,'u4','L09','tb_g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'sa','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u4-C9","difficulty":1,"kind":"sa","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 사용하지 않는 가전제품의 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2 × 15 = 30이에요.","실제로는 1.9 × 15 = 28.5 — 어림한 값과 비슷해요."],"mis":"M5-2-u4-X14","asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]},"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 재활용이 가능한 유리병, 캔 등 분리배출하기의 반 전체 효과를 0.4 → 0.5로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","0.5 × 22 = 11이에요.","실제로는 0.4 × 22 = 8.8 — 어림한 값과 비슷해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 비닐봉지 대신 장바구니 사용하기의 반 전체 효과를 1.2 → 1로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1 × 16 = 16이에요.","실제로는 1.2 × 16 = 19.2 — 어림한 값과 비슷해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}},{"stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 텔레비전 사용 시간 1시간 줄이기의 반 전체 효과를 13.3 → 13으로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","13 × 2 = 26이에요.","실제로는 13.3 × 2 = 26.6 — 어림한 값과 비슷해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
