INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#13','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C3',2,'mc','auto','0.61 × 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],false,'{"seq":13,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.61 × 7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨61/100⟩ × 7","correct":true},{"t":"⟨61/1000⟩ × 7","mis":"M5-2-u4-X08"},{"t":"⟨1/61⟩ × 7","mis":"M5-2-u4-X08"},{"t":"⟨61/100⟩ × ⟨7/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.61 = ⟨61/100⟩이에요.","⟨61/100⟩ × 7 = ⟨427/100⟩ = 4.27이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#14','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',2,'mc','auto','계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 7.39 × 7 ○ 6 × 8.15',ARRAY['M5-2-u4-X20','M5-2-u4-X18']::text[],false,'{"seq":14,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 7.39 × 7 ○ 6 × 8.15","options":[{"t":">","correct":true},{"t":"<","mis":"M5-2-u4-X20"},{"t":"=","mis":"M5-2-u4-X18"}],"explanation":["두 식을 각각 계산해요.","7.39 × 7 = 51.73, 6 × 8.15 = 48.9예요.","51.73 > 48.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#15','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',2,'mc','auto','365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. 3.65 × □ = 9.125',ARRAY['M5-2-u4-X01','M5-2-u4-X03','M5-2-u4-X11']::text[],false,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. 3.65 × □ = 9.125","options":[{"t":"2.5","correct":true},{"t":"25","mis":"M5-2-u4-X01"},{"t":"0.25","mis":"M5-2-u4-X03"},{"t":"250","mis":"M5-2-u4-X11"}],"explanation":["곱해지는 수 3.65는 소수 두 자리 수이고, 곱 9.125는 소수 세 자리 수예요.","그래서 □는 소수 한 자리 수 — 25의 ⟨1/10⟩배인 2.5예요.","3.65 × 2.5 = 9.125예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#16','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',2,'mc','auto','176 × 0.01을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],false,'{"seq":16,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"176 × 0.01을 계산하면 얼마인가요?","options":[{"t":"1.76","correct":true},{"t":"17600","mis":"M5-2-u4-X10"},{"t":"0.176","mis":"M5-2-u4-X11"},{"t":"17.6","mis":"M5-2-u4-X11"}],"explanation":["0.01을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.01은 소수 두 자리 수 — 왼쪽으로 두 자리예요.","176 × 0.01 = 1.76이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#17','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',3,'mc','auto','예건은 「138 × 46 = 6348이니까 13.8 × 4.6 = 634.8」, 주연은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],false,'{"seq":17,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"예건은 「138 × 46 = 6348이니까 13.8 × 4.6 = 634.8」, 주연은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"예건 — 바른 곱은 63.48","correct":true},{"t":"주연 — 바른 곱은 1.568","mis":"M5-2-u4-X18"},{"t":"예건 — 바른 곱은 6348","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["13.8 × 4.6의 소수점 아래 자릿수는 1 + 1 = 2예요.","0.49 × 0.32의 소수점 아래 자릿수는 2 + 2 = 4예요.","예건의 말이 틀렸어요 — 바른 곱은 63.48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#18','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',3,'mc','auto','1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X18']::text[],false,'{"seq":18,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"390 km","correct":true},{"t":"338 km","mis":"M5-2-u4-X16"},{"t":"260 km","mis":"M5-2-u4-X18"},{"t":"290 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","1시간 30분 = 1.5시간이에요.","260 × 1.5 = 390 — 390 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#19','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C3',3,'sa','auto','0.83 × 15 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u4-C3","difficulty":3,"kind":"sa","stem":"0.83 × 15 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["0.83 × 15 = 12.45예요.","12.45 < □이므로 □는 12.45보다 큰 자연수예요 — 12는 12.45보다 작아서 안 돼요.","가장 작은 자연수는 13이에요."],"mis":"M5-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#20','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],false,'{"seq":20,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"사용하지 않는 가전제품의 플러그 뽑기","correct":true},{"t":"텔레비전 사용 시간 1시간 줄이기","mis":"M5-2-u4-X15"},{"t":"재활용이 가능한 유리병, 캔 등 분리배출하기","mis":"M5-2-u4-X15"},{"t":"비닐봉지 대신 장바구니 사용하기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 높게 나타난 방법은 사용하지 않는 가전제품의 플러그 뽑기예요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#21','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 1.7 × 0.7 · 17 × 0.07 · 7 × 0.17 · 1.9 × 0.8',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":21,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 1.7 × 0.7 · 17 × 0.07 · 7 × 0.17 · 1.9 × 0.8","options":[{"t":"1.9 × 0.8","correct":true},{"t":"1.7 × 0.7","mis":"M5-2-u4-X20"},{"t":"17 × 0.07","mis":"M5-2-u4-X20"},{"t":"7 × 0.17","mis":"M5-2-u4-X20"}],"explanation":["곱의 소수점 위치의 규칙 — 자연수의 곱을 구한 다음 두 수의 소수점 아래 자릿수의 합만큼 소수점을 왼쪽으로 옮겨요.","1.7 × 0.7 = 1.19, 17 × 0.07 = 1.19, 7 × 0.17 = 1.19, 1.9 × 0.8 = 1.52예요.","곱이 다른 칸은 1.9 × 0.8이에요 — 숫자가 비슷해도 소수점 위치가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#22','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',3,'mc','auto','떨어진 높이의 0.6배만큼 튀어 오르는 공이 있어요. 높이가 2 m인 곳에서 이 공을 떨어뜨렸을 때 두 번째로 튀어 오른 공의 높이는 몇 m인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X02','M5-2-u4-X17']::text[],false,'{"seq":22,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"떨어진 높이의 0.6배만큼 튀어 오르는 공이 있어요. 높이가 2 m인 곳에서 이 공을 떨어뜨렸을 때 두 번째로 튀어 오른 공의 높이는 몇 m인가요?","options":[{"t":"0.72 m","correct":true},{"t":"1.2 m","mis":"M5-2-u4-X18"},{"t":"7.2 m","mis":"M5-2-u4-X02"},{"t":"0.8 m","mis":"M5-2-u4-X17"}],"explanation":["첫 번째로 튀어 오른 높이는 2 × 0.6 = 1.2(m)예요.","두 번째는 첫 번째의 0.6배 — 1.2 × 0.6 = 0.72(m)예요.","그래서 0.72 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#23','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C6',4,'essay','teacher','0.9 × 0.7을 분수의 곱셈으로 계산하는 방법과 자연수의 곱셈을 이용하는 방법, 두 가지로 계산하고 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"0.9 × 0.7을 분수의 곱셈으로 계산하는 방법과 자연수의 곱셈을 이용하는 방법, 두 가지로 계산하고 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 분수로 — 0.9 = ⟨9/10⟩, 0.7 = ⟨7/10⟩이므로 ⟨9/10⟩ × ⟨7/10⟩ = ⟨63/100⟩ = 0.63이다. 자연수로 — 9 × 7 = 63이고 0.9는 9의 ⟨1/10⟩배, 0.7은 7의 ⟨1/10⟩배이므로 0.9 × 0.7은 63의 ⟨1/100⟩배인 0.63이다.","scoring_points":["분수의 곱셈으로 0.63을 구했는가","9 × 7 = 63의 ⟨1/100⟩배로 0.63을 구했는가","두 방법을 말로 설명했는가"]},"explanation":["⟨9/10⟩ × ⟨7/10⟩ = ⟨63/100⟩ = 0.63이에요.","9 × 7 = 63의 ⟨1/100⟩배예요.","0.9 × 0.7 = 0.63이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#24','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',4,'essay','teacher','주연이는 「49 × 32 = 1568이므로 0.49 × 0.32 = 0.1568」, 예건이는 「138 × 46 = 6348이므로 13.8 × 4.6 = 634.8」이라고 말했어요. 누가 잘못 말했는지 찾고 곱의 소수점 위치를 정하는 규칙으로 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"주연이는 「49 × 32 = 1568이므로 0.49 × 0.32 = 0.1568」, 예건이는 「138 × 46 = 6348이므로 13.8 × 4.6 = 634.8」이라고 말했어요. 누가 잘못 말했는지 찾고 곱의 소수점 위치를 정하는 규칙으로 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 0.49 × 0.32는 소수 두 자리 수끼리의 곱이라 소수점 아래 자릿수가 2 + 2 = 4이므로 0.1568이 맞다. 13.8 × 4.6은 소수 한 자리 수끼리의 곱이라 1 + 1 = 2이므로 6348에서 소수점을 왼쪽으로 두 자리 옮긴 63.48이 되어야 한다. 예건이가 잘못 말했고 바른 곱은 63.48이다.","scoring_points":["주연이의 말이 맞음을 자릿수 2 + 2 = 4로 확인했는가","예건이가 잘못 말했다고 찾았는가","바른 곱 63.48을 구했는가"]},"explanation":["2 + 2 = 4 — 0.1568이 맞아요.","1 + 1 = 2 — 6348 → 63.48이에요.","예건이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_a#25','math',5,2,'u4','','tb_g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',4,'essay','teacher','1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리를 구하려고 해요. 1시간 30분을 소수로 나타내는 방법을 쓰고 거리를 구해 보세요. 1시간 30분을 1.3시간으로 쓰면 안 되는 까닭도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리를 구하려고 해요. 1시간 30분을 소수로 나타내는 방법을 쓰고 거리를 구해 보세요. 1시간 30분을 1.3시간으로 쓰면 안 되는 까닭도 쓰세요.","answer_guide":{"answer":"예: 30분은 1시간의 ⟨30/60⟩ = ⟨1/2⟩이므로 0.5시간이고 1시간 30분은 1.5시간이다. 260 × 1.5 = 390이므로 390 km를 간다. 1시간은 60분이라 30분은 0.3시간이 아니라 0.5시간이므로 1.3시간으로 쓰면 안 된다.","scoring_points":["1시간 30분 = 1.5시간으로 바꾸었는가","260 × 1.5 = 390(km)를 구했는가","30분이 0.3시간이 아닌 까닭을 썼는가"]},"explanation":["30분은 ⟨1/2⟩시간 = 0.5시간이에요.","260 × 1.5 = 390(km)예요.","1시간은 60분이라 30분은 0.3시간이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#1','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',1,'mc','auto','1.7 × 5.31을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],false,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"1.7 × 5.31을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨17/10⟩ × ⟨531/100⟩","correct":true},{"t":"⟨17/100⟩ × ⟨531/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/17⟩ × ⟨531/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨17/10⟩ × ⟨531/1000⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.7 = ⟨17/10⟩ · 5.31 = ⟨531/100⟩이에요.","⟨17/10⟩ × ⟨531/100⟩ = ⟨9027/1000⟩ = 9.027이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#2','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',1,'mc','auto','1.7 × 5.31을 자연수의 곱셈 17 × 531 = 9027을 이용해 계산하려고 해요. 1.7 × 5.31의 곱은 9027의 몇 배인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X10']::text[],false,'{"seq":2,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"1.7 × 5.31을 자연수의 곱셈 17 × 531 = 9027을 이용해 계산하려고 해요. 1.7 × 5.31의 곱은 9027의 몇 배인가요?","options":[{"t":"⟨1/1000⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/100⟩배","mis":"M5-2-u4-X03"},{"t":"1000배","mis":"M5-2-u4-X10"}],"explanation":["1.7은 17의 ⟨1/10⟩배, 5.31은 531의 ⟨1/100⟩배예요.","그래서 곱은 9027의 ⟨1/1000⟩배예요.","1.7 × 5.31 = 9.027이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#3','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',1,'mc','auto','31 × 2.4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":3,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"31 × 2.4를 계산하면 얼마인가요?","options":[{"t":"74.4","correct":true},{"t":"744","mis":"M5-2-u4-X01"},{"t":"7.44","mis":"M5-2-u4-X02"},{"t":"7440","mis":"M5-2-u4-X02"}],"explanation":["31 × 24 = 744예요.","2.4는 24의 ⟨1/10⟩배이므로 곱도 744의 ⟨1/10⟩배예요.","31 × 2.4 = 74.4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#4','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',1,'sa','auto','0.64 × 9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"0.64 × 9를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["7"],"explanation":["소수점을 생각하지 않고 64 × 9 = 576을 계산해요.","0.64의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","0.64 × 9 = 5.76 — ?는 7이에요."],"mis":"M5-2-u4-X13","asset":{"type":"expr_grid","rows":[["","0.","6","4"],["×","","","9"],["","5.","?","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#5','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',1,'mc','auto','0.272 × 100과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X20','M5-2-u4-X11']::text[],false,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"0.272 × 100과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"2.72 × 10","correct":true},{"t":"2720 × 0.001","mis":"M5-2-u4-X20"},{"t":"2.72 × 1000","mis":"M5-2-u4-X11"},{"t":"272 × 0.01","mis":"M5-2-u4-X20"}],"explanation":["0.272 × 100은 0.272에서 소수점이 오른쪽으로 두 자리 — 27.2예요.","2.72 × 10 = 27.2, 2720 × 0.001 = 2.72, 2.72 × 1000 = 2720, 272 × 0.01 = 2.72예요.","그래서 같은 것은 2.72 × 10이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#6','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C4',1,'mc','auto','어림하여 계산 결과가 6보다 큰 식을 모두 고른 것은 어느 것인가요? 6 × 0.9 · 3의 2.1배 · 2 × 2.7',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],false,'{"seq":6,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"어림하여 계산 결과가 6보다 큰 식을 모두 고른 것은 어느 것인가요? 6 × 0.9 · 3의 2.1배 · 2 × 2.7","options":[{"t":"3의 2.1배","correct":true},{"t":"6 × 0.9, 2 × 2.7","mis":"M5-2-u4-X06"},{"t":"6 × 0.9, 3의 2.1배, 2 × 2.7","mis":"M5-2-u4-X07"},{"t":"3의 2.1배, 6 × 0.9","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","0.9를 1로 어림하면 6 × 1 = 6 — 6 × 0.9는 6보다 작아요 · 2.1을 2로 어림하면 3 × 2 = 6 — 3의 2.1배는 6보다 커요 · 2.7을 3으로 어림하면 2 × 3 = 6 — 2 × 2.7은 6보다 작아요.","그래서 6보다 큰 식은 3의 2.1배 — 실제로 6 × 0.9 = 5.4, 3 × 2.1 = 6.3, 2 × 2.7 = 5.4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#7','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',1,'mc','auto','계산 결과가 가장 작은 것을 찾아 기호를 고르세요. ㉠ 7.14 × 5.5 · ㉡ 4.2 × 9.2',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"계산 결과가 가장 작은 것을 찾아 기호를 고르세요. ㉠ 7.14 × 5.5 · ㉡ 4.2 × 9.2","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"M5-2-u4-X20"},{"t":"두 식이 모두 같다","mis":"M5-2-u4-X20"}],"explanation":["식을 각각 계산하고 소수점 위치를 기준으로 견주어요.","7.14 × 5.5 = 39.27, 4.2 × 9.2 = 38.64예요.","가장 작은 것은 ㉡예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#8','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',1,'mc','auto','리코더의 길이는 25 cm이고, 플루트의 길이는 리코더의 길이의 2.64배예요. 플루트의 길이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"리코더의 길이는 25 cm이고, 플루트의 길이는 리코더의 길이의 2.64배예요. 플루트의 길이는 몇 cm인가요?","options":[{"t":"66 cm","correct":true},{"t":"27.64 cm","mis":"M5-2-u4-X17"},{"t":"6600 cm","mis":"M5-2-u4-X01"},{"t":"660 cm","mis":"M5-2-u4-X02"}],"explanation":["「25 cm의 2.64배」는 25 × 2.64예요.","25 × 264 = 6600이에요. 곱은 그 ⟨1/100⟩배예요.","25 × 2.64 = 66 — 66 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#9','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C3',2,'mc','auto','도영이는 매일 4.25 km씩 걷기 운동을 했어요. 도영이가 5일 동안 걸은 거리는 모두 몇 km인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":9,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"도영이는 매일 4.25 km씩 걷기 운동을 했어요. 도영이가 5일 동안 걸은 거리는 모두 몇 km인가요?","options":[{"t":"21.25 km","correct":true},{"t":"9.25 km","mis":"M5-2-u4-X17"},{"t":"2125 km","mis":"M5-2-u4-X01"},{"t":"212.5 km","mis":"M5-2-u4-X02"}],"explanation":["같은 거리 4.25 km를 5일 걸었으니 식은 4.25 × 5예요.","425 × 5 = 2125예요. 곱은 그 ⟨1/100⟩배예요.","4.25 × 5 = 21.25 — 21.25 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#10','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',2,'mc','auto','성진이네 가족이 지난달에 사용한 물은 494 L예요. 이번 달에 사용한 물이 지난달의 0.85배라면 이번 달에 사용한 물은 몇 L인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":10,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"성진이네 가족이 지난달에 사용한 물은 494 L예요. 이번 달에 사용한 물이 지난달의 0.85배라면 이번 달에 사용한 물은 몇 L인가요?","options":[{"t":"419.9 L","correct":true},{"t":"494.85 L","mis":"M5-2-u4-X17"},{"t":"41990 L","mis":"M5-2-u4-X01"},{"t":"4199 L","mis":"M5-2-u4-X02"}],"explanation":["「494 L의 0.85배」는 494 × 0.85예요.","494 × 85 = 41990이에요. 곱은 그 ⟨1/100⟩배예요.","494 × 0.85 = 419.9 — 419.9 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#11','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',2,'mc','auto','32 × 24 = 768이에요. 3.2 × 24를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":11,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"32 × 24 = 768이에요. 3.2 × 24를 계산하면 얼마인가요?","options":[{"t":"76.8","correct":true},{"t":"768","mis":"M5-2-u4-X01"},{"t":"7.68","mis":"M5-2-u4-X02"},{"t":"7680","mis":"M5-2-u4-X02"}],"explanation":["3.2와 24의 소수점 아래 자릿수는 1개와 0개예요.","1 + 0 = 1 — 768에서 소수점을 왼쪽으로 한 자리 옮겨요.","3.2 × 24 = 76.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#12','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C6',2,'sa','auto','전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u4-C6","difficulty":2,"kind":"sa","stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["가로 6칸, 세로 9칸을 칠해요.","칠한 칸은 6 × 9 = 54칸이에요.","한 칸이 0.01이므로 0.6 × 0.9 = 0.54예요."],"mis":"M5-2-u4-X09","asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]],"hi":true},{"p":[[1,0],[2,0],[2,1],[1,1]],"hi":true},{"p":[[2,0],[3,0],[3,1],[2,1]],"hi":true},{"p":[[3,0],[4,0],[4,1],[3,1]],"hi":true},{"p":[[4,0],[5,0],[5,1],[4,1]],"hi":true},{"p":[[5,0],[6,0],[6,1],[5,1]],"hi":true},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[8,0],[9,0],[9,1],[8,1]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]],"hi":true},{"p":[[1,1],[2,1],[2,2],[1,2]],"hi":true},{"p":[[2,1],[3,1],[3,2],[2,2]],"hi":true},{"p":[[3,1],[4,1],[4,2],[3,2]],"hi":true},{"p":[[4,1],[5,1],[5,2],[4,2]],"hi":true},{"p":[[5,1],[6,1],[6,2],[5,2]],"hi":true},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]],"hi":true},{"p":[[1,2],[2,2],[2,3],[1,3]],"hi":true},{"p":[[2,2],[3,2],[3,3],[2,3]],"hi":true},{"p":[[3,2],[4,2],[4,3],[3,3]],"hi":true},{"p":[[4,2],[5,2],[5,3],[4,3]],"hi":true},{"p":[[5,2],[6,2],[6,3],[5,3]],"hi":true},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[0,3],[1,3],[1,4],[0,4]],"hi":true},{"p":[[1,3],[2,3],[2,4],[1,4]],"hi":true},{"p":[[2,3],[3,3],[3,4],[