"hi":true},{"p":[[5,8],[6,8],[6,9],[5,9]],"hi":true},{"p":[[6,8],[7,8],[7,9],[6,9]]},{"p":[[7,8],[8,8],[8,9],[7,9]]},{"p":[[8,8],[9,8],[9,9],[8,9]]},{"p":[[9,8],[10,8],[10,9],[9,9]]},{"p":[[0,9],[1,9],[1,10],[0,10]]},{"p":[[1,9],[2,9],[2,10],[1,10]]},{"p":[[2,9],[3,9],[3,10],[2,10]]},{"p":[[3,9],[4,9],[4,10],[3,10]]},{"p":[[4,9],[5,9],[5,10],[4,10]]},{"p":[[5,9],[6,9],[6,10],[5,10]]},{"p":[[6,9],[7,9],[7,10],[6,10]]},{"p":[[7,9],[8,9],[8,10],[7,10]]},{"p":[[8,9],[9,9],[9,10],[8,10]]},{"p":[[9,9],[10,9],[10,10],[9,10]]}],"u":16}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#13','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C4',2,'mc','auto','4 × 0.9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03','M5-2-u4-X17']::text[],false,'{"seq":13,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"4 × 0.9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"4 × ⟨9/10⟩","correct":true},{"t":"4 × ⟨9/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨4/10⟩ × ⟨9/10⟩","mis":"M5-2-u4-X03"},{"t":"4 + ⟨9/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.9 = ⟨9/10⟩예요.","4 × ⟨9/10⟩ = ⟨36/10⟩ = 3.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#14','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C6',2,'mc','auto','계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 8.6 × 3.4 ○ 6.4 × 5.5',ARRAY['M5-2-u4-X20','M5-2-u4-X18']::text[],false,'{"seq":14,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 8.6 × 3.4 ○ 6.4 × 5.5","options":[{"t":"<","correct":true},{"t":">","mis":"M5-2-u4-X20"},{"t":"=","mis":"M5-2-u4-X18"}],"explanation":["두 식을 각각 계산해요.","8.6 × 3.4 = 29.24, 6.4 × 5.5 = 35.2예요.","29.24 < 35.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#15','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',2,'mc','auto','365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. □ × 0.25 = 912.5',ARRAY['M5-2-u4-X11','M5-2-u4-X10']::text[],false,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"365 × 25 = 9125를 이용하여 □ 안에 알맞은 수를 구하세요. □ × 0.25 = 912.5","options":[{"t":"3650","correct":true},{"t":"365","mis":"M5-2-u4-X11"},{"t":"36.5","mis":"M5-2-u4-X10"},{"t":"36500","mis":"M5-2-u4-X11"}],"explanation":["곱하는 수 0.25는 소수 두 자리 수이고, 곱 912.5는 소수 한 자리 수예요.","그래서 □는 365의 10배인 3650이어야 해요.","3650 × 0.25 = 912.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#16','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',2,'mc','auto','0.018 × 100을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],false,'{"seq":16,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"0.018 × 100을 계산하면 얼마인가요?","options":[{"t":"1.8","correct":true},{"t":"0.00018","mis":"M5-2-u4-X10"},{"t":"18","mis":"M5-2-u4-X11"},{"t":"0.18","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","0.018 × 100 = 1.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#17','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',3,'mc','auto','다을은 「25 × 11 = 275니까 0.25 × 1.1 = 2.75」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],false,'{"seq":17,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"다을은 「25 × 11 = 275니까 0.25 × 1.1 = 2.75」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"다을 — 바른 곱은 0.275","correct":true},{"t":"봄이 — 바른 곱은 0.48","mis":"M5-2-u4-X18"},{"t":"다을 — 바른 곱은 27.5","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.25 × 1.1의 소수점 아래 자릿수는 2 + 1 = 3이에요.","0.06 × 0.8의 소수점 아래 자릿수는 2 + 1 = 3이에요.","다을의 말이 틀렸어요 — 바른 곱은 0.275예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#18','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',3,'mc','auto','1시간에 150 km를 가는 고속 열차가 같은 빠르기로 2시간 30분 동안 가는 거리는 몇 km인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X18']::text[],false,'{"seq":18,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"1시간에 150 km를 가는 고속 열차가 같은 빠르기로 2시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"375 km","correct":true},{"t":"345 km","mis":"M5-2-u4-X16"},{"t":"300 km","mis":"M5-2-u4-X18"},{"t":"330 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","2시간 30분 = 2.5시간이에요.","150 × 2.5 = 375 — 375 km예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#19','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',3,'sa','auto','□ < 3.9 × 7.21에서 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u4-C7","difficulty":3,"kind":"sa","stem":"□ < 3.9 × 7.21에서 □ 안에 들어갈 수 있는 가장 큰 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["39 × 721 = 28119이고 곱은 그 ⟨1/1000⟩배 — 3.9 × 7.21 = 28.119예요.","□ < 28.119이므로 29는 안 되고 28은 돼요.","가장 큰 자연수는 28이에요."],"mis":"M5-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#20','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 텔레비전 사용 시간 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X14']::text[],false,'{"seq":20,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 텔레비전 사용 시간 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","13.3 × 2 = 26.6이에요.","1등 사용하지 않는 가전제품의 플러그 뽑기의 28.5그루보다 작아요 — 학생 수도 함께 봐야 해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#21','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 2.8 × 5.6 · 0.28 × 5.6 · 28 × 0.56 · 0.28 × 56',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":21,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 나머지 세 칸과 다른 칸은 어느 것인가요? 2.8 × 5.6 · 0.28 × 5.6 · 28 × 0.56 · 0.28 × 56","options":[{"t":"0.28 × 5.6","correct":true},{"t":"2.8 × 5.6","mis":"M5-2-u4-X20"},{"t":"28 × 0.56","mis":"M5-2-u4-X20"},{"t":"0.28 × 56","mis":"M5-2-u4-X20"}],"explanation":["곱의 소수점 위치의 규칙 — 자연수의 곱을 구한 다음 두 수의 소수점 아래 자릿수의 합만큼 소수점을 왼쪽으로 옮겨요.","2.8 × 5.6 = 15.68, 0.28 × 5.6 = 1.568, 28 × 0.56 = 15.68, 0.28 × 56 = 15.68이에요.","곱이 다른 칸은 0.28 × 5.6이에요 — 숫자가 비슷해도 소수점 위치가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#22','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C4',3,'mc','auto','높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X02','M5-2-u4-X18']::text[],false,'{"seq":22,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"19.2 cm","correct":true},{"t":"28.4 cm","mis":"M5-2-u4-X17"},{"t":"192 cm","mis":"M5-2-u4-X02"},{"t":"24 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.8 = 24(cm)예요.","두 번째 인형은 24 × 0.8 = 19.2(cm)예요.","그래서 19.2 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#23','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',4,'essay','teacher','1.7 × 5.31을 서로 다른 두 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용)으로 계산해 보세요. 곱이 소수 몇 자리 수인지와 그 까닭도 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"1.7 × 5.31을 서로 다른 두 가지 방법(분수의 곱셈 · 자연수의 곱셈 이용)으로 계산해 보세요. 곱이 소수 몇 자리 수인지와 그 까닭도 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨17/10⟩ × ⟨531/100⟩ = ⟨9027/1000⟩ = 9.027이다. 자연수로 — 17 × 531 = 9027이고 1.7은 17의 ⟨1/10⟩배, 5.31은 531의 ⟨1/100⟩배이므로 곱은 9027의 ⟨1/1000⟩배인 9.027이다. 소수 한 자리 수와 소수 두 자리 수의 곱이므로 1 + 2 = 3, 소수 세 자리 수이다.","scoring_points":["분수의 곱셈으로 9.027을 구했는가","17 × 531 = 9027의 ⟨1/1000⟩배로 9.027을 구했는가","자릿수 1 + 2 = 3으로 소수 세 자리라고 했는가"]},"explanation":["⟨17/10⟩ × ⟨531/100⟩ = ⟨9027/1000⟩이에요.","9027의 ⟨1/1000⟩배는 9.027이에요.","1 + 2 = 3 — 소수 세 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#24','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',4,'essay','teacher','다을이는 「25 × 11 = 275니까 0.25 × 1.1 = 2.75예요.」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048이에요.」라고 말했어요. 잘못 말한 친구를 찾고 이유를 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"다을이는 「25 × 11 = 275니까 0.25 × 1.1 = 2.75예요.」, 봄이는 「6 × 8 = 48이니까 0.06 × 0.8 = 0.048이에요.」라고 말했어요. 잘못 말한 친구를 찾고 이유를 써 보세요.","answer_guide":{"answer":"예: 잘못 말한 친구는 다을이다. 0.25 × 1.1은 소수 두 자리 수와 소수 한 자리 수의 곱이므로 소수점 아래 자릿수가 2 + 1 = 3인 소수 세 자리 수 0.275이다. 봄이는 48에서 소수점을 왼쪽으로 2 + 1 = 3자리 옮기고 빈 자리를 0으로 채워 0.048로 바르게 말했다.","scoring_points":["잘못 말한 친구를 다을이로 찾았는가","자릿수 2 + 1 = 3으로 곱이 소수 세 자리 수임을 밝혔는가","바른 곱 0.275를 구했는가"]},"explanation":["0.25는 두 자리, 1.1은 한 자리예요.","2 + 1 = 3 — 소수 세 자리 수예요.","바른 곱은 0.275 — 다을이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_b#25','math',5,2,'u4','','tb_g5_2_math_u4_review_b','unit_review','M5-2-u4-C9',4,'essay','teacher','민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C9","difficulty":4,"kind":"essay","stem":"민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 어림셈 — 2 × 15 = 30, 0.5 × 22 = 11, 1 × 16 = 16, 13 × 2 = 26이므로 플러그 뽑기가 가장 높을 것이다. 계산 — 1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이므로 가장 높은 방법은 플러그 뽑기(28.5그루)이다. 텔레비전 1시간 줄이기는 한 사람의 효과가 크지만 실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루로 플러그 뽑기보다 작다.","scoring_points":["어림셈으로 네 방법을 견주었는가","계산으로 플러그 뽑기 28.5그루가 가장 높음을 확인했는가","학생 수가 2명뿐이라 곱이 작다고 설명했는가"]},"explanation":["어림셈: 2 × 15 = 30이 가장 커요.","계산: 1.9 × 15 = 28.5 > 13.3 × 2 = 26.6이에요.","효과 × 학생 수로 견줘야 해요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#1','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C6',1,'mc','auto','1.5 × 0.7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],false,'{"seq":1,"concept":"M5-2-u4-C6","difficulty":1,"kind":"mc","stem":"1.5 × 0.7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨15/10⟩ × ⟨7/10⟩","correct":true},{"t":"⟨15/100⟩ × ⟨7/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/15⟩ × ⟨7/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨15/10⟩ × ⟨7/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.5 = ⟨15/10⟩ · 0.7 = ⟨7/10⟩이에요.","⟨15/10⟩ × ⟨7/10⟩ = ⟨105/100⟩ = 1.05예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#2','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',1,'mc','auto','9 × 0.28을 자연수의 곱셈 9 × 28 = 252를 이용해 계산하려고 해요. 9 × 0.28의 곱은 252의 몇 배인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X02','M5-2-u4-X10']::text[],false,'{"seq":2,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"9 × 0.28을 자연수의 곱셈 9 × 28 = 252를 이용해 계산하려고 해요. 9 × 0.28의 곱은 252의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"100배","mis":"M5-2-u4-X10"}],"explanation":["0.28은 28의 ⟨1/100⟩배예요.","그래서 곱은 252의 ⟨1/100⟩배예요.","9 × 0.28 = 2.52예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#3','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C7',1,'mc','auto','0.74 × 0.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"0.74 × 0.3을 계산하면 얼마인가요?","options":[{"t":"0.222","correct":true},{"t":"2.22","mis":"M5-2-u4-X03"},{"t":"222","mis":"M5-2-u4-X01"},{"t":"0.0222","mis":"M5-2-u4-X02"}],"explanation":["74 × 3 = 222예요.","0.74는 74의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","그래서 곱은 222의 ⟨1/1000⟩배인 0.222예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#4','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C3',1,'sa','auto','5.24 × 4를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u4-C3","difficulty":1,"kind":"sa","stem":"5.24 × 4를 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["소수점을 생각하지 않고 524 × 4 = 2096을 계산해요.","5.24의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","5.24 × 4 = 20.96 — ?는 9예요."],"mis":"M5-2-u4-X13","asset":{"type":"expr_grid","rows":[["","","5.","2","4"],["×","","","","4"],["","2","0.","?","6"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#5','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',1,'mc','auto','0.42 × 1.6과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"0.42 × 1.6과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"4.2 × 0.16","correct":true},{"t":"4.2 × 1.6","mis":"M5-2-u4-X20"},{"t":"420 × 0.016","mis":"M5-2-u4-X20"}],"explanation":["0.42 × 1.6 = 0.672예요.","4.2 × 0.16 = 0.672, 4.2 × 1.6 = 6.72, 420 × 0.016 = 6.72예요.","그래서 같은 것은 4.2 × 0.16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#6','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',1,'mc','auto','어림하여 계산 결과가 8보다 작은 식을 모두 고른 것은 어느 것인가요? 4의 2.1배 · 3 × 3.01 · 2의 3.98배',ARRAY['M5-2-u4-X07']::text[],false,'{"seq":6,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"어림하여 계산 결과가 8보다 작은 식을 모두 고른 것은 어느 것인가요? 4의 2.1배 · 3 × 3.01 · 2의 3.98배","options":[{"t":"2의 3.98배","correct":true},{"t":"4의 2.1배, 3 × 3.01","mis":"M5-2-u4-X07"},{"t":"4의 2.1배, 3 × 3.01, 2의 3.98배","mis":"M5-2-u4-X07"},{"t":"2의 3.98배, 4의 2.1배","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","2.1을 2로 어림하면 4 × 2 = 8 — 4의 2.1배는 8보다 커요 · 3.01을 3으로 어림하면 3 × 3 = 9 — 8보다 커요 · 3.98을 4로 어림하면 2 × 4 = 8 — 2의 3.98배는 8보다 작아요.","그래서 8보다 작은 식은 2의 3.98배 — 실제로 4 × 2.1 = 8.4, 3 × 3.01 = 9.03, 2 × 3.98 = 7.96."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#7','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C7',1,'mc','auto','계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ 7.5 × 3 · ㉡ 4 × 5.9 · ㉢ 3.6 × 6.8',ARRAY['M5-2-u4-X18','M5-2-u4-X13']::text[],false,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"계산 결과가 큰 것부터 차례로 기호를 쓴 것은 어느 것인가요? ㉠ 7.5 × 3 · ㉡ 4 × 5.9 · ㉢ 3.6 × 6.8","options":[{"t":"㉢, ㉡, ㉠","correct":true},{"t":"㉠, ㉡, ㉢","mis":"M5-2-u4-X18"},{"t":"㉠, ㉢, ㉡","mis":"M5-2-u4-X13"},{"t":"㉡, ㉠, ㉢","mis":"M5-2-u4-X13"}],"explanation":["세 식을 각각 계산해요.","7.5 × 3 = 22.5, 4 × 5.9 = 23.6, 3.6 × 6.8 = 24.48이에요.","24.48 > 23.6 > 22.5이므로 ㉢, ㉡, ㉠예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#8','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',1,'mc','auto','수박의 무게는 7 kg이에요. 호박의 무게가 수박의 0.69배라면 호박의 무게는 몇 kg인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"수박의 무게는 7 kg이에요. 호박의 무게가 수박의 0.69배라면 호박의 무게는 몇 kg인가요?","options":[{"t":"4.83 kg","correct":true},{"t":"7.69 kg","mis":"M5-2-u4-X17"},{"t":"483 kg","mis":"M5-2-u4-X01"},{"t":"48.3 kg","mis":"M5-2-u4-X02"}],"explanation":["「7 kg의 0.69배」는 7 × 0.69예요.","7 × 69 = 483이에요. 곱은 그 ⟨1/100⟩배예요.","7 × 0.69 = 4.83 — 4.83 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#9','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C2',2,'mc','auto','참기름이 한 병에 0.3 L씩 들어 있어요. 9병에 들어 있는 참기름은 모두 몇 L인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"참기름이 한 병에 0.3 L씩 들어 있어요. 9병에 들어 있는 참기름은 모두 몇 L인가요?","options":[{"t":"2.7 L","correct":true},{"t":"9.3 L","mis":"M5-2-u4-X17"},{"t":"27 L","mis":"M5-2-u4-X01"},{"t":"0.27 L","mis":"M5-2-u4-X02"}],"explanation":["같은 양 0.3 L가 9병 있으니 식은 0.3 × 9예요.","3 × 9 = 27이에요. 곱은 그 ⟨1/10⟩배예요.","0.3 × 9 = 2.7 — 2.7 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#10','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C4',2,'mc','auto','밑변의 길이가 7 cm, 높이가 4.6 cm인 평행사변형의 넓이는 몇 cm²인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":10,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"밑변의 길이가 7 cm, 높이가 4.6 cm인 평행사변형의 넓이는 몇 cm²인가요?","options":[{"t":"32.2 cm²","correct":true},{"t":"11.6 cm²","mis":"M5-2-u4-X17"},{"t":"322 cm²","mis":"M5-2-u4-X01"},{"t":"3.22 cm²","mis":"M5-2-u4-X02"}],"explanation":["평행사변형의 넓이 = 밑변의 길이 × 높이이므로 7 × 4.6이에요.","7 × 46 = 322예요. 곱은 그 ⟨1/10⟩배예요.","7 × 4.6 = 32.2 — 32.2 cm²예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#11','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',2,'mc','auto','13 × 26 = 338이에요. 1.3 × 0.26을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":11,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"13 × 26 = 338이에요. 1.3 × 0.26을 계산하면 얼마인가요?","options":[{"t":"0.338","correct":true},{"t":"3.38","mis":"M5-2-u4-X03"},{"t":"338","mis":"M5-2-u4-X01"},{"t":"0.0338","mis":"M5-2-u4-X02"}],"explanation":["1.3과 0.26의 소수점 아래 자릿수는 1개와 2개예요.","1 + 2 = 3 — 338에서 소수점을 왼쪽으로 세 자리 옮겨요.","1.3 × 0.26 = 0.338이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#12','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C6',2,'sa','auto','0.4 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u4-C6","difficulty":2,"kind":"sa","stem":"0.4 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["0.4는 0.1이 4개, 0.3은 0.1이 3개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 4 × 3 = 12개예요.","0.4 × 0.3 = 0.12예요."],"mis":"M5-2-u4-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#13','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C2',2,'mc','auto','4.3 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],false,'{"seq":13,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"4.3 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨43/10⟩ × 5","correct":true},{"t":"⟨43/100⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨1/43⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨43/10⟩ × ⟨5/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","4.3 = ⟨43/10⟩이에요.","⟨43/10⟩ × 5 = ⟨215/10⟩ = 21.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#14','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C2',2,'mc','auto','계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 0.9 × 4 ○ 3',ARRAY['M5-2-u4-X20','M5-2-u4-X18']::text[],false,'{"seq":14,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"계산 결과의 크기를 비교하여 ○ 안에 >, =, < 가운데 알맞은 것을 고르세요. 0.9 × 4 ○ 3","options":[{"t":">","correct":true},{"t":"<","mis":"M5-2-u4-X20"},{"t":"=","mis":"M5-2-u4-X18"}],"explanation":["두 식을 각각 계산해요.","0.9 × 4 = 3.6이에요.","3.6 > 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#15','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',2,'mc','auto','564 × 13 = 7332를 이용하여 □ 안에 알맞은 수를 구하세요. 5.64 × □ = 7.332',ARRAY['M5-2-u4-X01','M5-2-u4-X03','M5-2-u4-X11']::text[],false,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"564 × 13 = 7332를 이용하여 □ 안에 알맞은 수를 구하세요. 5.64 × □ = 7.332","options":[{"t":"1.3","correct":true},{"t":"13","mis":"M5-2-u4-X01"},{"t":"0.13","mis":"M5-2-u4-X03"},{"t":"130","mis":"M5-2-u4-X11"}],"explanation":["곱해지는 수 5.64는 소수 두 자리 수이고, 곱 7.332는 소수 세 자리 수예요.","그래서 □는 소수 한 자리 수 — 13의 ⟨1/10⟩배인 1.3이에요.","5.64 × 1.3 = 7.332예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#16','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',2,'mc','auto','8.15 × 1000을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],false,'{"seq":16,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"8.15 × 1000을 계산하면 얼마인가요?","options":[{"t":"8150","correct":true},{"t":"0.00815","mis":"M5-2-u4-X10"},{"t":"81500","mis":"M5-2-u4-X11"},{"t":"815","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","8.15 × 1000 = 8150이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#17','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',3,'mc','auto','4 × 0.24를 「4 × ⟨24/10⟩ = ⟨96/10⟩ = 9.6」으로 잘못 계산했어요. 잘못 계산한 곳과 바른 계산을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X13','M5-2-u4-X02','M5-2-u4-X06']::text[],false,'{"seq":17,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"4 × 0.24를 「4 × ⟨24/10⟩ = ⟨96/10⟩ = 9.6」으로 잘못 계산했어요. 잘못 계산한 곳과 바른 계산을 바르게 말한 것은 어느 것인가요?","options":[{"t":"0.24를 ⟨24/10⟩로 나타냈다 — 4 × ⟨24/100⟩ = ⟨96/100⟩ = 0.96","correct":true},{"t":"4 × 24를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"⟨96/10⟩을 소수로 잘못 나타냈다 — 96","mis":"M5-2-u4-X02"},{"t":"바르게 계산했다 — 곱하면 커진다","mis":"M5-2-u4-X06"}],"explanation":["소수 두 자리 수는 분모가 100인 분수예요 — 0.24 = ⟨24/100⟩예요.","4 × ⟨24/100⟩ = ⟨96/100⟩ = 0.96이에요.","0.24가 1보다 작으니 곱은 4보다 작아야 해요 — 9.6은 너무 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#18','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',3,'mc','auto','용희는 매일 1시간 15분씩 수영을 했어요. 8일 동안 용희가 수영을 한 시간은 모두 몇 시간인지 소수의 곱셈을 이용하여 구하면 어느 것인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X02','M5-2-u4-X18']::text[],false,'{"seq":18,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"용희는 매일 1시간 15분씩 수영을 했어요. 8일 동안 용희가 수영을 한 시간은 모두 몇 시간인지 소수의 곱셈을 이용하여 구하면 어느 것인가요?","options":[{"t":"10시간","correct":true},{"t":"9.2시간","mis":"M5-2-u4-X16"},{"t":"92시간","mis":"M5-2-u4-X02"},{"t":"8.75시간","mis":"M5-2-u4-X18"}],"explanation":["15분은 1시간의 ⟨15/60⟩ = ⟨1/4⟩ — 0.25시간이에요.","1시간 15분 = 1.25시간이에요.","1.25 × 8 = 10 — 모두 10시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#19','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C6',3,'sa','auto','10.9 × 0.2 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u4-C6","difficulty":3,"kind":"sa","stem":"10.9 × 0.2 < □에서 □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["109 × 2 = 218이고 곱은 그 ⟨1/100⟩배 — 10.9 × 0.2 = 2.18이에요.","2.18 < □이므로 2는 안 되고 3은 돼요.","가장 작은 자연수는 3이에요."],"mis":"M5-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#20','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 재활용이 가능한 유리병, 캔 등 분리배출하기는 실천한 학생이 22명으로 가장 많은데, 반 전체 효과는 22그루보다 적어요. 그 까닭은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X14']::text[],false,'{"seq":20,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 재활용이 가능한 유리병, 캔 등 분리배출하기는 실천한 학생이 22명으로 가장 많은데, 반 전체 효과는 22그루보다 적어요. 그 까닭은 무엇인가요?","options":[{"t":"한 사람의 효과 0.4그루가 1보다 작아 곱이 22보다 작기 때문","correct":true},{"t":"22가 가장 큰 수라서","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못해서","mis":"M5-2-u4-X14"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"}],"explanation":["반 전체 효과는 0.4 × 22예요.","곱하는 수 0.4가 1보다 작으면 곱은 22보다 작아요.","0.4 × 22 = 8.8 — 22보다 작아요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#21','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 작은 칸은 어느 것인가요? 0.14 × 0.01 · 3.65 × 0.01 · 0.5 × 0.22 · 36.5 × 0.01',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":21,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 작은 칸은 어느 것인가요? 0.14 × 0.01 · 3.65 × 0.01 · 0.5 × 0.22 · 36.5 × 0.01","options":[{"t":"0.14 × 0.01","correct":true},{"t":"3.65 × 0.01","mis":"M5-2-u4-X20"},{"t":"0.5 × 0.22","mis":"M5-2-u4-X20"},{"t":"36.5 × 0.01","mis":"M5-2-u4-X20"}],"explanation":["곱하는 수가 0.01이면 소수점이 왼쪽으로 두 자리, 10배씩 커지면 오른쪽으로 옮겨져요.","0.14 × 0.01 = 0.0014, 3.65 × 0.01 = 0.0365, 0.5 × 0.22 = 0.11, 36.5 × 0.01 = 0.365예요.","소수점 위치를 기준으로 견주면 가장 작은 곱은 0.14 × 0.01 = 0.0014예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#22','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',3,'mc','auto','수 카드 6, 1, 5, 8, 3 가운데 2장을 한 번씩만 이용하여 소수 한 자리 수를 만들려고 해요. 만들 수 있는 수 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X18','M5-2-u4-X01']::text[],false,'{"seq":22,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"수 카드 6, 1, 5, 8, 3 가운데 2장을 한 번씩만 이용하여 소수 한 자리 수를 만들려고 해요. 만들 수 있는 수 가운데 가장 큰 수와 가장 작은 수의 곱은 얼마인가요?","options":[{"t":"11.18","correct":true},{"t":"111.8","mis":"M5-2-u4-X03"},{"t":"26.66","mis":"M5-2-u4-X18"},{"t":"1118","mis":"M5-2-u4-X01"}],"explanation":["가장 큰 소수 한 자리 수는 큰 카드 8, 6으로 만든 8.6이에요.","가장 작은 소수 한 자리 수는 작은 카드 1, 3으로 만든 1.3이에요.","8.6 × 1.3 = 11.18이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#23','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C7',4,'essay','teacher','해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩ = 0.141이다. 자연수로 — 47 × 3 = 141이고 0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배이므로 곱은 141의 ⟨1/1000⟩배인 0.141이다. 소수 두 자리 수와 한 자리 수를 곱했으므로 곱은 2 + 1 = 3, 소수 세 자리 수이다. 물고기 인형은 0.141 m이다.","scoring_points":["분수의 곱셈으로 0.141을 구했는가","자연수의 곱셈과 ⟨1/1000⟩배로 0.141을 구했는가","소수점 아래 자릿수 2 + 1 = 3이라고 설명했는가"]},"explanation":["⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩이에요.","141의 ⟨1/1000⟩배는 0.141이에요.","2 + 1 = 3 — 소수 세 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#24','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C6',4,'essay','teacher','75.9 × 0.6을 455.4로 잘못 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"75.9 × 0.6을 455.4로 잘못 계산했어요. 잘못 계산한 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 759 × 6 = 4554이고 75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배이므로 75.9 × 0.6은 4554의 ⟨1/100⟩배인 45.54이다. 455.4는 한 수의 소수점 아래 자릿수만 생각해 4554의 ⟨1/10⟩배로 계산한 것이다. 0.6이 1보다 작으므로 곱은 75.9보다 작아야 하는데 455.4는 75.9보다 커서 틀렸다.","scoring_points":["두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배라고 설명했는가","바른 곱 45.54를 구했는가","어림(0.6 < 1)로 455.4가 틀렸음을 밝혔는가"]},"explanation":["759 × 6 = 4554예요.","곱은 4554의 ⟨1/100⟩배 — 45.54예요.","0.6 < 1이니 곱은 75.9보다 작아야 해요."],"asset":{"type":"expr_grid","rows":[["","","7","5.","9"],["×","","","0.","6"],["","4","5","5.","4"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_c#25','math',5,2,'u4','','tb_g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',4,'essay','teacher','떨어진 높이의 0.6배만큼 튀어 오르는 공이 있어요. 높이가 2 m인 곳에서 이 공을 떨어뜨렸을 때 두 번째로 튀어 오른 공의 높이는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"떨어진 높이의 0.6배만큼 튀어 오르는 공이 있어요. 높이가 2 m인 곳에서 이 공을 떨어뜨렸을 때 두 번째로 튀어 오른 공의 높이는 몇 m인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 첫 번째로 튀어 오른 높이는 떨어진 높이 2 m의 0.6배이므로 2 × 0.6 = 1.2(m)이다. 두 번째로 튀어 오른 높이는 1.2 m의 0.6배이므로 1.2 × 0.6 = 0.72(m)이다. 두 번째로 튀어 오른 공의 높이는 0.72 m이다.","scoring_points":["첫 번째 높이 2 × 0.6 = 1.2(m)를 구했는가","두 번째 높이를 1.2 × 0.6으로 세웠는가","0.72 m를 구했는가"]},"explanation":["2 × 0.6 = 1.2(m)예요.","1.2 × 0.6 = 0.72(m)예요.","두 번째는 0.72 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#1','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',1,'mc','auto','2.33 × 1.7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],false,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"2.33 × 1.7을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨233/100⟩ × ⟨17/10⟩","correct":true},{"t":"⟨233/1000⟩ × ⟨17/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/233⟩ × ⟨17/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨233/100⟩ × ⟨17/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","2.33 = ⟨233/100⟩ · 1.7 = ⟨17/10⟩이에요.","⟨233/100⟩ × ⟨17/10⟩ = ⟨3961/1000⟩ = 3.961이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#2','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',1,'mc','auto','0.59 × 4를 자연수의 곱셈 59 × 4 = 236을 이용해 계산하려고 해요. 0.59 × 4의 곱은 236의 몇 배인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X02','M5-2-u4-X10']::text[],false,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"0.59 × 4를 자연수의 곱셈 59 × 4 = 236을 이용해 계산하려고 해요. 0.59 × 4의 곱은 236의 몇 배인가요?","options":[{"t":"⟨1/100⟩배","correct":true},{"t":"⟨1/10⟩배","mis":"M5-2-u4-X03"},{"t":"⟨1/1000⟩배","mis":"M5-2-u4-X02"},{"t":"100배","mis":"M5-2-u4-X10"}],"explanation":["0.59는 59의 ⟨1/100⟩배예요.","그래서 곱은 236의 ⟨1/100⟩배예요.","0.59 × 4 = 2.36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#3','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',1,'mc','auto','2.4 × 1.32를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"2.4 × 1.32를 계산하면 얼마인가요?","options":[{"t":"3.168","correct":true},{"t":"31.68","mis":"M5-2-u4-X03"},{"t":"3168","mis":"M5-2-u4-X01"},{"t":"0.3168","mis":"M5-2-u4-X02"}],"explanation":["24 × 132 = 3168이에요.","2.4는 24의 ⟨1/10⟩배, 1.32는 132의 ⟨1/100⟩배예요.","그래서 곱은 3168의 ⟨1/1000⟩배인 3.168이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#4','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C5',1,'sa','auto','12 × 0.83을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"12 × 0.83을 세로로 계산했어요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["소수점을 생각하지 않고 12 × 83 = 996을 계산해요.","0.83의 소수점 아래 자릿수가 2개이므로 곱도 소수점 아래 2자리예요.","12 × 0.83 = 9.96 — ?는 6이에요."],"mis":"M5-2-u4-X13","asset":{"type":"expr_grid","rows":[["","","1","2"],["×","0.","8","3"],["","9.","9","?"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#5','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',1,'mc','auto','□ 안에 알맞은 수가 0.01인 식은 어느 것인가요? 79 × □ = 0.079 · 790 × □ = 7.9',ARRAY['M5-2-u4-X11']::text[],false,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"□ 안에 알맞은 수가 0.01인 식은 어느 것인가요? 79 × □ = 0.079 · 790 × □ = 7.9","options":[{"t":"790 × □ = 7.9","correct":true},{"t":"79 × □ = 0.079","mis":"M5-2-u4-X11"},{"t":"두 식 모두","mis":"M5-2-u4-X11"}],"explanation":["79 → 0.079는 소수점이 왼쪽으로 세 자리 — □는 0.001이에요.","790 → 7.9는 소수점이 왼쪽으로 두 자리 — □는 0.01이에요.","그래서 790 × 0.01 = 7.9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#6','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',1,'mc','auto','어림하여 계산 결과가 6보다 큰 식을 모두 고른 것은 어느 것인가요? 2.9 × 2 · 2.03 × 3 · 1.39 × 4',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],false,'{"seq":6,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"어림하여 계산 결과가 6보다 큰 식을 모두 고른 것은 어느 것인가요? 2.9 × 2 · 2.03 × 3 · 1.39 × 4","options":[{"t":"2.03 × 3","correct":true},{"t":"2.9 × 2, 1.39 × 4","mis":"M5-2-u4-X06"},{"t":"2.9 × 2, 2.03 × 3, 1.39 × 4","mis":"M5-2-u4-X07"},{"t":"2.03 × 3, 2.9 × 2","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수를 계산하기 쉬운 수로 바꾸어 어림해요.","2.9를 3으로 어림하면 3 × 2 = 6 — 2.9 × 2는 6보다 작아요 · 2.03을 2로 어림하면 2 × 3 = 6 — 2.03 × 3은 6보다 커요 · 1.39를 1.4로 어림하면 1.4 × 4 = 5.6 — 1.39 × 4는 6보다 작아요.","그래서 6보다 큰 식은 2.03 × 3 — 실제로 2.9 × 2 = 5.8, 2.03 × 3 = 6.09, 1.39 × 4 = 5.56."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#7','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',1,'mc','auto','아리 「87 × 0.3」, 소명 「870 × 0.03」, 승연 「8.7 × 0.3」 가운데 계산 결과가 가장 작은 식을 말한 친구는 누구인가요?',ARRAY['M5-2-u4-X20']::text[],false,'{"seq":7,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"아리 「87 × 0.3」, 소명 「870 × 0.03」, 승연 「8.7 × 0.3」 가운데 계산 결과가 가장 작은 식을 말한 친구는 누구인가요?","options":[{"t":"승연","correct":true},{"t":"아리","mis":"M5-2-u4-X20"},{"t":"소명","mis":"M5-2-u4-X20"},{"t":"세 친구의 식이 모두 같다","mis":"M5-2-u4-X20"}],"explanation":["식을 각각 계산하고 소수점 위치를 기준으로 견주어요.","87 × 0.3 = 26.1, 870 × 0.03 = 26.1, 8.7 × 0.3 = 2.61이에요.","가장 작은 것은 승연예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#8','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',1,'mc','auto','연수의 키는 1.45 m이고, 강당의 높이는 연수 키의 3배예요. 강당의 높이는 몇 m인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":8,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"연수의 키는 1.45 m이고, 강당의 높이는 연수 키의 3배예요. 강당의 높이는 몇 m인가요?","options":[{"t":"4.35 m","correct":true},{"t":"4.45 m","mis":"M5-2-u4-X17"},{"t":"435 m","mis":"M5-2-u4-X01"},{"t":"43.5 m","mis":"M5-2-u4-X02"}],"explanation":["「1.45 m의 3배」는 1.45 × 3이에요.","145 × 3 = 435예요. 곱은 그 ⟨1/100⟩배예요.","1.45 × 3 = 4.35 — 4.35 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#9','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C2',2,'mc','auto','우유가 한 병에 0.9 L씩 들어 있어요. 8병에 들어 있는 우유는 모두 몇 L인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"우유가 한 병에 0.9 L씩 들어 있어요. 8병에 들어 있는 우유는 모두 몇 L인가요?","options":[{"t":"7.2 L","correct":true},{"t":"8.9 L","mis":"M5-2-u4-X17"},{"t":"72 L","mis":"M5-2-u4-X01"},{"t":"0.72 L","mis":"M5-2-u4-X02"}],"explanation":["같은 양 0.9 L가 8병 있으니 식은 0.9 × 8이에요.","9 × 8 = 72예요. 곱은 그 ⟨1/10⟩배예요.","0.9 × 8 = 7.2 — 7.2 L예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#10','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',2,'mc','auto','한 변의 길이가 3.84 cm인 정육각형의 둘레는 몇 cm인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X02']::text[],false,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"한 변의 길이가 3.84 cm인 정육각형의 둘레는 몇 cm인가요?","options":[{"t":"23.04 cm","correct":true},{"t":"2304 cm","mis":"M5-2-u4-X01"},{"t":"9.84 cm","mis":"M5-2-u4-X05"},{"t":"2.304 cm","mis":"M5-2-u4-X02"}],"explanation":["정육각형은 6개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 6이에요.","3.84 × 6 = 23.04 — 둘레는 23.04 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#11','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',2,'mc','auto','21 × 586 = 12306이에요. 0.21 × 58.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":11,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"21 × 586 = 12306이에요. 0.21 × 58.6을 계산하면 얼마인가요?","options":[{"t":"12.306","correct":true},{"t":"123.06","mis":"M5-2-u4-X03"},{"t":"12306","mis":"M5-2-u4-X01"},{"t":"1.2306","mis":"M5-2-u4-X02"}],"explanation":["0.21과 58.6의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 12306에서 소수점을 왼쪽으로 세 자리 옮겨요.","0.21 × 58.6 = 12.306이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#12','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C6',2,'sa','auto','1.5 × 0.7의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u4-C6","difficulty":2,"kind":"sa","stem":"1.5 × 0.7의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["1.5는 0.1이 15개, 0.7은 0.1이 7개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 15 × 7 = 105개예요.","1.5 × 0.7 = 1.05예요."],"mis":"M5-2-u4-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#13','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C2',2,'mc','auto','0.7 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],false,'{"seq":13,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"0.7 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × 4","correct":true},{"t":"⟨7/100⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/7⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨7/10⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.7 = ⟨7/10⟩이에요.","⟨7/10⟩ × 4 = ⟨28/10⟩ = 2.8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#14','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C4',2,'mc','auto','두 식 가운데 계산 결과가 10보다 작은 것은 어느 것인가요? 5 × 2.14 · 4 × 2.3',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],false,'{"seq":14,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"두 식 가운데 계산 결과가 10보다 작은 것은 어느 것인가요? 5 × 2.14 · 4 × 2.3","options":[{"t":"4 × 2.3","correct":true},{"t":"5 × 2.14","mis":"M5-2-u4-X06"},{"t":"두 식 모두 10보다 작다","mis":"M5-2-u4-X07"}],"explanation":["5 × 2 = 10이고 2.14는 2보다 크니 5 × 2.14는 10보다 커요.","4 × 2.5 = 10이고 2.3은 2.5보다 작으니 4 × 2.3은 10보다 작아요.","실제로 5 × 2.14 = 10.7, 4 × 2.3 = 9.2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#15','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',2,'mc','auto','354 × 0.01을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],false,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"354 × 0.01을 계산하면 얼마인가요?","options":[{"t":"3.54","correct":true},{"t":"35400","mis":"M5-2-u4-X10"},{"t":"0.354","mis":"M5-2-u4-X11"},{"t":"35.4","mis":"M5-2-u4-X11"}],"explanation":["0.01을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.01은 소수 두 자리 수 — 왼쪽으로 두 자리예요.","354 × 0.01 = 3.54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#16','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',2,'mc','auto','31 × 0.001을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],false,'{"seq":16,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"31 × 0.001을 계산하면 얼마인가요?","options":[{"t":"0.031","correct":true},{"t":"31000","mis":"M5-2-u4-X10"},{"t":"0.0031","mis":"M5-2-u4-X11"},{"t":"0.31","mis":"M5-2-u4-X11"}],"explanation":["0.001을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.001은 소수 세 자리 수 — 왼쪽으로 세 자리예요.","31 × 0.001 = 0.031이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#17','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',3,'mc','auto','1.35 × 4를 세로로 계산한 것이에요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X13','M5-2-u4-X04']::text[],false,'{"seq":17,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"1.35 × 4를 세로로 계산한 것이에요. 잘못 계산한 까닭과 바른 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 5.4이다","correct":true},{"t":"135 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["1.35는 1보다 크므로 곱은 1 × 4 = 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배이므로 곱은 5.40이에요.","바른 곱은 5.4 — 0.540은 ⟨1/10⟩배 더 작게 쓴 거예요."],"asset":{"type":"expr_grid","rows":[["","","1.","3","5"],["×","","","","4"],["","0.","5","4","0"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#18','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C5',3,'mc','auto','고속 열차가 간 거리를 소수의 곱셈으로 구하려고 해요. 1시간 30분을 시간 단위의 소수로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X18']::text[],false,'{"seq":18,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"고속 열차가 간 거리를 소수의 곱셈으로 구하려고 해요. 1시간 30분을 시간 단위의 소수로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1.5시간","correct":true},{"t":"1.3시간","mis":"M5-2-u4-X16"},{"t":"1.03시간","mis":"M5-2-u4-X16"},{"t":"0.5시간","mis":"M5-2-u4-X18"}],"explanation":["1시간은 60분이에요.","30분은 1시간의 ⟨30/60⟩ = ⟨1/2⟩ — 0.5시간이에요.","1시간 30분 = 1 + 0.5 = 1.5(시간)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#19','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',3,'sa','auto','9.4 × 3.61 < □ < 7.13 × 5.5에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u4-C7","difficulty":3,"kind":"sa","stem":"9.4 × 3.61 < □ < 7.13 × 5.5에서 □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["9.4 × 3.61 = 33.934, 7.13 × 5.5 = 39.215예요.","33.934 < □ < 39.215이므로 □는 34부터 39까지예요 — 33과 40은 안 돼요.","34, 35, 36, 37, 38, 39 — 모두 6개예요."],"mis":"M5-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#20','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X15','M5-2-u4-X02']::text[],false,'{"seq":20,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표예요(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수). 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?","options":[{"t":"19.7그루","correct":true},{"t":"37.3그루","mis":"M5-2-u4-X18"},{"t":"1.5그루","mis":"M5-2-u4-X15"},{"t":"197그루","mis":"M5-2-u4-X02"}],"explanation":["가장 높은 방법은 사용하지 않는 가전제품의 플러그 뽑기 28.5그루예요.","가장 낮은 방법은 재활용이 가능한 유리병, 캔 등 분리배출하기 8.8그루예요.","28.5 − 8.8 = 19.7(그루)예요."],"asset":{"type":"expr_grid","rows":[["실천 방법","나무 심는 효과","학생 수"],["사용하지 않는 가전제품의 플러그 뽑기","연간 1.9그루","15명"],["재활용이 가능한 유리병, 캔 등 분리배출하기","연간 0.4그루","22명"],["비닐봉지 대신 장바구니 사용하기","연간 1.2그루","16명"],["텔레비전 사용 시간 1시간 줄이기","연간 13.3그루","2명"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#21','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',3,'mc','auto','사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 큰 칸은 어느 것인가요? 12 × 16.6 · 30 × 5.3 · 1.5 × 80 · 40 × 10.2',ARRAY['M5-2-u4-X07']::text[],false,'{"seq":21,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"사각사각 사목 놀이판의 네 칸이에요. 곱이 가장 큰 칸은 어느 것인가요? 12 × 16.6 · 30 × 5.3 · 1.5 × 80 · 40 × 10.2","options":[{"t":"40 × 10.2","correct":true},{"t":"12 × 16.6","mis":"M5-2-u4-X07"},{"t":"30 × 5.3","mis":"M5-2-u4-X07"},{"t":"1.5 × 80","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 0.01이면 소수점이 왼쪽으로 두 자리, 10배씩 커지면 오른쪽으로 옮겨져요.","12 × 16.6 = 199.2, 30 × 5.3 = 159, 1.5 × 80 = 120, 40 × 10.2 = 408이에요.","소수점 위치를 기준으로 견주면 가장 큰 곱은 40 × 10.2 = 408이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#22','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C5',3,'mc','auto','수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],false,'{"seq":22,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"29.58","correct":true},{"t":"2958","mis":"M5-2-u4-X01"},{"t":"295.8","mis":"M5-2-u4-X02"},{"t":"2.958","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 87이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.34가 돼요.","87 × 0.34 = 29.58이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#23','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C6',4,'essay','teacher','가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.","answer_guide":{"answer":"예: 넓이 1인 정사각형을 가로·세로 10칸씩 나누면 모두 100칸이고 한 칸의 넓이는 ⟨1/100⟩ = 0.01이다. 가로 6칸, 세로 9칸을 칠하면 6 × 9 = 54칸이다. 0.01이 54칸이므로 0.6 × 0.9 = 0.54이고 벽화의 넓이는 0.54 m²이다.","scoring_points":["한 칸의 넓이가 0.01임을 밝혔는가","칠한 칸 6 × 9 = 54칸을 구했는가","0.54 m²를 구했는가"]},"explanation":["100칸 중의 1칸 — 한 칸은 0.01이에요.","6 × 9 = 54칸이에요.","0.6 × 0.9 = 0.54(m²)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#24','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',4,'essay','teacher','어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.","answer_guide":{"answer":"예: 1.35는 1보다 크므로 1.35 × 4는 1 × 4 = 4보다 커야 하는데 0.540은 4보다 작아 틀렸다. 135 × 4 = 540이고 1.35는 135의 ⟨1/100⟩배이므로 곱은 540의 ⟨1/100⟩배인 5.40이다. 끝자리 0은 생략하여 5.4로 쓸 수 있다.","scoring_points":["곱이 4보다 커야 한다고 어림으로 설명했는가","135 × 4 = 540의 ⟨1/100⟩배로 5.40을 구했는가","끝자리 0을 생략해 5.4로 쓸 수 있다고 했는가"]},"explanation":["1 × 4 = 4보다 커야 해요.","540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략해 5.4로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u4_review_d#25','math',5,2,'u4','','tb_g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',4,'essay','teacher','고무나무의 높이는 25.2 cm이고 몬스테라는 고무나무의 1.4배예요. 몬스테라의 높이를 어림하여 먼저 말하고, 계산하여 구한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"고무나무의 높이는 25.2 cm이고 몬스테라는 고무나무의 1.4배예요. 몬스테라의 높이를 어림하여 먼저 말하고, 계산하여 구한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 25.2를 25로, 1.4를 1.5쯤으로 보면 몬스테라는 25.2 cm보다 크고 25 × 1.5 = 37.5보다 조금 작은 정도이다. 252 × 14 = 3528이고 곱은 그 ⟨1/100⟩배이므로 25.2 × 1.4 = 35.28이다. 몬스테라의 높이는 35.28 cm로 어림한 크기와 비슷하다.","scoring_points":["1.4가 1보다 커서 25.2 cm보다 크다는 등 어림했는가","25.2 × 1.4 = 35.28을 구했는가","어림한 값과 견주었는가"]},"explanation":["1.4 > 1 — 25.2 cm보다 커요.","252 × 14 = 3528의 ⟨1/100⟩배는 35.28이에요.","35.28 cm — 어림과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
